export function createBuildchainLayoutDiscovery({
  cwd = process.cwd(),
  buildchainVersion = "",
} = {}) {
  const resolvedCwd = path.resolve(cwd);
  const configPath = resolveBuildchainConfigPath(resolvedCwd);
  const kfd3RegistryPath = resolveKfd3SurfaceRegistryPath(resolvedCwd);
  return {
    schemaVersion: 1,
    contract: BUILDCHAIN_LAYOUT_DISCOVERY_CONTRACT,
    buildchain: {
      version: String(buildchainVersion || ""),
      versionPinPath: BUILDCHAIN_VERSION_PIN_PATH,
    },
    repository: {
      root: resolvedCwd,
      managed: fs.existsSync(repoPath(resolvedCwd, configPath))
        || fs.existsSync(repoPath(resolvedCwd, BUILDCHAIN_VERSION_PIN_PATH))
        || fs.existsSync(repoPath(resolvedCwd, kfd3RegistryPath)),
      configPath,
    },
    kfd: {
      root: BUILDCHAIN_KFD_ROOT,
      registries: {
        "kfd-3": {
          standard: "kfd-3",
          schemaVersion: 1,
          path: kfd3RegistryPath,
          canonicalPath: BUILDCHAIN_KFD3_SURFACE_REGISTRY_PATH,
          exists: fs.existsSync(repoPath(resolvedCwd, kfd3RegistryPath)),
        },
      },
    },
    shifu: {
      jurisdiction: {
        source: "kfd-3-distribution-declaration",
        registryStandard: "kfd-3",
        field: "surfaces[].distribution.registrar",
        value: "shifu",
      },
    },
  };
}

export function discoverBuildchainRepoFiles(cwd = process.cwd()) {
  const files = [
    {
      kind: "config",
      canonical: BUILDCHAIN_CONFIG_PATH,
      legacy: LEGACY_BUILDCHAIN_CONFIG_PATH,
      tracked: true,
    },
    {
      kind: "contract-lock",
      canonical: BUILDCHAIN_CONTRACT_LOCK_PATH,
      legacy: LEGACY_BUILDCHAIN_CONTRACT_LOCK_PATH,
      tracked: true,
    },
    {
      kind: "kfd-3-surface-registry",
      canonical: BUILDCHAIN_KFD3_SURFACE_REGISTRY_PATH,
      legacy: LEGACY_BUILDCHAIN_KFD3_SURFACE_REGISTRY_PATHS,
      tracked: true,
    },
    {
      kind: "kfd-1-contract-world-witness",
      canonical: BUILDCHAIN_KFD1_CONTRACT_WORLD_WITNESS_PATH,
      legacy: [
        ".buildchain/kfd-1/contract-world.witness.json",
        ".buildchain/kfd/buildchain-kfd-1-witness.json",
      ],
      tracked: true,
    },
    {
      kind: "kfd-1-release-gate",
      canonical: BUILDCHAIN_KFD1_RELEASE_GATE_PATH,
      legacy: [".buildchain/kfd-1/release-gate.json"],
      tracked: true,
    },
    {
      kind: "kfd-1-verify-result",
      canonical: BUILDCHAIN_KFD1_VERIFY_RESULT_PATH,
      legacy: [".buildchain/kfd-1/verify-result.json"],
      tracked: false,
    },
    {
      kind: "kfd-2-product-claims-registry",
      canonical: BUILDCHAIN_KFD2_REGISTRY_PATH,
      legacy: [],
      tracked: true,
    },
    {
      kind: "kfd-2-release-claims",
      canonical: BUILDCHAIN_KFD2_RELEASE_CLAIMS_PATH,
      legacy: [
        ".buildchain/kfd-2/release-claims.json",
        ".buildchain/kfd-2/public-release-trust.claim.json",
      ],
      tracked: true,
    },
    {
      kind: "kfd-2-claim-args",
      canonical: BUILDCHAIN_KFD2_CLAIM_ARGS_PATH,
      legacy: [".buildchain/kfd-2/buildchain-claim-args.txt"],
      tracked: true,
    },
    {
      kind: "kfd-2-claims",
      canonical: BUILDCHAIN_KFD2_CLAIMS_DIR,
      legacy: [".buildchain/kfd/kfd-2-claims", ".buildchain/kfd-2/claims"],
      tracked: false,
    },
    {
      kind: "kfd-3-collaboration-interface",
      canonical: BUILDCHAIN_KFD3_COLLABORATION_INTERFACE_PATH,
      legacy: [".buildchain/kfd-3/collaboration-interface.json"],
      tracked: true,
    },
    {
      kind: "kfd-3-prebuild-witness",
      canonical: BUILDCHAIN_KFD3_PREBUILD_WITNESS_PATH,
      legacy: [
        ".buildchain/kfd-3/collaboration-interface.prebuild.json",
        ".buildchain/kfd/buildchain-kfd-3-prebuild-witness.json",
      ],
      tracked: true,
    },
    {
      kind: "kfd-3-artifact-witness",
      canonical: BUILDCHAIN_KFD3_ARTIFACT_WITNESS_PATH,
      legacy: [
        ".buildchain/kfd-3/collaboration-interface.artifact.json",
        ".buildchain/kfd/buildchain-kfd-3-artifact-witness.json",
      ],
      tracked: true,
    },
    {
      kind: "kfd-3-capability-query",
      canonical: BUILDCHAIN_KFD3_CAPABILITY_QUERY_PATH,
      legacy: [".buildchain/kfd-3/capability-query.json"],
      tracked: true,
    },
    {
      kind: "release-passport",
      canonical: BUILDCHAIN_RELEASE_PASSPORT_PATH,
      legacy: LEGACY_BUILDCHAIN_RELEASE_PASSPORT_PATH,
      tracked: false,
    },
  ];
  return files.map((entry) => {
    const canonicalExists = fs.existsSync(repoPath(cwd, entry.canonical));
    const legacyPaths = Array.isArray(entry.legacy) ? entry.legacy : [entry.legacy].filter(Boolean);
    const existingLegacyPaths = legacyPaths.filter((legacy) => fs.existsSync(repoPath(cwd, legacy)));
    const legacyExists = existingLegacyPaths.length > 0;
    return {
      ...entry,
      legacy: legacyPaths,
      canonicalExists,
      legacyExists,
      existingLegacyPaths,
      activePath: canonicalExists ? entry.canonical : legacyExists ? existingLegacyPaths[0] : entry.canonical,
      migrationNeeded: !canonicalExists && legacyExists,
    };
  });
}

export function planBuildchainLayoutMigration({ cwd = process.cwd() } = {}) {
  const entries = discoverBuildchainRepoFiles(cwd);
  const moves = entries
    .filter((entry) => entry.migrationNeeded)
    .flatMap((entry) => entry.existingLegacyPaths.map((legacy) => ({
      kind: entry.kind,
      from: legacy,
      to: entry.canonical,
      tracked: entry.tracked,
    })));
  return {
    schemaVersion: 1,
    contract: "kungfu-buildchain-repository-layout-migration",
    cwd: path.resolve(cwd),
    canonicalRoot: BUILDCHAIN_DIR,
    status: moves.length > 0 ? "migration-needed" : "current",
    files: entries,
    generatedDirs: BUILDCHAIN_GENERATED_DIRS,
    moves,
  };
}

export function migrateBuildchainLayout({ cwd = process.cwd(), write = false, force = false } = {}) {
  const plan = planBuildchainLayoutMigration({ cwd });
  const applied = [];
  if (write) {
    for (const move of plan.moves) {
      const from = repoPath(cwd, move.from);
      const to = repoPath(cwd, move.to);
      if (fs.existsSync(to) && !force) {
        throw new Error(`${move.to} already exists; pass --force to overwrite`);
      }
      fs.mkdirSync(path.dirname(to), { recursive: true });
      fs.renameSync(from, to);
      applied.push(move);
    }
  }
  return {
    ...plan,
    write,
    force,
    status: write && applied.length === plan.moves.length ? "applied" : plan.status,
    applied,
  };
}

import { execFileSync } from "node:child_process";
import crypto from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import {
  discoverConfiguredVersionStateFiles,
  getNativeDiagnosticsProfile,
  getLifecycleStage,
  getPublishContract,
  getVersionStrategy,
  loadBuildchainConfig,
  loadConfiguredAnchorManifest,
  validateBuildchainConfig,
} from "./buildchain-config.js";
import { detectPackageManager, getWorkspaceInfo } from "./package-manager.js";
import {
  BUILDCHAIN_LOG_EVENT_CONTRACT,
  readBuildchainLogEvents,
  summarizeBuildchainLogEvents,
} from "./logging.js";

export const BUILDCHAIN_DIAGNOSTICS_CONTRACT = "kungfu-buildchain-diagnostics";
export const BUILDCHAIN_LIFECYCLE_OBSERVABILITY_CONTRACT =
  "kungfu-buildchain-lifecycle-observability";
export const BUILDCHAIN_ANCHORED_PACKAGE_RELEASE_VALIDATION_CONTRACT =
  "kungfu-buildchain-anchored-package-release-validation";
export const BUILDCHAIN_DIAGNOSTICS_MANIFEST_CONTRACT =
  "kungfu-buildchain-diagnostics-manifest";
export const BUILDCHAIN_DIAGNOSTICS_SUMMARY_CONTRACT =
  "kungfu-buildchain-diagnostics-summary";
export const BUILDCHAIN_PROCESS_SAMPLE_REPORT_CONTRACT =
  "kungfu-buildchain-process-sample-report";
export const BUILDCHAIN_PROCESS_SAMPLE_SUMMARY_CONTRACT =
  "kungfu-buildchain-process-sample-summary";
export const BUILDCHAIN_LOCKED_SOURCE_CHECKOUT_CONTRACT =
  "kungfu-buildchain-locked-source-checkout-cache";

const DEFAULT_SECRET_KEY_PATTERN =
  /(authorization|cookie|credential|password|passwd|private[_-]?key|secret|token|api[_-]?key)/i;

function posixPath(value) {
  return String(value || "").split(path.sep).join("/");
}

function safeReadJson(filePath) {
  try {
    return JSON.parse(fs.readFileSync(filePath, "utf8"));
  } catch {
    return undefined;
  }
}

function readJsonResult(filePath) {
  try {
    return { value: JSON.parse(fs.readFileSync(filePath, "utf8")) };
  } catch (error) {
    return { error };
  }
}

function sha256File(filePath) {
  return crypto.createHash("sha256").update(fs.readFileSync(filePath)).digest("hex");
}

function fileStats(cwd, entries = []) {
  return entries.map((entry) => {
    const filePath = path.resolve(cwd, entry);
    if (!fs.existsSync(filePath)) {
      return { path: posixPath(entry), exists: false };
    }
    const stat = fs.statSync(filePath);
    return {
      path: posixPath(entry),
      exists: true,
      type: stat.isDirectory() ? "directory" : stat.isFile() ? "file" : "other",
      bytes: stat.size,
    };
  });
}

function commandVersion(command, args = ["--version"], cwd = process.cwd()) {
  try {
    return execFileSync(command, args, {
      cwd,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
      timeout: 5000,
    }).trim().split(/\r?\n/)[0] || "";
  } catch {
    return "";
  }
}

function defaultDiagnosticCommandRunner(command, args = [], { cwd = process.cwd(), timeoutMs = 5000 } = {}) {
  return execFileSync(command, args, {
    cwd,
    encoding: "utf8",
    stdio: ["ignore", "pipe", "ignore"],
    timeout: timeoutMs,
  });
}

function gitField(cwd, args) {
  try {
    return execFileSync("git", args, {
      cwd,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
      timeout: 5000,
    }).trim();
  } catch {
    return "";
  }
}

function safeAnchorManifest(cwd, loadedConfig) {
  try {
    return loadConfiguredAnchorManifest(cwd, loadedConfig);
  } catch (error) {
    return { error: error.message };
  }
}

function check(ok, id, message, details = {}) {
  return { id, status: ok ? "pass" : "fail", message, details };
}

function normalizePublishSourceRef(value = "") {
  return String(value || "")
    .trim()
    .replace(/^refs\/heads\//, "")
    .replace(/^refs\/tags\//, "");
}

function parsePublishGateSourceRef(value = "") {
  const sourceRef = normalizePublishSourceRef(value);
  if (sourceRef === "publish-gate/major") {
    return { sourceRef, channel: "major", line: "", consumerVersion: "" };
  }
  if (sourceRef === "publish-gate/anchor") {
    return { sourceRef, channel: "anchor", line: "", consumerVersion: "" };
  }
  const match = sourceRef.match(/^publish-gate\/(alpha|release)\/(.+)\/([^/]+)$/);
  if (!match) {
    return { sourceRef, channel: "", line: "", consumerVersion: "" };
  }
  return {
    sourceRef,
    channel: match[1],
    line: match[2],
    consumerVersion: match[3],
  };
}

function versionFileValue(file) {
  if (file.type === "json" || file.type === "toml") {
    return String(file.key || "")
      .split(".")
      .reduce((current, segment) => current?.[segment], file.content);
  }
  return file.source.match(file.pattern)?.groups?.version;
}

function defaultPublishSourceFromEnv(env = process.env) {
  return {
    sourceRef: env.BUILDCHAIN_PUBLISH_SOURCE_REF || "",
    sourceSha: env.BUILDCHAIN_PUBLISH_SOURCE_SHA || "",
    sourceLocked: env.BUILDCHAIN_PUBLISH_SOURCE_LOCKED || "",
    channel: env.BUILDCHAIN_PUBLISH_SOURCE_CHANNEL || "",
    consumerVersion: env.BUILDCHAIN_PUBLISH_SOURCE_CONSUMER_VERSION || "",
  };
}

function lifecycleTimingFromEvents(events = []) {
  const stages = {};
  const spans = [];
  let warningCount = 0;
  let errorCount = 0;
  for (const event of events) {
    if (event.level === "warn") {
      warningCount += 1;
    }
    if (event.level === "error") {
      errorCount += 1;
    }
    const stage = event.attributes?.stage || event.phase || "unknown";
    const durationMs = Number(event.durationMs || 0);
    if (durationMs > 0) {
      stages[stage] = stages[stage] || { durationMs: 0, eventCount: 0 };
      stages[stage].durationMs += durationMs;
      spans.push({
        event: event.event,
        source: event.source || "",
        component: event.component || "",
        stage,
        phase: event.phase || "",
        durationMs,
      });
    }
    if (stage) {
      stages[stage] = stages[stage] || { durationMs: 0, eventCount: 0 };
      stages[stage].eventCount += 1;
    }
  }
  return {
    stages: Object.fromEntries(Object.entries(stages).sort(([left], [right]) => left.localeCompare(right))),
    topSlowSpans: spans.sort((left, right) => right.durationMs - left.durationMs).slice(0, 10),
    warningCount,
    errorCount,
  };
}

export function summarizeLifecycleObservability({
  events = [],
  logPath = "",
  artifactScanDurationMs = 0,
  artifactUploadDurationMs = 0,
  totalBytes = 0,
  fileCount = 0,
} = {}) {
  const resolvedEvents = events.length ? events : readBuildchainLogEvents(logPath);
  const timing = lifecycleTimingFromEvents(resolvedEvents);
  return {
    schemaVersion: 1,
    contract: BUILDCHAIN_LIFECYCLE_OBSERVABILITY_CONTRACT,
    log: {
      contract: BUILDCHAIN_LOG_EVENT_CONTRACT,
      path: logPath ? posixPath(logPath) : "",
      summary: summarizeBuildchainLogEvents(resolvedEvents),
    },
    stages: timing.stages,
    artifactScan: { durationMs: Math.round(Number(artifactScanDurationMs || 0)) },
    artifactUpload: { durationMs: Math.round(Number(artifactUploadDurationMs || 0)) },
    totalBytes: Number(totalBytes || 0),
    fileCount: Number(fileCount || 0),
    topSlowSpans: timing.topSlowSpans,
    warningCount: timing.warningCount,
    errorCount: timing.errorCount,
  };
}

export function collectBuildchainDiagnostics({ cwd = process.cwd(), artifactPaths = [] } = {}) {
  const resolvedCwd = path.resolve(cwd);
  const loadedConfig = loadBuildchainConfig(resolvedCwd);
  let configSummary = {};
  try {
    configSummary = validateBuildchainConfig(resolvedCwd);
  } catch (error) {
    configSummary = { ok: false, error: error.message };
  }
  return {
    config: loadedConfig
      ? {
          path: loadedConfig.path,
          project: loadedConfig.config.project || {},
          versionStrategy: getVersionStrategy(loadedConfig),
          publishContract: getPublishContract(loadedConfig),
          lifecycleStages: Object.keys(loadedConfig.config.lifecycle || {}),
          diagnostics: {
            native: getNativeDiagnosticsProfile(loadedConfig),
          },
          anchorManifest: safeAnchorManifest(resolvedCwd, loadedConfig),
          validation: configSummary,
        }
      : { path: "", validation: configSummary },
    lifecycle: Object.fromEntries(
      ["install", "build", "verify", "publish"]
        .map((stage) => [stage, getLifecycleStage(loadedConfig, stage)])
        .filter(([, value]) => Boolean(value)),
    ),
    artifactPaths: fileStats(resolvedCwd, artifactPaths),
  };
}

function selectedCompilerCacheDiagnostics({ cwd, compilerCache, runCommand }) {
  if (compilerCache === "none") {
    return {};
  }
  const diagnostics = collectCompilerCacheDiagnostics({ cwd, runCommand });
  if (compilerCache === "ccache") {
    return { ccache: diagnostics.ccache };
  }
  if (compilerCache === "sccache") {
    return { sccache: diagnostics.sccache };
  }
  return diagnostics;
}

export function collectNativeDiagnostics({
  cwd = process.cwd(),
  profile = undefined,
  runCommand = defaultDiagnosticCommandRunner,
} = {}) {
  const resolvedCwd = path.resolve(cwd);
  const nativeProfile = profile || getNativeDiagnosticsProfile(loadBuildchainConfig(resolvedCwd));
  if (!nativeProfile.enabled) {
    return {
      enabled: false,
      profile: nativeProfile,
    };
  }
  const expectedTools = nativeProfile.expectedTools.length
    ? nativeProfile.expectedTools
    : ["node", "pnpm", "npm", "git", "cmake", "ninja", "ccache", "sccache"];
  return {
    enabled: true,
    profile: nativeProfile,
    tools: collectToolDiagnostics({ cwd: resolvedCwd, tools: expectedTools }),
    compilerCaches: selectedCompilerCacheDiagnostics({
      cwd: resolvedCwd,
      compilerCache: nativeProfile.compilerCache,
      runCommand,
    }),
    artifactDirs: fileStats(resolvedCwd, nativeProfile.artifactDirs),
    cacheDirs: fileStats(resolvedCwd, nativeProfile.cacheDirs),
  };
}

export function validateAnchoredPackageRelease({
  cwd = process.cwd(),
  requireManifest = true,
  requirePackageSetOrder = "platforms-first-main-last",
  requireTrustedPublishing = true,
  requireLifecycleStages = ["install", "build", "verify", "publish"],
  requirePublishGateSourceLock = false,
  publishSource = undefined,
  env = process.env,
} = {}) {
  const resolvedCwd = path.resolve(cwd);
  const checks = [];
  let versionFiles = [];
  let loadedConfig;
  try {
    loadedConfig = loadBuildchainConfig(resolvedCwd);
    checks.push(check(Boolean(loadedConfig), "config.load", "buildchain.toml is readable"));
  } catch (error) {
    checks.push(check(false, "config.load", error.message));
  }
  const versionStrategy = getVersionStrategy(loadedConfig);
  checks.push(check(
    versionStrategy.strategy === "anchored",
    "version.strategy",
    "version strategy is anchored",
    versionStrategy,
  ));
  checks.push(check(
    versionStrategy.next === "manual",
    "version.next",
    "next version strategy is manual",
    versionStrategy,
  ));
  const anchorManifest = safeAnchorManifest(resolvedCwd, loadedConfig);
  checks.push(check(
    !requireManifest || (anchorManifest && !anchorManifest.error),
    "version.manifest",
    anchorManifest?.error || "anchor manifest is readable",
    { path: anchorManifest?.path || versionStrategy.manifest || "" },
  ));
  try {
    versionFiles = discoverConfiguredVersionStateFiles(resolvedCwd, loadedConfig);
    checks.push(check(versionFiles.length > 0, "version.files", "configured version files are readable", {
      files: versionFiles.map((file) => file.path),
    }));
  } catch (error) {
    checks.push(check(false, "version.files", error.message));
  }
  const publish = getPublishContract(loadedConfig) || {};
  checks.push(check(
    publish.mode === "publish-final-version",
    "publish.mode",
    "publish mode is compatible with anchored final-version release",
    { mode: publish.mode || "" },
  ));
  if (requireTrustedPublishing) {
    checks.push(check(
      publish.auth === "trusted-publishing",
      "publish.auth",
      "trusted publishing is enabled",
      { auth: publish.auth || "" },
    ));
  }
  if (requirePackageSetOrder) {
    checks.push(check(
      publish.packageSetOrder === requirePackageSetOrder,
      "publish.package_set_order",
      `package set order is ${requirePackageSetOrder}`,
      { packageSetOrder: publish.packageSetOrder || "" },
    ));
  }
  for (const stage of requireLifecycleStages || []) {
    checks.push(check(
      Boolean(getLifecycleStage(loadedConfig, stage)),
      `lifecycle.${stage}`,
      `lifecycle stage is configured: ${stage}`,
    ));
  }
  const source = publishSource || defaultPublishSourceFromEnv(env);
  const parsedSource = parsePublishGateSourceRef(source.sourceRef);
  if (requirePublishGateSourceLock) {
    const normalizedLocked = String(source.sourceLocked || "").toLowerCase();
    const lockEnabled = normalizedLocked === "true" || normalizedLocked === "1" || source.sourceLocked === true;
    checks.push(check(
      lockEnabled,
      "publish.source_locked",
      "publish source lock is required before package publication",
      { sourceLocked: source.sourceLocked || "" },
    ));
    checks.push(check(
      Boolean(parsedSource.channel) && parsedSource.channel !== "anchor",
      "publish.source_ref",
      "publish source ref uses publish-gate/{alpha,release,major}",
      { sourceRef: parsedSource.sourceRef || source.sourceRef || "", channel: parsedSource.channel || "" },
    ));
    checks.push(check(
      /^[0-9a-f]{40}$/i.test(String(source.sourceSha || "")),
      "publish.source_sha",
      "publish source SHA is a 40-character Git SHA",
      { sourceSha: source.sourceSha || "" },
    ));
    const consumerVersion = parsedSource.consumerVersion || source.consumerVersion || "";
    if (consumerVersion) {
      const mismatches = versionFiles
        .map((file) => ({ path: file.path, version: versionFileValue(file) || "" }))
        .filter((file) => file.version !== consumerVersion);
      checks.push(check(
        mismatches.length === 0,
        "publish.source_version",
        `publish source consumer version matches configured version files: ${consumerVersion}`,
        { consumerVersion, mismatches },
      ));
      checks.push(check(
        !anchorManifest?.fields?.npmVersion || anchorManifest.fields.npmVersion === consumerVersion,
        "publish.anchor_version",
        `anchor manifest npmVersion matches publish source version: ${consumerVersion}`,
        { consumerVersion, npmVersion: anchorManifest?.fields?.npmVersion || "" },
      ));
    }
  }
  return {
    schemaVersion: 1,
    contract: BUILDCHAIN_ANCHORED_PACKAGE_RELEASE_VALIDATION_CONTRACT,
    cwd: resolvedCwd,
    ok: checks.every((entry) => entry.status === "pass"),
    checks,
    summary: {
      versionStrategy,
      anchorManifest: anchorManifest?.path || "",
      publish,
      publishSource: {
        sourceRef: parsedSource.sourceRef || source.sourceRef || "",
        sourceSha: source.sourceSha || "",
        sourceLocked: source.sourceLocked || "",
        channel: parsedSource.channel || source.channel || "",
        line: parsedSource.line || "",
        consumerVersion: parsedSource.consumerVersion || source.consumerVersion || "",
      },
      requiredLifecycleStages: requireLifecycleStages,
    },
  };
}

export function collectRunnerDiagnostics() {
  return {
    os: {
      platform: os.platform(),
      release: os.release(),
      arch: os.arch(),
      type: os.type(),
    },
    cpu: {
      logicalCount: os.cpus().length,
      model: os.cpus()[0]?.model || "",
      loadAverage: os.loadavg(),
    },
    memory: {
      totalBytes: os.totalmem(),
      freeBytes: os.freemem(),
    },
    uptimeSeconds: Math.round(os.uptime()),
    github: {
      actions: process.env.GITHUB_ACTIONS === "true",
      runnerOs: process.env.RUNNER_OS || "",
      runnerArch: process.env.RUNNER_ARCH || "",
      runnerName: process.env.RUNNER_NAME || "",
    },
  };
}

export function collectToolDiagnostics({ cwd = process.cwd(), tools = ["node", "pnpm", "npm", "git", "cmake", "ninja", "ccache", "sccache"] } = {}) {
  return Object.fromEntries(tools.map((tool) => [tool, { version: commandVersion(tool, ["--version"], cwd) }]));
}

function parseJsonDiagnostics(value = "") {
  try {
    return JSON.parse(String(value || "").trim());
  } catch {
    return undefined;
  }
}

function parseTextStats(value = "") {
  const stats = {};
  for (const line of String(value || "").split(/\r?\n/)) {
    const trimmed = line.trim();
    if (!trimmed) {
      continue;
    }
    const match = trimmed.match(/^(.+?)(?:\s{2,}|\t+|:\s+)([-+]?\d+(?:\.\d+)?)(?:\s|$)/);
    if (!match) {
      continue;
    }
    const key = match[1]
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "_")
      .replace(/^_+|_+$/g, "");
    if (!key) {
      continue;
    }
    const number = Number(match[2]);
    stats[key] = Number.isFinite(number) ? number : match[2];
  }
  return stats;
}

function collectCompilerCacheTool({ command, attempts, cwd, runCommand }) {
  let lastError;
  for (const attempt of attempts) {
    const args = attempt.args || [];
    const expectedFormat = attempt.format || "";
    try {
      const output = runCommand(command, args, { cwd, timeoutMs: 5000 });
      const text = String(output || "").trim();
      const jsonStats = parseJsonDiagnostics(text);
      if (jsonStats) {
        return {
          available: true,
          command,
          args,
          format: "json",
          stats: jsonStats,
          rawBytes: Buffer.byteLength(text, "utf8"),
          parseError: "",
        };
      }
      const textStats = parseTextStats(text);
      return {
        available: true,
        command,
        args,
        format: "text",
        stats: textStats,
        rawBytes: Buffer.byteLength(text, "utf8"),
        parseError: Object.keys(textStats).length ? "" : `${expectedFormat || "stats"} output was not parseable`,
      };
    } catch (error) {
      lastError = error;
    }
  }
  return {
    available: false,
    command,
    error: lastError?.code || lastError?.message || "stats command failed",
  };
}

export function collectCompilerCacheDiagnostics({
  cwd = process.cwd(),
  runCommand = defaultDiagnosticCommandRunner,
} = {}) {
  const resolvedCwd = path.resolve(cwd);
  return {
    ccache: collectCompilerCacheTool({
      command: "ccache",
      attempts: [
        { args: ["--show-stats", "--json"], format: "json" },
        { args: ["--show-stats"], format: "text" },
      ],
      cwd: resolvedCwd,
      runCommand,
    }),
    sccache: collectCompilerCacheTool({
      command: "sccache",
      attempts: [
        { args: ["--show-stats", "--stats-format", "json"], format: "json" },
      ],
      cwd: resolvedCwd,
      runCommand,
    }),
  };
}

export function collectCacheDiagnostics({ cwd = process.cwd(), cacheDirs = [], runCommand = defaultDiagnosticCommandRunner } = {}) {
  const resolvedCwd = path.resolve(cwd);
  return {
    packageManager: (() => {
      try {
        return detectPackageManager(resolvedCwd);
      } catch (error) {
        return { name: "unknown", error: error.message };
      }
    })(),
    workspace: (() => {
      try {
        return getWorkspaceInfo(resolvedCwd);
      } catch (error) {
        return { error: error.message };
      }
    })(),
    dirs: fileStats(resolvedCwd, cacheDirs),
    compilerCaches: collectCompilerCacheDiagnostics({ cwd: resolvedCwd, runCommand }),
  };
}

export function collectGitDiagnostics({ cwd = process.cwd() } = {}) {
  return {
    repository: gitField(cwd, ["config", "--get", "remote.origin.url"]),
    head: gitField(cwd, ["rev-parse", "HEAD"]),
    ref: gitField(cwd, ["rev-parse", "--abbrev-ref", "HEAD"]),
    dirty: gitField(cwd, ["status", "--short"]) !== "",
  };
}

export function redactDiagnosticsValue(key, value, pattern = DEFAULT_SECRET_KEY_PATTERN) {
  if (pattern.test(String(key || ""))) {
    return "[REDACTED]";
  }
  return value;
}

function processCommandFromLine(commandLine = "", fallback = "") {
  const firstToken = shellishTokens(commandLine)[0] || fallback;
  return String(firstToken || "")
    .replace(/[()]/g, "")
    .split(/[\\/]/)
    .pop();
}

function normalizeProcessRows({ rootPid, platform, rows = [] }) {
  const byParent = new Map();
  const byPid = new Map();
  for (const row of rows) {
    byPid.set(row.pid, row);
    byParent.set(row.ppid, [...(byParent.get(row.ppid) || []), row]);
  }
  const seen = new Set();
  const stack = [String(rootPid)];
  const processes = [];
  while (stack.length) {
    const current = stack.pop();
    for (const child of byParent.get(current) || []) {
      if (seen.has(child.pid)) {
        continue;
      }
      seen.add(child.pid);
      processes.push(child);
      stack.push(child.pid);
    }
  }
  return { rootPid: String(rootPid), platform, rootProcess: byPid.get(String(rootPid)) || undefined, processes };
}

function collectWindowsProcessRows({ cwd, runCommand }) {
  const script = [
    "$ErrorActionPreference = 'Stop';",
    "Get-CimInstance Win32_Process |",
    "Select-Object ProcessId,ParentProcessId,Name,CommandLine |",
    "ConvertTo-Json -Compress",
  ].join(" ");
  const errors = [];
  let output = "";
  for (const command of ["powershell.exe", "powershell", "pwsh"]) {
    try {
      output = runCommand(command, ["-NoProfile", "-NonInteractive", "-Command", script], {
        cwd,
        timeoutMs: 5000,
      });
      break;
    } catch (error) {
      errors.push(`${command}: ${error.message}`);
    }
  }
  if (!output) {
    throw new Error(`Windows process sampler unavailable: ${errors.join("; ") || "no process query output"}`);
  }
  const parsed = JSON.parse(String(output || "[]"));
  const entries = Array.isArray(parsed) ? parsed : [parsed];
  return entries.map((entry) => {
    const commandLine = redactCommandLine(entry.CommandLine || entry.Name || "");
    return {
      pid: String(entry.ProcessId || ""),
      ppid: String(entry.ParentProcessId || ""),
      cpu: 0,
      command: processCommandFromLine(commandLine, entry.Name || ""),
      commandLine,
    };
  }).filter((entry) => entry.pid && entry.ppid);
}

export function collectProcessTreeSnapshot({
  rootPid = process.pid,
  cwd = process.cwd(),
  platform = process.platform,
  runCommand = defaultDiagnosticCommandRunner,
} = {}) {
  const pid = String(rootPid || process.pid);
  if (platform === "win32") {
    try {
      return normalizeProcessRows({
        rootPid: pid,
        platform,
        rows: collectWindowsProcessRows({ cwd, runCommand }),
      });
    } catch (error) {
      return {
        rootPid: pid,
        platform,
        processes: [],
        samplerUnavailable: true,
        samplerUnavailableReason: error.message,
      };
    }
  }
  let lines = [];
  try {
    lines = runCommand("ps", ["-axo", "pid=,ppid=,pcpu=,args="], {
      cwd,
      timeoutMs: 5000,
    }).split(/\r?\n/).filter(Boolean);
  } catch (error) {
    return {
      rootPid: pid,
      platform,
      processes: [],
      samplerUnavailable: true,
      samplerUnavailableReason: error.message,
    };
  }
  const rows = lines.map((line) => {
    const match = line.trim().match(/^(\d+)\s+(\d+)\s+([0-9.]+)\s+(.*)$/);
    const args = match?.[4] || "";
    const commandLine = redactCommandLine(args);
    return match
      ? {
          pid: match[1],
          ppid: match[2],
          cpu: Number(match[3]),
          command: processCommandFromLine(commandLine),
          commandLine,
        }
      : undefined;
  }).filter(Boolean);
  return normalizeProcessRows({ rootPid: pid, platform, rows });
}

export function classifyProcessCommand(command = "") {
  const name = String(command || "").split(/[\\/]/).pop().toLowerCase();
  if (/^(ccache|sccache)$/.test(name)) {
    return "cache";
  }
  if (/^(clang|clang\+\+|gcc|g\+\+|cc|c\+\+|cl)(\.exe)?$/.test(name)) {
    return "compiler";
  }
  if (/^(ld|lld|lld-link|link)(\.exe)?$/.test(name)) {
    return "linker";
  }
  if (/^(ar|llvm-ar|libtool|ranlib)(\.exe)?$/.test(name)) {
    return "archive";
  }
  if (/^(make|ninja|cmake|msbuild|vcbuild|gyp-mac-tool)(\.exe)?$/.test(name)) {
    return "build-tool";
  }
  if (/^(node|python|python3|bash|sh|pwsh|powershell)(\.exe)?$/.test(name)) {
    return "script";
  }
  return "other";
}

function firstPositiveInteger(value) {
  const number = Number(value);
  return Number.isInteger(number) && number > 0 ? number : 0;
}

function commandName(value = "") {
  return String(value || "")
    .replace(/[()]/g, "")
    .replace(/\.exe$/i, "")
    .split(/[\\/]/)
    .pop()
    .toLowerCase();
}

function detectParallelismFromTokens(tokens = []) {
  for (let index = 0; index < tokens.length; index += 1) {
    const token = String(tokens[index] || "");
    const inlineMatch = token.match(/^(?:-j|--jobs=|--parallel=|-jobs|\/m:|\/maxcpucount:|-m:)(\d+)$/i);
    if (inlineMatch) {
      return { value: Number(inlineMatch[1]), source: "command", token };
    }
    if (/^(?:-j|--jobs|--parallel|-jobs)$/i.test(token)) {
      const value = firstPositiveInteger(tokens[index + 1]);
      if (value) {
        return { value, source: "command", token: `${token} ${tokens[index + 1]}` };
      }
    }
  }
  return { value: 0, source: "", token: "" };
}

function shellishTokens(command = "") {
  return String(command || "").match(/"[^"]+"|'[^']+'|\S+/g)?.map((token) => token.replace(/^['"]|['"]$/g, "")) || [];
}

function redactCommandLine(commandLine = "", pattern = DEFAULT_SECRET_KEY_PATTERN) {
  const tokens = shellishTokens(commandLine);
  let redactNext = false;
  return tokens.map((token) => {
    const withUrlUserInfo = token.replace(/:\/\/[^/\s:@]+:[^/\s@]+@/g, "://[REDACTED]@");
    if (redactNext) {
      redactNext = false;
      return "[REDACTED]";
    }
    const assignment = withUrlUserInfo.match(/^([^=\s]+)=(.*)$/);
    if (assignment && pattern.test(assignment[1])) {
      return `${assignment[1]}=[REDACTED]`;
    }
    const inlineOption = withUrlUserInfo.match(/^(--?[^=\s]+)=(.*)$/);
    if (inlineOption && pattern.test(inlineOption[1])) {
      return `${inlineOption[1]}=[REDACTED]`;
    }
    if (/^--?/.test(withUrlUserInfo) && pattern.test(withUrlUserInfo)) {
      redactNext = true;
    }
    return withUrlUserInfo;
  }).join(" ");
}

function commandLineFromProcess(entry = {}) {
  return [
    entry.commandLine,
    Array.isArray(entry.args) ? entry.args.join(" ") : entry.args,
    Array.isArray(entry.argv) ? entry.argv.join(" ") : "",
    entry.command,
  ].find((value) => String(value || "").trim()) || "";
}

function parallelismCandidate({ value, source, token, entry, sample }) {
  return {
    value,
    source,
    token,
    pid: entry?.pid ? String(entry.pid) : "",
    command: commandName(entry?.command || shellishTokens(commandLineFromProcess(entry))[0] || ""),
    commandLine: commandLineFromProcess(entry),
    timestamp: sample?.timestamp || "",
  };
}

export function detectRequestedParallelism({
  command = "",
  args = [],
  env = process.env,
} = {}) {
  const commandTokens = [
    ...shellishTokens(command),
    ...(Array.isArray(args) ? args.map((entry) => String(entry)) : shellishTokens(args)),
  ];
  const commandParallelism = detectParallelismFromTokens(commandTokens);
  if (commandParallelism.value) {
    return commandParallelism;
  }

  const explicitEnvKeys = [
    "BUILDCHAIN_REQUESTED_PARALLELISM",
    "CMAKE_BUILD_PARALLEL_LEVEL",
    "NINJA_STATUS_JOBS",
    "npm_config_jobs",
  ];
  for (const key of explicitEnvKeys) {
    const value = firstPositiveInteger(env?.[key]);
    if (value) {
      return { value, source: `env:${key}`, token: key };
    }
  }

  const makeflags = detectParallelismFromTokens(shellishTokens(env?.MAKEFLAGS || ""));
  if (makeflags.value) {
    return { ...makeflags, source: "env:MAKEFLAGS" };
  }

  return { value: 0, source: "", token: "" };
}

export function detectRequestedParallelismFromProcessSamples(samples = []) {
  const candidates = [];
  const buildToolNames = new Set(["make", "ninja", "cmake", "msbuild", "xcodebuild"]);
  for (const sample of Array.isArray(samples) ? samples : []) {
    for (const entry of Array.isArray(sample?.processes) ? sample.processes : []) {
      const command = commandName(entry.command || shellishTokens(commandLineFromProcess(entry))[0] || "");
      if (!buildToolNames.has(command)) {
        continue;
      }
      const tokens = shellishTokens(commandLineFromProcess(entry));
      const detected = detectParallelismFromTokens(tokens);
      if (detected.value) {
        candidates.push(parallelismCandidate({
          ...detected,
          source: "process-tree",
          entry,
          sample,
        }));
      }
    }
  }
  candidates.sort((left, right) => right.value - left.value || left.command.localeCompare(right.command));
  return {
    value: candidates[0]?.value || 0,
    source: candidates[0] ? "process-tree" : "",
    token: candidates[0]?.token || "",
    evidence: candidates[0] || undefined,
    candidates,
  };
}

export function summarizeProcessSamples({
  samples = [],
  requestedParallelism = 0,
  command = "",
  args = [],
  env = process.env,
  activeCpuThreshold = 0.1,
} = {}) {
  const normalizedSamples = Array.isArray(samples) ? samples : [];
  const unavailableSamples = normalizedSamples.filter((sample) => sample?.samplerUnavailable);
  const activeCounts = [];
  const cpuTotals = [];
  const categoryMax = {};
  const commandStats = new Map();
  const threshold = Number(activeCpuThreshold || 0);

  for (const sample of normalizedSamples) {
    const processes = Array.isArray(sample?.processes) ? sample.processes : [];
    const active = processes.filter((entry) => Number(entry.cpu || 0) >= threshold);
    activeCounts.push(active.length);
    cpuTotals.push(processes.reduce((sum, entry) => sum + Number(entry.cpu || 0), 0));

    const categoryCounts = {};
    for (const entry of active) {
      const command = path.basename(String(entry.command || "unknown"));
      const category = classifyProcessCommand(command);
      categoryCounts[category] = (categoryCounts[category] || 0) + 1;
      const stats = commandStats.get(command) || {
        command,
        category,
        samples: 0,
        maxConcurrent: 0,
        maxCpu: 0,
      };
      stats.samples += 1;
      stats.maxCpu = Math.max(stats.maxCpu, Number(entry.cpu || 0));
      commandStats.set(command, stats);
    }

    const commandCounts = {};
    for (const entry of active) {
      const command = path.basename(String(entry.command || "unknown"));
      commandCounts[command] = (commandCounts[command] || 0) + 1;
    }
    for (const [command, count] of Object.entries(commandCounts)) {
      const stats = commandStats.get(command);
      if (stats) {
        stats.maxConcurrent = Math.max(stats.maxConcurrent, count);
      }
    }
    for (const [category, count] of Object.entries(categoryCounts)) {
      categoryMax[category] = Math.max(categoryMax[category] || 0, count);
    }
  }

  const observedMax = activeCounts.length ? Math.max(...activeCounts) : 0;
  const observedAverage = activeCounts.length
    ? activeCounts.reduce((sum, value) => sum + value, 0) / activeCounts.length
    : 0;
  const totalCpuMax = cpuTotals.length ? Math.max(...cpuTotals) : 0;
  const totalCpuAverage = cpuTotals.length
    ? cpuTotals.reduce((sum, value) => sum + value, 0) / cpuTotals.length
    : 0;
  const explicitRequested = firstPositiveInteger(requestedParallelism);
  const commandParallelism = detectRequestedParallelism({ command, args, env });
  const sampledParallelism = detectRequestedParallelismFromProcessSamples(normalizedSamples);
  const requested = explicitRequested || sampledParallelism.value || commandParallelism.value;
  const requestedSource = explicitRequested
    ? "explicit"
    : sampledParallelism.source || commandParallelism.source;
  const requestedEvidence = explicitRequested
    ? { value: explicitRequested, source: "explicit" }
    : sampledParallelism.evidence || (commandParallelism.value ? commandParallelism : undefined);

  return {
    schemaVersion: 1,
    contract: BUILDCHAIN_PROCESS_SAMPLE_SUMMARY_CONTRACT,
    sampleCount: normalizedSamples.length,
    sampler: {
      unavailable: unavailableSamples.length > 0,
      unavailableSamples: unavailableSamples.length,
      unavailableReasons: [...new Set(
        unavailableSamples
          .map((sample) => String(sample.samplerUnavailableReason || "").trim())
          .filter(Boolean),
      )].slice(0, 5),
    },
    activeCpuThreshold: threshold,
    requestedParallelism: requested,
    requestedParallelismSource: requestedSource,
    requestedParallelismEvidence: requestedEvidence || {},
    requestedParallelismCandidates: sampledParallelism.candidates.slice(0, 10),
    observedConcurrency: {
      max: observedMax,
      average: Number(observedAverage.toFixed(2)),
      ratioToRequestedMax: requested > 0 ? Number((observedMax / requested).toFixed(3)) : 0,
    },
    cpu: {
      totalMax: Number(totalCpuMax.toFixed(2)),
      totalAverage: Number(totalCpuAverage.toFixed(2)),
    },
    categories: Object.fromEntries(Object.entries(categoryMax).sort(([left], [right]) => left.localeCompare(right))),
    topCommands: [...commandStats.values()]
      .sort((left, right) => right.maxConcurrent - left.maxConcurrent || right.maxCpu - left.maxCpu)
      .slice(0, 10),
  };
}

export function startProcessSampler({
  rootPid = process.pid,
  intervalMs = 15000,
  label = "",
  command = "",
  args = [],
  env = process.env,
  requestedParallelism = 0,
  onSample = () => undefined,
  cwd = process.cwd(),
} = {}) {
  const samples = [];
  const startedAt = Date.now();
  const explicitRequested = firstPositiveInteger(requestedParallelism);
  const detectedParallelism = detectRequestedParallelism({ command, args, env });
  const requested = explicitRequested || detectedParallelism.value;
  const sample = () => {
    const snapshot = {
      timestamp: new Date().toISOString(),
      label,
      elapsedMs: Date.now() - startedAt,
      requestedParallelism: requested,
      requestedParallelismSource: explicitRequested ? "explicit" : detectedParallelism.source,
      ...collectProcessTreeSnapshot({ rootPid, cwd }),
    };
    samples.push(snapshot);
    onSample(snapshot);
    return snapshot;
  };
  sample();
  const interval = Math.max(1000, Number(intervalMs || 15000));
  const earlyDelay = Math.min(1000, interval);
  const earlyTimer = interval > earlyDelay ? setTimeout(sample, earlyDelay) : undefined;
  const timer = setInterval(sample, interval);
  return {
    samples,
    stop() {
      if (earlyTimer) {
        clearTimeout(earlyTimer);
      }
      clearInterval(timer);
      return samples;
    },
  };
}

export function createDiagnosticsArtifact({
  cwd = process.cwd(),
  logPath = "",
  artifactPaths = [],
  cacheDirs = [],
  lifecycleObservability = undefined,
  processSamples = [],
  processSummary = undefined,
  requestedParallelism = 0,
  sourceCheckout = undefined,
  links = {},
} = {}) {
  const resolvedCwd = path.resolve(cwd);
  const events = logPath ? readBuildchainLogEvents(logPath) : [];
  const loadedConfig = loadBuildchainConfig(resolvedCwd);
  const nativeProfile = getNativeDiagnosticsProfile(loadedConfig);
  const native = collectNativeDiagnostics({ cwd: resolvedCwd, profile: nativeProfile });
  const cache = collectCacheDiagnostics({ cwd: resolvedCwd, cacheDirs });
  return {
    schemaVersion: 1,
    contract: BUILDCHAIN_DIAGNOSTICS_CONTRACT,
    generatedAt: new Date().toISOString(),
    cwd: resolvedCwd,
    buildchain: collectBuildchainDiagnostics({ cwd: resolvedCwd, artifactPaths }),
    runner: collectRunnerDiagnostics(),
    tools: collectToolDiagnostics({ cwd: resolvedCwd }),
    cache,
    native,
    compilerCaches: native.compilerCaches || cache.compilerCaches || {},
    nativeCacheDirs: native.cacheDirs || [],
    git: collectGitDiagnostics({ cwd: resolvedCwd }),
    lifecycleObservability: lifecycleObservability || summarizeLifecycleObservability({ events, logPath }),
    process: processSummary || summarizeProcessSamples({ samples: processSamples, requestedParallelism }),
    ...(sourceCheckout ? { sourceCheckout } : {}),
    links,
  };
}

export function writeDiagnosticsArtifact(filePath, diagnostics) {
  if (!filePath) {
    return "";
  }
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, `${JSON.stringify(diagnostics, null, 2)}\n`);
  return filePath;
}

export function readDiagnosticsArtifact(filePath) {
  return safeReadJson(filePath);
}

function sumLifecycleDurationMs(stages = {}) {
  return Object.values(stages).reduce((sum, entry) => sum + Number(entry?.durationMs || 0), 0);
}

function stageDurationMs(stages = {}, stage) {
  return Math.round(Number(stages?.[stage]?.durationMs || 0));
}

function formatDiagnosticsDurationMs(value) {
  const durationMs = Math.round(Number(value || 0));
  if (!Number.isFinite(durationMs) || durationMs <= 0) {
    return "-";
  }
  if (durationMs < 1000) {
    return `${durationMs}ms`;
  }
  if (durationMs < 60000) {
    const seconds = durationMs / 1000;
    return `${seconds < 10 ? seconds.toFixed(1).replace(/\.0$/, "") : Math.round(seconds)}s`;
  }
  const minutes = Math.floor(durationMs / 60000);
  const seconds = Math.round((durationMs % 60000) / 1000);
  return seconds ? `${minutes}m${seconds}s` : `${minutes}m`;
}

function compactProcessSummary(process = {}) {
  const observedConcurrency = process?.observedConcurrency || {};
  const topCommands = Array.isArray(process?.topCommands)
    ? process.topCommands.slice(0, 3).map((entry) => ({
        command: entry.command || "",
        category: entry.category || "",
        maxConcurrent: Number(entry.maxConcurrent || 0),
        maxCpu: Number(entry.maxCpu || 0),
      }))
    : [];
  return {
    requestedParallelism: Number(process?.requestedParallelism || 0),
    requestedParallelismSource: process?.requestedParallelismSource || "",
    observedConcurrencyMax: Number(observedConcurrency.max || 0),
    ratioToRequestedMax: Number(observedConcurrency.ratioToRequestedMax || 0),
    sampleCount: Number(process?.sampleCount || 0),
    categories: process?.categories || {},
    topCommands,
  };
}

function formatDiagnosticsProcessValue(value) {
  const number = Number(value || 0);
  return number > 0 ? String(number) : "-";
}

function compactRunnerDetails(runner = {}) {
  return {
    os: {
      platform: runner.os?.platform || "",
      release: runner.os?.release || "",
      arch: runner.os?.arch || "",
      type: runner.os?.type || "",
    },
    github: {
      actions: Boolean(runner.github?.actions),
      runnerOs: runner.github?.runnerOs || "",
      runnerArch: runner.github?.runnerArch || "",
      runnerName: runner.github?.runnerName || "",
    },
    cpu: {
      logicalCount: Number(runner.cpu?.logicalCount || 0),
      model: runner.cpu?.model || "",
      loadAverage: Array.isArray(runner.cpu?.loadAverage)
        ? runner.cpu.loadAverage.map((entry) => Number(entry || 0))
        : [],
    },
    memory: {
      totalBytes: Number(runner.memory?.totalBytes || 0),
      freeBytes: Number(runner.memory?.freeBytes || 0),
    },
    uptimeSeconds: Number(runner.uptimeSeconds || 0),
  };
}

function compactToolSummary(...toolSets) {
  const merged = {};
  for (const toolSet of toolSets) {
    for (const [name, details] of Object.entries(toolSet || {})) {
      merged[name] = details || {};
    }
  }
  const versions = {};
  const missing = [];
  for (const [name, details] of Object.entries(merged).sort(([left], [right]) => left.localeCompare(right))) {
    const version = String(details?.version || "").trim();
    if (version) {
      versions[name] = version;
    } else {
      missing.push(name);
    }
  }
  return {
    checked: Object.keys(merged).length,
    available: Object.keys(versions).length,
    missing,
    versions,
  };
}

function compactStatsObject(stats = {}, limit = 12) {
  const entries = [];
  const visit = (prefix, value) => {
    if (entries.length >= limit || value === undefined || value === null) {
      return;
    }
    if (typeof value === "number" || typeof value === "string" || typeof value === "boolean") {
      entries.push([prefix, value]);
      return;
    }
    if (Array.isArray(value) || typeof value !== "object") {
      return;
    }
    for (const [key, nested] of Object.entries(value).sort(([left], [right]) => left.localeCompare(right))) {
      visit(prefix ? `${prefix}.${key}` : key, nested);
      if (entries.length >= limit) {
        break;
      }
    }
  };
  visit("", stats);
  return Object.fromEntries(entries);
}

function compactCompilerCacheSummary(compilerCaches = {}) {
  return Object.fromEntries(
    Object.entries(compilerCaches || {})
      .sort(([left], [right]) => left.localeCompare(right))
      .map(([name, details]) => [name, {
        available: Boolean(details?.available),
        format: details?.format || "",
        rawBytes: Number(details?.rawBytes || 0),
        error: details?.error || "",
        stats: compactStatsObject(details?.stats || {}),
      }]),
  );
}

function compactCacheSummary(cache = {}, native = {}) {
  const workspace = cache.workspace || {};
  const workspacePackages = workspace && !workspace.error && !Array.isArray(workspace) && typeof workspace === "object"
    ? Object.keys(workspace).length
    : 0;
  return {
    packageManager: cache.packageManager || {},
    workspacePackages,
    workspaceError: workspace.error || "",
    dirs: Array.isArray(cache.dirs)
      ? cache.dirs.map((entry) => ({
          path: entry.path || "",
          exists: Boolean(entry.exists),
          type: entry.type || "",
          bytes: Number(entry.bytes || 0),
        }))
      : [],
    compilerCaches: compactCompilerCacheSummary({
      ...(cache.compilerCaches || {}),
      ...(native.compilerCaches || {}),
    }),
    nativeCacheDirs: Array.isArray(native.cacheDirs)
      ? native.cacheDirs.map((entry) => ({
          path: entry.path || "",
          exists: Boolean(entry.exists),
          type: entry.type || "",
          bytes: Number(entry.bytes || 0),
        }))
      : [],
  };
}

function resolveDiagnosticsInput(entry) {
  if (typeof entry !== "string") {
    return { diagnostics: entry, sourcePath: "" };
  }
  return {
    diagnostics: readDiagnosticsArtifact(entry),
    sourcePath: path.resolve(entry),
  };
}

function buildchainRootForPath(filePath) {
  const parts = path.resolve(filePath).split(path.sep);
  const index = parts.lastIndexOf(".buildchain");
  if (index <= 0) {
    return "";
  }
  const rootParts = parts.slice(0, index);
  return rootParts.length ? rootParts.join(path.sep) || path.sep : path.sep;
}

function diagnosticsManifestCandidates(diagnostics, sourcePath) {
  if (!sourcePath) {
    return [];
  }
  const candidates = [path.join(path.dirname(sourcePath), "diagnostics-manifest.json")];
  const linkedPath = diagnostics?.links?.diagnosticsManifest || "";
  if (linkedPath) {
    if (path.isAbsolute(linkedPath)) {
      candidates.push(linkedPath);
    } else {
      const buildchainRoot = buildchainRootForPath(sourcePath);
      if (buildchainRoot) {
        candidates.push(path.resolve(buildchainRoot, linkedPath));
      }
      candidates.push(path.resolve(process.cwd(), linkedPath));
      candidates.push(path.resolve(path.dirname(sourcePath), linkedPath));
    }
  }
  return [...new Set(candidates)];
}

function compactDiagnosticsManifestFile(entry = {}) {
  return {
    kind: entry.kind || "",
    path: entry.path || "",
    bytes: Number(entry.bytes || 0),
    sha256: entry.sha256 || "",
    required: Boolean(entry.required),
  };
}

function summarizeDiagnosticsContract(diagnostics = {}) {
  const actual = diagnostics?.contract || "";
  const warnings = [];
  if (actual !== BUILDCHAIN_DIAGNOSTICS_CONTRACT) {
    warnings.push(`unexpected diagnostics artifact contract: ${actual || "unknown"}`);
  }
  return {
    status: warnings.length ? "warning" : "verified",
    expected: BUILDCHAIN_DIAGNOSTICS_CONTRACT,
    actual,
    warningCount: warnings.length,
    warnings,
  };
}

function summarizeDiagnosticsManifest(diagnostics, sourcePath) {
  if (!sourcePath) {
    return undefined;
  }
  const candidates = diagnosticsManifestCandidates(diagnostics, sourcePath);
  const manifestPath = candidates.find((candidate) => fs.existsSync(candidate)) || candidates[0] || "";
  const relativePath = manifestPath
    ? posixPath(path.relative(path.dirname(sourcePath), manifestPath))
    : "";
  if (!manifestPath || !fs.existsSync(manifestPath)) {
    return {
      status: "missing",
      path: relativePath || "diagnostics-manifest.json",
      warningCount: 1,
      warnings: ["diagnostics sidecar manifest is missing"],
    };
  }

  const { value: manifest, error } = readJsonResult(manifestPath);
  if (error) {
    return {
      status: "invalid",
      path: relativePath,
      warningCount: 1,
      warnings: [`failed to read diagnostics sidecar manifest: ${error.message}`],
    };
  }

  const warnings = [];
  if (manifest?.contract !== BUILDCHAIN_DIAGNOSTICS_MANIFEST_CONTRACT) {
    warnings.push(`unexpected diagnostics sidecar manifest contract: ${manifest?.contract || "unknown"}`);
  }
  const files = Array.isArray(manifest?.files) ? manifest.files.map(compactDiagnosticsManifestFile) : [];
  if (!Array.isArray(manifest?.files)) {
    warnings.push("diagnostics sidecar manifest files must be an array");
  }
  const diagnosticsEntry = files.find((entry) => entry.kind === "diagnostics");
  if (!diagnosticsEntry) {
    warnings.push("diagnostics sidecar manifest does not list diagnostics.json");
  } else {
    const stat = fs.statSync(sourcePath);
    const digest = sha256File(sourcePath);
    if (diagnosticsEntry.bytes !== stat.size) {
      warnings.push("diagnostics sidecar manifest bytes do not match diagnostics.json");
    }
    if (diagnosticsEntry.sha256 && diagnosticsEntry.sha256 !== digest) {
      warnings.push("diagnostics sidecar manifest sha256 does not match diagnostics.json");
    }
  }

  return {
    status: warnings.length ? "warning" : "verified",
    path: relativePath,
    artifactName: manifest?.artifactName || "",
    diagnosticsArtifactName: manifest?.diagnosticsArtifactName || "",
    platformId: manifest?.platformId || "",
    fileCount: Number(manifest?.fileCount || files.length),
    totalBytes: Number(manifest?.totalBytes || files.reduce((sum, entry) => sum + entry.bytes, 0)),
    files,
    warningCount: warnings.length,
    warnings,
  };
}

function formatDiagnosticsSummaryRows(rows = []) {
  const widths = rows[0].map((_, columnIndex) => (
    Math.max(...rows.map((row) => String(row[columnIndex] ?? "").length))
  ));
  return rows
    .map((row) => row.map((cell, index) => String(cell ?? "").padEnd(widths[index], " ")).join("  ").trimEnd())
    .join("\n");
}

export function formatDiagnosticsSummaryTable(summary = {}) {
  const rows = [[
    "platform",
    "head",
    "install",
    "build",
    "verify",
    "publish",
    "scan",
    "upload",
    "total",
    "jobs",
    "active",
    "warn",
    "err",
  ]];
  for (const platform of summary.platforms || []) {
    const label = `${platform.runner || "unknown"}/${platform.arch || "unknown"}`;
    const processSummary = compactProcessSummary(platform.process);
    rows.push([
      label,
      platform.gitHead ? platform.gitHead.slice(0, 12) : "-",
      formatDiagnosticsDurationMs(stageDurationMs(platform.lifecycle, "install")),
      formatDiagnosticsDurationMs(stageDurationMs(platform.lifecycle, "build")),
      formatDiagnosticsDurationMs(stageDurationMs(platform.lifecycle, "verify")),
      formatDiagnosticsDurationMs(stageDurationMs(platform.lifecycle, "publish")),
      formatDiagnosticsDurationMs(platform.artifactScanDurationMs),
      formatDiagnosticsDurationMs(platform.artifactUploadDurationMs),
      formatDiagnosticsDurationMs(platform.totalDurationMs),
      formatDiagnosticsProcessValue(processSummary.requestedParallelism),
      formatDiagnosticsProcessValue(processSummary.observedConcurrencyMax),
      platform.warningCount || 0,
      platform.errorCount || 0,
    ]);
  }
  return formatDiagnosticsSummaryRows(rows);
}

export function summarizeDiagnosticsArtifacts(inputs = []) {
  const diagnostics = inputs
    .map(resolveDiagnosticsInput)
    .filter((entry) => entry.diagnostics);
  const platforms = diagnostics.map(({ diagnostics: entry, sourcePath }) => {
    const lifecycle = entry.lifecycleObservability?.stages || {};
    const lifecycleTotalDurationMs = sumLifecycleDurationMs(lifecycle);
    const artifactScanDurationMs = Math.round(Number(entry.lifecycleObservability?.artifactScan?.durationMs || 0));
    const artifactUploadDurationMs = Math.round(Number(entry.lifecycleObservability?.artifactUpload?.durationMs || 0));
    const diagnosticsContract = summarizeDiagnosticsContract(entry);
    const diagnosticsManifest = summarizeDiagnosticsManifest(entry, sourcePath);
    return {
      runner: entry.runner?.github?.runnerOs || entry.runner?.os?.platform || "unknown",
      arch: entry.runner?.github?.runnerArch || entry.runner?.os?.arch || "unknown",
      gitHead: entry.git?.head || "",
      lifecycle,
      lifecycleTotalDurationMs,
      artifactScanDurationMs,
      artifactUploadDurationMs,
      totalDurationMs: lifecycleTotalDurationMs + artifactScanDurationMs + artifactUploadDurationMs,
      totalBytes: Number(entry.lifecycleObservability?.totalBytes || 0),
      fileCount: Number(entry.lifecycleObservability?.fileCount || 0),
      topSlowSpans: (entry.lifecycleObservability?.topSlowSpans || []).slice(0, 5),
      runnerDetails: compactRunnerDetails(entry.runner || {}),
      tools: compactToolSummary(entry.tools || {}, entry.native?.tools || {}),
      cache: compactCacheSummary(entry.cache || {}, entry.native || {}),
      compilerCaches: compactCompilerCacheSummary(entry.compilerCaches || entry.native?.compilerCaches || entry.cache?.compilerCaches || {}),
      nativeCacheDirs: Array.isArray(entry.nativeCacheDirs)
        ? entry.nativeCacheDirs
        : Array.isArray(entry.native?.cacheDirs)
          ? entry.native.cacheDirs
          : [],
      process: entry.process || {},
      sourceCheckout: entry.sourceCheckout
        ? {
            mode: entry.sourceCheckout.policy?.mode || "",
            transport: entry.sourceCheckout.cache?.transport || "",
            hit: Boolean(entry.sourceCheckout.cache?.hit),
            fallbackUsed: Boolean(entry.sourceCheckout.cache?.fallbackUsed),
            fallbackReason: entry.sourceCheckout.cache?.fallbackReason || "",
            durationMs: Number(entry.sourceCheckout.durationMs || 0),
            headOk: Boolean(entry.sourceCheckout.verification?.headOk),
            treeOk: Boolean(entry.sourceCheckout.verification?.treeOk),
          }
        : undefined,
      diagnosticsContract,
      ...(diagnosticsManifest ? { diagnosticsManifest } : {}),
      links: entry.links || {},
      warningCount: entry.lifecycleObservability?.warningCount || 0,
      errorCount: entry.lifecycleObservability?.errorCount || 0,
    };
  });
  return {
    schemaVersion: 1,
    contract: BUILDCHAIN_DIAGNOSTICS_SUMMARY_CONTRACT,
    generatedAt: new Date().toISOString(),
    count: diagnostics.length,
    totalWarningCount: platforms.reduce((sum, entry) => sum + entry.warningCount, 0),
    totalErrorCount: platforms.reduce((sum, entry) => sum + entry.errorCount, 0),
    diagnosticsManifestWarningCount: platforms.reduce(
      (sum, entry) => sum + Number(entry.diagnosticsManifest?.warningCount || 0),
      0,
    ),
    diagnosticsContractWarningCount: platforms.reduce(
      (sum, entry) => sum + Number(entry.diagnosticsContract?.warningCount || 0),
      0,
    ),
    slowestPlatforms: platforms
      .map(({ runner, arch, gitHead, lifecycleTotalDurationMs, totalDurationMs, process }) => ({
        runner,
        arch,
        gitHead,
        lifecycleTotalDurationMs,
        totalDurationMs,
        process: compactProcessSummary(process),
      }))
      .sort((left, right) => right.totalDurationMs - left.totalDurationMs)
      .slice(0, 10),
    platforms,
  };
}

import fs from "node:fs";
import path from "node:path";
import { readJsonFromLocation, sha256Text, verifyReleasePassport } from "./release-passport.js";

export const HOMEBREW_TAP_FACTS_CONTRACT = "kungfu-buildchain-homebrew-tap-facts";
export const HOMEBREW_TAP_CHECK_CONTRACT = "kungfu-buildchain-homebrew-tap-check";
export const HOMEBREW_TAP_MANIFEST_CONTRACT = "kungfu-buildchain-homebrew-tap-manifest";

const DEFAULT_MANIFEST_PATH = "tap-manifest.json";
const DEFAULT_FORMULA_PATH = "Formula/buildchain.rb";
const KFD_KEYS = ["kfd-1", "kfd-2", "kfd-3"];
const SUPPORTED_FORMULA_PLATFORMS = new Set(["darwin-arm64", "linux-x64"]);

function readJsonFile(filePath, fallback = undefined) {
  if (!fs.existsSync(filePath)) {
    return fallback;
  }
  return JSON.parse(fs.readFileSync(filePath, "utf8"));
}

function writeJsonFile(filePath, value) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, `${JSON.stringify(value, null, 2)}\n`);
}

function writeTextFile(filePath, value) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, value.endsWith("\n") ? value : `${value}\n`);
}

function optionalString(value) {
  return value === undefined || value === null ? "" : String(value);
}

function nonEmptyString(value, label) {
  const normalized = optionalString(value).trim();
  if (!normalized) {
    throw new Error(`${label} must be a non-empty string`);
  }
  return normalized;
}

function digestWithoutPrefix(value) {
  return optionalString(value).replace(/^sha256:/, "");
}

function stableJson(value) {
  if (Array.isArray(value)) {
    return `[${value.map(stableJson).join(",")}]`;
  }
  if (value && typeof value === "object") {
    return `{${Object.keys(value)
      .sort()
      .map((key) => `${JSON.stringify(key)}:${stableJson(value[key])}`)
      .join(",")}}`;
  }
  return JSON.stringify(value);
}

function formulaClassName(name) {
  return nonEmptyString(name, "package name")
    .replace(/^@[^/]+\//, "")
    .split(/[^A-Za-z0-9]+/)
    .filter(Boolean)
    .map((part) => `${part.slice(0, 1).toUpperCase()}${part.slice(1)}`)
    .join("");
}

function rubyString(value) {
  return optionalString(value).replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}

function inferPlatformFromName(name) {
  const lower = optionalString(name).toLowerCase();
  if (lower.includes("apple-darwin") || lower.includes("darwin") || lower.includes("macos")) {
    return lower.includes("aarch64") || lower.includes("arm64") ? "darwin-arm64" : "darwin-x64";
  }
  if (lower.includes("windows") || lower.includes("pc-windows") || lower.endsWith(".zip")) {
    return "windows-x64";
  }
  if (lower.includes("linux") || lower.includes("unknown-linux")) {
    return lower.includes("aarch64") || lower.includes("arm64") ? "linux-arm64" : "linux-x64";
  }
  return "";
}

function normalizeRepository(value = "") {
  const raw = optionalString(value).trim();
  if (!raw) return "";
  const githubMatch = raw.match(/github\.com[:/]([^/\s]+\/[^/\s#]+?)(?:\.git)?(?:[#/?].*)?$/);
  if (githubMatch) return githubMatch[1].replace(/\.git$/, "");
  if (/^[^/\s]+\/[^/\s]+$/.test(raw)) return raw.replace(/\.git$/, "");
  return raw;
}

function releaseDirectoryUrl(releasePassportLocation = "") {
  if (!/^https?:\/\//.test(releasePassportLocation)) return "";
  const url = new URL(releasePassportLocation);
  url.pathname = url.pathname.replace(/\/[^/]*$/, "/");
  return url.toString();
}

function githubAssetUrl(repository, tag, name) {
  const repo = normalizeRepository(repository);
  if (!repo || !tag || !name) return "";
  return `https://github.com/${repo}/releases/download/${encodeURIComponent(tag)}/${encodeURIComponent(name)}`;
}

function siblingAssetUrl(releasePassportLocation, name) {
  const base = releaseDirectoryUrl(releasePassportLocation);
  return base ? new URL(encodeURIComponent(name), base).toString() : "";
}

function normalizeArtifact(artifact, { releasePassportLocation = "", repository = "", tag = "" } = {}) {
  const name = nonEmptyString(artifact.name || artifact.filename, "artifact.name");
  const platform = optionalString(artifact.platform || inferPlatformFromName(name));
  return {
    name,
    platform,
    url: optionalString(artifact.url || artifact.browser_download_url || artifact.downloadUrl)
      || siblingAssetUrl(releasePassportLocation, name)
      || githubAssetUrl(repository, tag, name),
    sha256: digestWithoutPrefix(artifact.sha256 || artifact.digest || artifact.checksum),
  };
}

function formulaArchiveArtifacts(passport, context) {
  return (passport.artifacts || [])
    .map((artifact) => normalizeArtifact(artifact, context))
    .filter((artifact) => SUPPORTED_FORMULA_PLATFORMS.has(artifact.platform))
    .filter((artifact) => /\.(?:tar\.gz|tgz)$/i.test(artifact.name))
    .sort((left, right) => left.platform.localeCompare(right.platform));
}

function readTapManifest(cwd, manifestPath = DEFAULT_MANIFEST_PATH) {
  const filePath = path.join(cwd, manifestPath);
  const manifest = readJsonFile(filePath, {
    schema: 1,
    contract: HOMEBREW_TAP_MANIFEST_CONTRACT,
    name: "",
    kind: "homebrew-tap",
    entries: [],
  });
  if (!manifest || typeof manifest !== "object" || Array.isArray(manifest)) {
    throw new Error(`${manifestPath} must be a JSON object`);
  }
  if (manifest.schema !== undefined && manifest.schema !== 1) {
    throw new Error(`${manifestPath} schema must be 1`);
  }
  if (manifest.schemaVersion !== undefined && manifest.schemaVersion !== 1) {
    throw new Error(`${manifestPath} schemaVersion must be 1`);
  }
  if (manifest.entries !== undefined && !Array.isArray(manifest.entries)) {
    throw new Error(`${manifestPath} entries must be an array`);
  }
  return manifest;
}

function findManifestEntry(manifest, packageName) {
  return (manifest.entries || []).find((entry) => entry?.type === "formula" && entry.name === packageName);
}

async function verifyPassportLocation(location) {
  try {
    const report = await verifyReleasePassport({ passportLocation: location });
    return { ok: report.ok === true, report, error: "" };
  } catch (error) {
    return { ok: false, report: undefined, error: error.message };
  }
}

function createKfdProjection(passport, verified) {
  return Object.fromEntries(KFD_KEYS.map((key) => [
    key,
    verified && passport?.[key]?.status === "passed" ? "passed" : "unverified",
  ]));
}

function createManifestProjection({
  manifest,
  entry,
  packageName,
  formulaPath,
  releasePassportLocation,
  passport,
  artifacts,
  kfd,
  repository,
} = {}) {
  const tag = nonEmptyString(passport.release?.tag, "release.tag");
  const version = nonEmptyString(passport.release?.publishedVersion || passport.release?.versionLabel, "release.publishedVersion");
  const repo = normalizeRepository(repository || entry?.upstream?.repository || passport.product?.repository);
  const latestReleasePassportUrl = optionalString(entry?.upstream?.latestReleasePassportUrl)
    || (repo ? `https://github.com/${repo}/releases/latest/download/buildchain.release.json` : "");
  return {
    schema: 1,
    contract: HOMEBREW_TAP_MANIFEST_CONTRACT,
    name: optionalString(manifest.name || (repo ? `${repo.replace(/\/[^/]+$/, "")}/homebrew-tap` : "")),
    kind: "homebrew-tap",
    entries: [
      {
        type: "formula",
        name: packageName,
        path: formulaPath,
        upstream: {
          repository: repo,
          tag,
          releasePassportUrl: releasePassportLocation,
          latestReleasePassportUrl,
        },
        version,
        kfd,
        artifacts: artifacts.map((artifact) => ({
          platform: artifact.platform,
          url: artifact.url,
          sha256: artifact.sha256,
        })),
      },
    ],
  };
}

export async function collectHomebrewTapFacts({
  cwd = process.cwd(),
  packageName = "buildchain",
  releasePassport = "",
  manifestPath = DEFAULT_MANIFEST_PATH,
  formulaPath = "",
} = {}) {
  const resolvedCwd = path.resolve(cwd);
  const manifest = readTapManifest(resolvedCwd, manifestPath);
  const entry = findManifestEntry(manifest, packageName);
  const selectedFormulaPath = formulaPath || entry?.path || (packageName === "buildchain" ? DEFAULT_FORMULA_PATH : `Formula/${packageName}.rb`);
  const releasePassportLocation = nonEmptyString(
    releasePassport || entry?.upstream?.releasePassportUrl || entry?.releasePassport,
    "release passport",
  );
  const passport = await readJsonFromLocation(releasePassportLocation);
  const verification = await verifyPassportLocation(releasePassportLocation);
  const repository = normalizeRepository(entry?.upstream?.repository || passport.product?.repository);
  const artifacts = formulaArchiveArtifacts(passport, {
    releasePassportLocation,
    repository,
    tag: passport.release?.tag,
  });
  const kfd = createKfdProjection(passport, verification.ok);
  const manifestProjection = createManifestProjection({
    manifest,
    entry,
    packageName,
    formulaPath: selectedFormulaPath,
    releasePassportLocation,
    passport,
    artifacts,
    kfd,
    repository,
  });
  return {
    schemaVersion: 1,
    contract: HOMEBREW_TAP_FACTS_CONTRACT,
    cwd: resolvedCwd,
    package: {
      name: packageName,
      formulaClass: formulaClassName(packageName),
      desc: optionalString(entry?.formula?.desc || "Release passport and build evidence toolkit"),
      homepage: optionalString(entry?.formula?.homepage || passport.product?.homepage || "https://buildchain.libkungfu.dev"),
      license: optionalString(entry?.formula?.license || "Apache-2.0"),
    },
    releasePassport: {
      location: releasePassportLocation,
      verified: verification.ok,
      verificationError: verification.error,
      report: verification.report,
    },
    release: {
      tag: passport.release?.tag || "",
      version: passport.release?.publishedVersion || passport.release?.versionLabel || "",
      repository,
    },
    formula: {
      path: selectedFormulaPath,
      artifacts,
    },
    kfd,
    manifestPath,
    manifestProjection,
  };
}

export function renderHomebrewFormula(facts) {
  if (!facts || facts.contract !== HOMEBREW_TAP_FACTS_CONTRACT) {
    throw new Error("facts must be collected with collectHomebrewTapFacts");
  }
  const artifacts = facts.formula?.artifacts || [];
  const darwinArm64 = artifacts.find((artifact) => artifact.platform === "darwin-arm64");
  const linuxX64 = artifacts.find((artifact) => artifact.platform === "linux-x64");
  if (!darwinArm64 || !linuxX64) {
    throw new Error("Homebrew formula requires darwin-arm64 and linux-x64 tar.gz artifacts");
  }
  return `class ${facts.package.formulaClass} < Formula
  desc "${rubyString(facts.package.desc)}"
  homepage "${rubyString(facts.package.homepage)}"
  version "${rubyString(facts.release.version)}"
  license "${rubyString(facts.package.license)}"

  if OS.mac? && Hardware::CPU.arm?
    url "${rubyString(darwinArm64.url)}"
    sha256 "${rubyString(darwinArm64.sha256)}"
  elsif OS.linux? && Hardware::CPU.intel?
    url "${rubyString(linuxX64.url)}"
    sha256 "${rubyString(linuxX64.sha256)}"
  else
    odie "${facts.package.formulaClass} Homebrew formula currently supports macOS arm64 and Linux x86_64 binary archives."
  end

  def install
    bin.install "${rubyString(facts.package.name)}"
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/${rubyString(facts.package.name)} version")
  end
end
`;
}

function checkStatus(ok, id, message, details = {}) {
  return { id, status: ok ? "pass" : "fail", message, details };
}

function sameJson(left, right) {
  return stableJson(left) === stableJson(right);
}

export async function checkHomebrewTap({
  cwd = process.cwd(),
  packageName = "buildchain",
  releasePassport = "",
  manifestPath = DEFAULT_MANIFEST_PATH,
  formulaPath = "",
} = {}) {
  const facts = await collectHomebrewTapFacts({ cwd, packageName, releasePassport, manifestPath, formulaPath });
  const expectedFormula = renderHomebrewFormula(facts);
  const expectedManifest = facts.manifestProjection;
  const formulaFilePath = path.join(facts.cwd, facts.formula.path);
  const manifestFilePath = path.join(facts.cwd, facts.manifestPath);
  const currentFormula = fs.existsSync(formulaFilePath) ? fs.readFileSync(formulaFilePath, "utf8") : "";
  const currentManifest = readJsonFile(manifestFilePath, undefined);
  const formulaCurrent = currentFormula === expectedFormula;
  const manifestCurrent = currentManifest !== undefined && sameJson(currentManifest, expectedManifest);
  const checks = [
    checkStatus(facts.releasePassport.verified, "upstream-passport.verified", "upstream release passport verifies", {
      error: facts.releasePassport.verificationError,
    }),
    checkStatus((facts.formula.artifacts || []).length >= 2, "formula.artifacts", "formula has required platform artifacts", {
      platforms: (facts.formula.artifacts || []).map((artifact) => artifact.platform),
    }),
    checkStatus(formulaCurrent, "formula.current", "Formula is current with upstream passport projection", {
      path: facts.formula.path,
      expectedSha256: sha256Text(expectedFormula),
      actualSha256: currentFormula ? sha256Text(currentFormula) : "",
    }),
    checkStatus(manifestCurrent, "tap-manifest.current", "tap manifest is current with upstream passport projection", {
      path: facts.manifestPath,
      expectedSha256: sha256Text(`${JSON.stringify(expectedManifest, null, 2)}\n`),
      actualSha256: currentManifest ? sha256Text(`${JSON.stringify(currentManifest, null, 2)}\n`) : "",
    }),
    ...KFD_KEYS.map((key) => checkStatus(
      facts.kfd[key] === "passed",
      `kfd.${key}`,
      `${key} passed is backed by verified upstream release passport`,
      { status: facts.kfd[key] },
    )),
  ];
  return {
    schemaVersion: 1,
    contract: HOMEBREW_TAP_CHECK_CONTRACT,
    cwd: facts.cwd,
    ok: checks.every((check) => check.status === "pass"),
    package: packageName,
    checks,
    facts,
    expected: {
      formula: expectedFormula,
      manifest: expectedManifest,
    },
  };
}

export async function updateHomebrewTap({
  cwd = process.cwd(),
  packageName = "buildchain",
  releasePassport = "",
  manifestPath = DEFAULT_MANIFEST_PATH,
  formulaPath = "",
  write = true,
} = {}) {
  const facts = await collectHomebrewTapFacts({ cwd, packageName, releasePassport, manifestPath, formulaPath });
  const formula = renderHomebrewFormula(facts);
  const manifest = facts.manifestProjection;
  if (write) {
    writeTextFile(path.join(facts.cwd, facts.formula.path), formula);
    writeJsonFile(path.join(facts.cwd, facts.manifestPath), manifest);
  }
  return {
    schemaVersion: 1,
    contract: "kungfu-buildchain-homebrew-tap-update",
    ok: true,
    written: write ? [facts.formula.path, facts.manifestPath] : [],
    facts,
    formula,
    manifest,
  };
}

import crypto from "node:crypto";
import fs from "node:fs";

export const BUILDCHAIN_CONSUMER_ISSUE_CONTRACT = "kungfu-buildchain-consumer-issue";
export const BUILDCHAIN_WORKFLOW_FRICTION_ISSUE_CONTRACT = "kungfu-buildchain-workflow-friction-issue";
export const DEFAULT_BUILDCHAIN_ISSUE_REPOSITORY = "kungfu-systems/buildchain";

const DEFAULT_LABELS = ["buildchain-consumer-feedback"];
const DEFAULT_FRICTION_LABELS = ["buildchain-feedback", "workflow-friction"];
const DEFAULT_MAX_BODY_BYTES = 60_000;
const DEFAULT_RETRY_DELAYS_MS = [500, 1_500, 3_000];

const SECRET_PATTERNS = [
  /\bgithub_pat_[A-Za-z0-9_]{20,}\b/g,
  /\bgh[oprsu]_[A-Za-z0-9_]{20,}\b/g,
  /\b[A-Z0-9]{20}:[A-Za-z0-9_=-]{20,}\b/g,
  /\bAKIA[0-9A-Z]{16}\b/g,
  /(authorization\s*:\s*)(bearer\s+)?[^\s]+/gi,
  /(token|secret|password|private[_-]?key)(\s*[:=]\s*)[^\s"'`]+/gi,
  /-----BEGIN [^-]+PRIVATE KEY-----[\s\S]*?-----END [^-]+PRIVATE KEY-----/g,
];

export class GitHubIssueRequestError extends Error {
  constructor(message, { status, response, body } = {}) {
    super(message);
    this.name = "GitHubIssueRequestError";
    this.status = status;
    this.response = response;
    this.body = body;
  }
}

export function normalizeIssueRepository(repository = DEFAULT_BUILDCHAIN_ISSUE_REPOSITORY) {
  const match = String(repository || "").trim().match(/^([^/\s]+)\/([^/\s]+)$/);
  if (!match) {
    throw new Error(`Invalid GitHub repository: ${repository}`);
  }
  return { owner: match[1], repo: match[2], fullName: `${match[1]}/${match[2]}` };
}

export function parseIssueLabels(input = DEFAULT_LABELS) {
  if (Array.isArray(input)) {
    return input.map((label) => String(label).trim()).filter(Boolean);
  }
  return String(input || "")
    .split(/[,\n]/)
    .map((label) => label.trim())
    .filter(Boolean);
}

export function redactIssueText(value) {
  let text = String(value ?? "");
  for (const pattern of SECRET_PATTERNS) {
    text = text.replace(pattern, (...args) => {
      if (args.length >= 4 && typeof args[1] === "string" && typeof args[2] === "string") {
        return `${args[1]}${args[2]}[REDACTED]`;
      }
      return "[REDACTED]";
    });
  }
  return text;
}

export function computeConsumerIssueFingerprint(fields = {}) {
  const normalized = {};
  for (const key of Object.keys(fields).sort()) {
    const value = fields[key];
    if (value === undefined || value === null || value === "") {
      continue;
    }
    normalized[key] = String(value);
  }
  return crypto.createHash("sha256").update(JSON.stringify(normalized)).digest("hex").slice(0, 32);
}

export function consumerIssueMarker(fingerprint) {
  return `buildchain-consumer-issue:fingerprint=${fingerprint}`;
}

export function workflowFrictionMarker(fingerprint) {
  return `buildchain-workflow-friction:fingerprint=${fingerprint}`;
}

export function truncateUtf8(text, maxBytes = DEFAULT_MAX_BODY_BYTES) {
  const value = String(text ?? "");
  if (!Number.isFinite(maxBytes) || maxBytes <= 0 || Buffer.byteLength(value, "utf8") <= maxBytes) {
    return value;
  }
  const suffix = "\n\n[buildchain truncated issue body]\n";
  const budget = Math.max(0, maxBytes - Buffer.byteLength(suffix, "utf8"));
  let output = "";
  let used = 0;
  for (const char of value) {
    const bytes = Buffer.byteLength(char, "utf8");
    if (used + bytes > budget) {
      break;
    }
    output += char;
    used += bytes;
  }
  return `${output}${suffix}`;
}

export function buildConsumerIssueReport(options = {}) {
  const target = normalizeIssueRepository(options.targetRepository);
  const env = options.env || process.env;
  const consumerRepository = options.consumerRepository || env.GITHUB_REPOSITORY || "";
  const runId = options.runId || env.GITHUB_RUN_ID || "";
  const runUrl = options.runUrl || githubRunUrl(env, consumerRepository, runId);
  const workflow = options.workflow || env.GITHUB_WORKFLOW || "";
  const job = options.job || env.GITHUB_JOB || "";
  const consumerRef = options.consumerRef || env.GITHUB_REF || "";
  const consumerSha = options.consumerSha || env.GITHUB_SHA || "";
  const failureCode = options.failureCode || "consumer-report";
  const fingerprint =
    options.fingerprint ||
    computeConsumerIssueFingerprint({
      targetRepository: target.fullName,
      consumerRepository,
      workflow,
      job,
      failureCode,
      buildchainRef: options.buildchainRef,
      buildchainVersion: options.buildchainVersion,
      title: options.title,
    });
  const title = redactIssueText(
    options.title ||
      `[Buildchain consumer] ${consumerRepository || "unknown repository"}: ${failureCode}`,
  );
  const marker = consumerIssueMarker(fingerprint);
  const body = truncateUtf8(
    redactIssueText(
      [
        `<!-- ${marker} -->`,
        `# Buildchain consumer report`,
        ``,
        options.summary ? `## Summary\n\n${options.summary}` : "",
        `## Consumer`,
        ``,
        `- Repository: ${consumerRepository || "(unknown)"}`,
        `- Ref: ${consumerRef || "(unknown)"}`,
        `- SHA: ${consumerSha || "(unknown)"}`,
        `- Workflow: ${workflow || "(unknown)"}`,
        `- Job: ${job || "(unknown)"}`,
        `- Run: ${runUrl || runId || "(unknown)"}`,
        ``,
        `## Buildchain`,
        ``,
        `- Ref: ${options.buildchainRef || "(unknown)"}`,
        `- Version: ${options.buildchainVersion || "(unknown)"}`,
        `- Failure code: ${failureCode}`,
        `- Fingerprint: ${fingerprint}`,
        ``,
        optionalLine("## Release Passport", options.passportUrl || options.passportPath),
        optionalLine("## Diagnostics", options.diagnosticsUrl || options.diagnosticsPath),
        optionalLine("## Artifact", options.artifactUrl),
        options.body ? `## Details\n\n${options.body}` : "",
      ]
        .filter(Boolean)
        .join("\n"),
    ),
    Number(options.maxBodyBytes || DEFAULT_MAX_BODY_BYTES),
  );
  const commentBody = truncateUtf8(
    redactIssueText(
      [
        `New matching Buildchain consumer report observed.`,
        ``,
        `- Repository: ${consumerRepository || "(unknown)"}`,
        `- Ref: ${consumerRef || "(unknown)"}`,
        `- SHA: ${consumerSha || "(unknown)"}`,
        `- Workflow: ${workflow || "(unknown)"}`,
        `- Run: ${runUrl || runId || "(unknown)"}`,
        `- Failure code: ${failureCode}`,
        `- Fingerprint: ${fingerprint}`,
        options.summary ? `\n${options.summary}` : "",
      ].join("\n"),
    ),
    Number(options.maxBodyBytes || DEFAULT_MAX_BODY_BYTES),
  );
  return {
    contract: BUILDCHAIN_CONSUMER_ISSUE_CONTRACT,
    targetRepository: target.fullName,
    fingerprint,
    marker,
    title,
    body,
    commentBody,
    labels: parseIssueLabels(options.labels ?? DEFAULT_LABELS),
  };
}

export function buildWorkflowFrictionIssueReport(options = {}) {
  const target = normalizeIssueRepository(options.targetRepository);
  const env = options.env || process.env;
  const repository = options.repository || env.GITHUB_REPOSITORY || "";
  const workflow = options.workflow || env.GITHUB_WORKFLOW || "";
  const runId = options.runId || env.GITHUB_RUN_ID || "";
  const runAttempt = options.runAttempt || env.GITHUB_RUN_ATTEMPT || "";
  const runUrl = options.runUrl || githubRunUrl(env, repository, runId);
  const channel = options.channel || "";
  const releaseIntent = options.releaseIntent || options.version || "";
  const sourceRef = options.sourceRef || env.GITHUB_REF || "";
  const sourceSha = options.sourceSha || env.GITHUB_SHA || "";
  const frictionClass = options.frictionClass || "workflow-friction";
  const fingerprint = options.fingerprint || computeConsumerIssueFingerprint({
    targetRepository: target.fullName,
    repository,
    workflow,
    channel,
    releaseIntent,
    sourceRef,
    sourceSha,
    frictionClass,
  });
  const marker = workflowFrictionMarker(fingerprint);
  const heavyBuilds = Array.isArray(options.heavyBuilds) ? options.heavyBuilds : [];
  const relatedRuns = Array.isArray(options.relatedRuns) ? options.relatedRuns : [];
  const title = redactIssueText(
    options.title || `[Buildchain feedback] ${frictionClass}: ${repository || "unknown repository"}`,
  );
  const body = truncateUtf8(
    redactIssueText(
      [
        `<!-- ${marker} -->`,
        `# Buildchain workflow friction`,
        ``,
        options.summary ? `## Summary\n\n${options.summary}` : "",
        `## Context`,
        ``,
        `- Repository: ${repository || "(unknown)"}`,
        `- Workflow: ${workflow || "(unknown)"}`,
        `- Run: ${runUrl || runId || "(unknown)"}`,
        `- Attempt: ${runAttempt || "(unknown)"}`,
        `- Pull request: ${options.pullRequest || "(unknown)"}`,
        `- Channel: ${channel || "(unknown)"}`,
        `- Release intent: ${releaseIntent || "(unknown)"}`,
        `- Source ref: ${sourceRef || "(unknown)"}`,
        `- Source SHA: ${sourceSha || "(unknown)"}`,
        `- Source tree: ${options.sourceTreeHash || "(unknown)"}`,
        `- Friction class: ${frictionClass}`,
        `- Fingerprint: ${fingerprint}`,
        ``,
        relatedRuns.length ? `## Related runs\n\n${relatedRuns.map((run) => `- ${run}`).join("\n")}` : "",
        heavyBuilds.length ? `## Heavy build jobs\n\n${heavyBuilds.map((job) => `- ${job.name || job}: ${job.durationMs || ""}`).join("\n")}` : "",
        options.diagnosis ? `## Diagnosis\n\n${options.diagnosis}` : "",
        options.nextAction ? `## Suggested next action\n\n${options.nextAction}` : "",
        options.body ? `## Details\n\n${options.body}` : "",
      ].filter(Boolean).join("\n"),
    ),
    Number(options.maxBodyBytes || DEFAULT_MAX_BODY_BYTES),
  );
  const commentBody = truncateUtf8(
    redactIssueText(
      [
        `New matching Buildchain workflow friction observed.`,
        ``,
        `- Repository: ${repository || "(unknown)"}`,
        `- Workflow: ${workflow || "(unknown)"}`,
        `- Run: ${runUrl || runId || "(unknown)"}`,
        `- Attempt: ${runAttempt || "(unknown)"}`,
        `- Friction class: ${frictionClass}`,
        `- Fingerprint: ${fingerprint}`,
        options.summary ? `\n${options.summary}` : "",
      ].join("\n"),
    ),
    Number(options.maxBodyBytes || DEFAULT_MAX_BODY_BYTES),
  );
  return {
    contract: BUILDCHAIN_WORKFLOW_FRICTION_ISSUE_CONTRACT,
    targetRepository: target.fullName,
    fingerprint,
    marker,
    title,
    body,
    commentBody,
    labels: parseIssueLabels(options.labels ?? DEFAULT_FRICTION_LABELS),
  };
}

export async function reportBuildchainIssue(options = {}) {
  const report = options.report || buildConsumerIssueReport(options);
  const target = normalizeIssueRepository(report.targetRepository);
  const mode = options.mode || "create-or-comment";
  if (options.dryRun) {
    return {
      ok: true,
      action: "dry-run",
      created: false,
      commented: false,
      issueNumber: "",
      issueUrl: "",
      fingerprint: report.fingerprint,
      report,
    };
  }
  if (!["create", "create-or-comment", "comment"].includes(mode)) {
    throw new Error(`Unsupported consumer issue mode: ${mode}`);
  }
  const request = options.request || createGitHubIssueRequest(options);
  const existing = mode === "create" ? undefined : await findOpenConsumerIssue({ request, target, report });
  if (existing) {
    if (mode !== "create-or-comment" && mode !== "comment") {
      return {
        ok: true,
        action: "found",
        created: false,
        commented: false,
        issueNumber: existing.number,
        issueUrl: existing.html_url || existing.url || "",
        fingerprint: report.fingerprint,
        report,
      };
    }
    const cooldown = await evaluateCommentCooldown({
      request,
      target,
      issueNumber: existing.number,
      cooldownHours: options.commentCooldownHours,
      now: options.now,
    });
    if (cooldown.active) {
      return {
        ok: true,
        action: "cooldown",
        created: false,
        commented: false,
        issueNumber: existing.number,
        issueUrl: existing.html_url || existing.url || "",
        fingerprint: report.fingerprint,
        report,
        cooldown,
      };
    }
    await request({
      method: "POST",
      path: `/repos/${target.owner}/${target.repo}/issues/${existing.number}/comments`,
      body: { body: report.commentBody },
    });
    return {
      ok: true,
      action: "commented",
      created: false,
      commented: true,
      issueNumber: existing.number,
      issueUrl: existing.html_url || existing.url || "",
      fingerprint: report.fingerprint,
      report,
    };
  }
  if (mode === "comment") {
    throw new Error(`No open Buildchain consumer issue found for fingerprint ${report.fingerprint}`);
  }
  const issue = await createIssueWithLabelFallback({ request, target, report });
  return {
    ok: true,
    action: "created",
    created: true,
    commented: false,
    issueNumber: issue.number,
    issueUrl: issue.html_url || issue.url || "",
    fingerprint: report.fingerprint,
    report,
  };
}

export async function reportWorkflowFrictionIssue(options = {}) {
  return reportBuildchainIssue({
    ...options,
    report: buildWorkflowFrictionIssueReport(options),
  });
}

export function readOptionalIssueBodyFile(filePath) {
  const resolved = String(filePath || "").trim();
  if (!resolved) {
    return "";
  }
  return fs.readFileSync(resolved, "utf8");
}

export function createGitHubIssueRequest({
  token,
  apiUrl = process.env.GITHUB_API_URL || "https://api.github.com",
  fetchImpl = globalThis.fetch,
  retryDelaysMs = DEFAULT_RETRY_DELAYS_MS,
} = {}) {
  if (!token) {
    throw new Error("A GitHub token is required to report a Buildchain issue");
  }
  if (typeof fetchImpl !== "function") {
    throw new Error("A fetch implementation is required to report a Buildchain issue");
  }
  const baseUrl = String(apiUrl || "https://api.github.com").replace(/\/+$/, "");
  return async function githubIssueRequest({ method = "GET", path, body }) {
    const url = `${baseUrl}${path}`;
    let attempt = 0;
    while (true) {
      try {
        const response = await fetchImpl(url, {
          method,
          headers: {
            accept: "application/vnd.github+json",
            authorization: `Bearer ${token}`,
            "content-type": "application/json",
            "x-github-api-version": "2022-11-28",
          },
          body: body === undefined ? undefined : JSON.stringify(body),
        });
        const text = await response.text();
        const parsed = text ? parseJsonResponse(text) : {};
        if (response.ok) {
          return parsed;
        }
        const retryAfterMs = retryAfterHeaderMs(response.headers?.get?.("retry-after"));
        if (shouldRetryStatus(response.status) && attempt < retryDelaysMs.length) {
          await sleep(retryAfterMs ?? retryDelaysMs[attempt]);
          attempt += 1;
          continue;
        }
        throw new GitHubIssueRequestError(
          `GitHub API ${method} ${path} failed with ${response.status}: ${parsed.message || text}`,
          { status: response.status, response: parsed, body },
        );
      } catch (error) {
        if (error instanceof GitHubIssueRequestError) {
          throw error;
        }
        if (attempt < retryDelaysMs.length) {
          await sleep(retryDelaysMs[attempt]);
          attempt += 1;
          continue;
        }
        throw new GitHubIssueRequestError(`GitHub API ${method} ${path} failed: ${error.message}`, {
          body,
        });
      }
    }
  };
}

async function findOpenConsumerIssue({ request, target, report }) {
  const query = encodeURIComponent(
    `repo:${target.fullName} is:issue is:open "${report.marker || consumerIssueMarker(report.fingerprint)}"`,
  );
  const result = await request({ method: "GET", path: `/search/issues?q=${query}&per_page=1` });
  const items = Array.isArray(result.items) ? result.items : [];
  return items[0];
}

async function evaluateCommentCooldown({
  request,
  target,
  issueNumber,
  cooldownHours = 0,
  now = new Date(),
}) {
  const hours = Number(cooldownHours || 0);
  if (!Number.isFinite(hours) || hours <= 0) {
    return { active: false, cooldownHours: 0 };
  }
  const result = await request({
    method: "GET",
    path: `/repos/${target.owner}/${target.repo}/issues/${issueNumber}/comments?per_page=100`,
  });
  const comments = Array.isArray(result) ? result : [];
  const latest = comments[comments.length - 1]?.created_at || "";
  if (!latest) {
    return { active: false, cooldownHours: hours };
  }
  const latestMs = Date.parse(latest);
  const nowMs = now instanceof Date ? now.getTime() : Date.parse(String(now));
  if (!Number.isFinite(latestMs) || !Number.isFinite(nowMs)) {
    return { active: false, cooldownHours: hours, latestCommentAt: latest };
  }
  const elapsedHours = (nowMs - latestMs) / 3_600_000;
  return {
    active: elapsedHours >= 0 && elapsedHours < hours,
    cooldownHours: hours,
    latestCommentAt: latest,
    elapsedHours,
  };
}

async function createIssueWithLabelFallback({ request, target, report }) {
  const payload = {
    title: report.title,
    body: report.body,
  };
  if (report.labels.length > 0) {
    payload.labels = report.labels;
  }
  try {
    return await request({
      method: "POST",
      path: `/repos/${target.owner}/${target.repo}/issues`,
      body: payload,
    });
  } catch (error) {
    if (error?.status === 422 && payload.labels) {
      return await request({
        method: "POST",
        path: `/repos/${target.owner}/${target.repo}/issues`,
        body: { title: payload.title, body: payload.body },
      });
    }
    throw error;
  }
}

function optionalLine(title, value) {
  return value ? `${title}\n\n${value}` : "";
}

function githubRunUrl(env, repository, runId) {
  if (!repository || !runId) {
    return "";
  }
  const server = env.GITHUB_SERVER_URL || "https://github.com";
  return `${server}/${repository}/actions/runs/${runId}`;
}

function parseJsonResponse(text) {
  try {
    return JSON.parse(text);
  } catch {
    return { message: text };
  }
}

function shouldRetryStatus(status) {
  return status === 429 || status === 500 || status === 502 || status === 503 || status === 504;
}

function retryAfterHeaderMs(value) {
  const seconds = Number(value || "");
  return Number.isFinite(seconds) && seconds > 0 ? seconds * 1000 : undefined;
}

async function sleep(ms) {
  await new Promise((resolve) => setTimeout(resolve, ms));
}

import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";

import kfdPackageJson from "@kungfu-tech/kfd/package.json" with { type: "json" };
import kfdStandards from "@kungfu-tech/kfd/standards.json" with { type: "json" };
import kfdTrustTaxonomySchema from "@kungfu-tech/kfd/schemas/kfd-2/trust-taxonomy.schema.json" with { type: "json" };

export const KFD1_RELEASE_GATE_CONTRACT = "kungfu-buildchain-kfd-1-release-gate";
export const KFD1_WITNESS_SET_CONTRACT = "kungfu-buildchain-kfd-1-witness-set";
export const KFD3_RELEASE_GATE_CONTRACT = "kungfu-buildchain-kfd-3-collaboration-interface-release-gate";
export const KFD3_PREBUILD_WITNESS_CONTRACT = "kungfu-buildchain-kfd-3-collaboration-interface-prebuild-witness";
export const KFD3_ARTIFACT_WITNESS_CONTRACT = "kungfu-buildchain-kfd-3-collaboration-interface-artifact-witness";
export const BUILDCHAIN_JSON_FORMATTING_POLICY = Object.freeze({
  name: "buildchain-release-evidence-json-v1",
  indentation: 2,
  trailingNewline: true,
  canonicalDigest: "stable-json-sha256-v1",
});

function optionalString(value) {
  return value === undefined || value === null ? "" : String(value);
}

function nonEmptyString(value, label) {
  const normalized = optionalString(value).trim();
  if (!normalized) {
    throw new Error(`${label} must be a non-empty string`);
  }
  return normalized;
}

function stableJson(value) {
  if (Array.isArray(value)) {
    return `[${value.map(stableJson).join(",")}]`;
  }
  if (value && typeof value === "object") {
    return `{${Object.keys(value)
      .sort()
      .map((key) => `${JSON.stringify(key)}:${stableJson(value[key])}`)
      .join(",")}}`;
  }
  return JSON.stringify(value);
}

function sha256Bytes(value) {
  return crypto.createHash("sha256").update(value).digest("hex");
}

export function sha256Json(value) {
  return sha256Bytes(stableJson(value));
}

export function sha256File(filePath) {
  return crypto.createHash("sha256").update(fs.readFileSync(filePath)).digest("hex");
}

const bundledKfdJsonExports = new Map([
  ["@kungfu-tech/kfd/package.json", kfdPackageJson],
  ["@kungfu-tech/kfd/standards.json", kfdStandards],
  ["@kungfu-tech/kfd/schemas/kfd-2/trust-taxonomy.schema.json", kfdTrustTaxonomySchema],
]);

function cloneJson(value) {
  return JSON.parse(JSON.stringify(value));
}

function readJsonPackageExport(exportPath) {
  if (!bundledKfdJsonExports.has(exportPath)) {
    throw new Error(`KFD metadata package export is not bundled into Buildchain release gates: ${exportPath}`);
  }
  return cloneJson(bundledKfdJsonExports.get(exportPath));
}

function tryReadJsonPackageExport(exportPath) {
  try {
    return readJsonPackageExport(exportPath);
  } catch {
    return undefined;
  }
}

function loadKfdPackageMetadata() {
  const packageJson = readJsonPackageExport("@kungfu-tech/kfd/package.json");
  const standards = readJsonPackageExport("@kungfu-tech/kfd/standards.json");
  return { packageJson, standards };
}

export function resolveKfd1Metadata() {
  const { packageJson, standards } = loadKfdPackageMetadata();
  const entries = Object.entries(standards.standards || {});
  const entry = entries.find(([key, value]) => {
    const names = [key, value?.key, value?.id, value?.label]
      .filter(Boolean)
      .map((name) => String(name).toLowerCase());
    return (
      names.includes("kfd-1") &&
      value?.schemaIds?.contractWorld &&
      value?.schemaIds?.witness &&
      value?.schemaPaths?.contractWorld &&
      value?.schemaPaths?.witness
    );
  });
  if (!entry) {
    throw new Error("KFD metadata package does not expose the KFD-1 contract-world witness standard");
  }
  const [key, standard] = entry;
  return {
    key: standard.key || key,
    id: standard.id || standard.label || key,
    label: standard.label || standard.id || key,
    title: standard.title || "",
    status: standard.status || "",
    revision: standard.revision || 0,
    package: {
      name: packageJson.name,
      version: packageJson.version,
      repository: packageJson.repository?.url || "",
    },
    schemaIds: { ...standard.schemaIds },
    schemaPaths: { ...standard.schemaPaths },
    concepts: { ...(standard.concepts || {}) },
    metadataSchema: standards.metadataSchema || {},
    source: standards.source || {},
  };
}

export function resolveKfd3Metadata({ requireSchemas = false } = {}) {
  const { packageJson, standards } = loadKfdPackageMetadata();
  const entries = Object.entries(standards.standards || {});
  const entry = entries.find(([key, value]) => {
    const names = [key, value?.key, value?.id, value?.label]
      .filter(Boolean)
      .map((name) => String(name).toLowerCase());
    return names.includes("kfd-3");
  });
  if (!entry) {
    throw new Error("KFD metadata package does not expose KFD-3 metadata");
  }
  const [key, standard] = entry;
  const schemaIds = { ...(standard.schemaIds || {}) };
  const schemaPaths = { ...(standard.schemaPaths || {}) };
  const hasCollaborationSchemas = Boolean(
    schemaIds.collaborationInterface &&
    schemaIds.witness &&
    schemaPaths.collaborationInterface &&
    schemaPaths.witness,
  );
  if (requireSchemas && !hasCollaborationSchemas) {
    throw new Error("KFD metadata package does not expose the KFD-3 collaboration-interface witness standard");
  }
  return {
    key: standard.key || key,
    id: standard.id || standard.label || key,
    label: standard.label || standard.id || key,
    title: standard.title || "",
    status: standard.status || "",
    revision: standard.revision || 0,
    package: {
      name: packageJson.name,
      version: packageJson.version,
      repository: packageJson.repository?.url || "",
    },
    schemaIds,
    schemaPaths,
    hasCollaborationSchemas,
    concepts: { ...(standard.concepts || {}) },
    metadataSchema: standards.metadataSchema || {},
    source: standards.source || {},
  };
}

export function resolveKfd2Metadata({ requireTrustTaxonomy = false } = {}) {
  const { packageJson, standards } = loadKfdPackageMetadata();
  const entries = Object.entries(standards.standards || {});
  const entry = entries.find(([key, value]) => {
    const names = [key, value?.key, value?.id, value?.label]
      .filter(Boolean)
      .map((name) => String(name).toLowerCase());
    return names.includes("kfd-2");
  });
  if (!entry) {
    throw new Error("KFD metadata package does not expose KFD-2 metadata");
  }
  const [key, standard] = entry;
  const schemaIds = { ...(standard.schemaIds || {}) };
  const schemaPaths = { ...(standard.schemaPaths || {}) };
  const trustTaxonomyPath = schemaPaths.trustTaxonomy || "";
  const trustTaxonomy = trustTaxonomyPath
    ? tryReadJsonPackageExport(`@kungfu-tech/kfd/${trustTaxonomyPath}`)
    : undefined;
  if (requireTrustTaxonomy && (!schemaIds.trustTaxonomy || !trustTaxonomyPath || !trustTaxonomy)) {
    throw new Error("KFD metadata package does not expose the KFD-2 trust taxonomy schema");
  }
  return {
    key: standard.key || key,
    id: standard.id || standard.label || key,
    label: standard.label || standard.id || key,
    title: standard.title || "",
    status: standard.status || "",
    revision: standard.revision || 0,
    package: {
      name: packageJson.name,
      version: packageJson.version,
      repository: packageJson.repository?.url || "",
    },
    schemaIds,
    schemaPaths,
    hasTrustTaxonomySchema: Boolean(schemaIds.trustTaxonomy && trustTaxonomyPath && trustTaxonomy),
    trustTaxonomy,
    concepts: { ...(standard.concepts || {}) },
    metadataSchema: standards.metadataSchema || {},
    source: standards.source || {},
  };
}

function normalizeHash(value, label, { required = false } = {}) {
  const text = optionalString(value).replace(/^sha256:/, "").trim();
  if (!text && !required) {
    return "";
  }
  if (!/^[0-9a-f]{64}$/i.test(text)) {
    throw new Error(`${label} must be a sha256 hex digest`);
  }
  return text.toLowerCase();
}

function normalizePath(value, label) {
  const text = nonEmptyString(value, label).replace(/\\/g, "/");
  if (path.isAbsolute(text)) {
    throw new Error(`${label} must be repository-relative`);
  }
  if (text.split("/").some((part) => part === "..")) {
    throw new Error(`${label} must not contain ..`);
  }
  return text;
}

function normalizeEvidenceFile(value, label) {
  if (!value) {
    return undefined;
  }
  if (typeof value === "string") {
    return { path: normalizePath(value, `${label}.path`) };
  }
  if (typeof value !== "object" || Array.isArray(value)) {
    throw new Error(`${label} must be an object`);
  }
  return {
    ...value,
    path: value.path ? normalizePath(value.path, `${label}.path`) : "",
    sha256: value.sha256 ? normalizeHash(value.sha256, `${label}.sha256`) : "",
  };
}

function normalizeSurface(surface, index) {
  if (!surface || typeof surface !== "object" || Array.isArray(surface)) {
    throw new Error(`surfaces[${index}] must be an object`);
  }
  const artifactPath = normalizePath(surface.artifactPath || surface.artifact_path, `surfaces[${index}].artifactPath`);
  return {
    name: nonEmptyString(surface.name || surface.id, `surfaces[${index}].name`),
    sourcePath: surface.sourcePath || surface.source_path
      ? normalizePath(surface.sourcePath || surface.source_path, `surfaces[${index}].sourcePath`)
      : "",
    sourceSha256: normalizeHash(surface.sourceSha256 || surface.source_sha256, `surfaces[${index}].sourceSha256`),
    artifactPath,
    expectedSha256: normalizeHash(surface.expectedSha256 || surface.expected_sha256, `surfaces[${index}].expectedSha256`, { required: true }),
    byteForByte: surface.byteForByte === undefined && surface.byte_for_byte === undefined
      ? true
      : Boolean(surface.byteForByte ?? surface.byte_for_byte),
  };
}

function normalizeStringArray(value) {
  return Array.isArray(value) ? value.map((entry) => optionalString(entry)).filter(Boolean) : [];
}

const KFD3_SURFACE_GROUPS = [
  {
    kind: "documentation",
    keys: ["docs", "documents", "documentation"],
  },
  {
    kind: "schema",
    keys: ["schemas"],
  },
  {
    kind: "standards-metadata",
    keys: ["standardsMetadata", "standards_metadata", "standards", "metadata"],
  },
  {
    kind: "package-export",
    keys: ["packageExports", "package_exports", "exports"],
  },
  {
    kind: "site-consumption-contract",
    keys: ["siteConsumptionContracts", "site_consumption_contracts", "siteContracts", "site_contracts"],
  },
];

function groupedKfd3SurfacesFromSource(source = {}) {
  if (!source || typeof source !== "object" || Array.isArray(source)) {
    return [];
  }
  const surfaces = [];
  for (const group of KFD3_SURFACE_GROUPS) {
    const values = group.keys
      .map((key) => source[key])
      .find((entry) => Array.isArray(entry));
    if (!values) {
      continue;
    }
    values.forEach((entry, index) => {
      if (typeof entry === "string") {
        surfaces.push({
          id: entry,
          name: entry,
          kind: group.kind,
          availability: "shipped",
          visibility: "public",
          participantFacing: true,
          public: true,
        });
        return;
      }
      if (!entry || typeof entry !== "object" || Array.isArray(entry)) {
        throw new Error(`${group.keys[0]}[${index}] must be a string or object`);
      }
      surfaces.push({
        kind: group.kind,
        availability: "shipped",
        visibility: "public",
        participantFacing: true,
        public: true,
        ...entry,
      });
    });
  }
  return surfaces;
}

function groupedKfd1SurfacesFromSource(source = {}) {
  return groupedKfd3SurfacesFromSource(source).map((surface) => ({
    name: surface.name || surface.id,
    sourcePath: surface.sourcePath || surface.source_path || "",
    sourceSha256: surface.sourceSha256 || surface.source_sha256 || surface.sha256 || "",
    artifactPath: surface.artifactPath || surface.artifact_path || surface.path || surface.sourcePath || surface.source_path || "",
    expectedSha256: surface.expectedSha256 || surface.expected_sha256 || surface.artifactSha256 || surface.artifact_sha256 || surface.sha256 || "",
    byteForByte: surface.byteForByte ?? surface.byte_for_byte ?? true,
  }));
}

function normalizeKfd3Surface(surface, index, label) {
  if (!surface || typeof surface !== "object" || Array.isArray(surface)) {
    throw new Error(`${label}[${index}] must be an object`);
  }
  const visibility = optionalString(surface.visibility || (surface.public === false ? "internal" : "public")).toLowerCase();
  const availability = optionalString(surface.availability || surface.state || surface.maturity || (surface.shipped === false ? "not-shipped" : "shipped")).toLowerCase();
  const participantFacing = surface.participantFacing ?? surface.participant_facing ?? true;
  const publicSurface = surface.public ?? (visibility === "public");
  return {
    id: nonEmptyString(surface.id || surface.name || surface.command, `${label}[${index}].id`),
    name: optionalString(surface.name || surface.label || surface.id),
    kind: optionalString(surface.kind || surface.type || "control-surface"),
    participantProfile: optionalString(surface.participantProfile || surface.participant_profile || surface.profile),
    availability,
    visibility,
    participantFacing: Boolean(participantFacing),
    public: Boolean(publicSurface),
    sourcePath: surface.sourcePath || surface.source_path
      ? normalizePath(surface.sourcePath || surface.source_path, `${label}[${index}].sourcePath`)
      : "",
    evidencePath: surface.evidencePath || surface.evidence_path
      ? normalizePath(surface.evidencePath || surface.evidence_path, `${label}[${index}].evidencePath`)
      : "",
  };
}

function declaredSurfacesFromWitness(witness) {
  return [
    ...(Array.isArray(witness.declaredSurfaces) ? witness.declaredSurfaces : []),
    ...(Array.isArray(witness.declared_surfaces) ? witness.declared_surfaces : []),
    ...(Array.isArray(witness.surfaces) ? witness.surfaces : []),
    ...(Array.isArray(witness.collaborationInterface?.surfaces) ? witness.collaborationInterface.surfaces : []),
    ...(Array.isArray(witness.collaboration_interface?.surfaces) ? witness.collaboration_interface.surfaces : []),
    ...(Array.isArray(witness.collaborationInterfaceDocument?.surfaces) ? witness.collaborationInterfaceDocument.surfaces : []),
    ...(Array.isArray(witness.collaboration_interface_document?.surfaces) ? witness.collaboration_interface_document.surfaces : []),
    ...groupedKfd3SurfacesFromSource(witness),
    ...groupedKfd3SurfacesFromSource(witness.collaborationInterface),
    ...groupedKfd3SurfacesFromSource(witness.collaboration_interface),
    ...groupedKfd3SurfacesFromSource(witness.collaborationInterfaceDocument),
    ...groupedKfd3SurfacesFromSource(witness.collaboration_interface_document),
  ];
}

function artifactSurfacesFromWitness(witness) {
  const groupedSurfaces = [
    ...groupedKfd3SurfacesFromSource(witness),
    ...groupedKfd3SurfacesFromSource(witness.artifact),
    ...groupedKfd3SurfacesFromSource(witness.closure),
  ];
  const explicitSurfaces = [
    ...(Array.isArray(witness.exposedSurfaces) ? witness.exposedSurfaces : []),
    ...(Array.isArray(witness.exposed_surfaces) ? witness.exposed_surfaces : []),
    ...(Array.isArray(witness.artifactPublicSurfaces) ? witness.artifactPublicSurfaces : []),
    ...(Array.isArray(witness.artifact_public_surfaces) ? witness.artifact_public_surfaces : []),
    ...(Array.isArray(witness.surfaces) ? witness.surfaces : []),
  ];
  if (Array.isArray(witness.closure?.reachableEntrypoints)) {
    explicitSurfaces.push(...witness.closure.reachableEntrypoints.map((id) => ({
      id,
      kind: "entrypoint",
      availability: "shipped",
      visibility: "public",
      participantFacing: true,
      public: true,
    })));
  }
  return [...explicitSurfaces, ...groupedSurfaces];
}

function normalizeRegistry(value = {}) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return {};
  }
  return {
    id: optionalString(value.id || value.name),
    version: optionalString(value.version),
    path: value.path ? normalizePath(value.path, "registry.path") : "",
    sha256: value.sha256 ? normalizeHash(value.sha256, "registry.sha256") : "",
    digest: optionalString(value.digest || (value.sha256 ? `sha256:${normalizeHash(value.sha256, "registry.sha256")}` : "")),
  };
}

function normalizeArtifactIdentity(value = {}) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    return {};
  }
  return {
    name: optionalString(value.name || value.fileName || value.filename),
    path: value.path ? normalizePath(value.path, "artifact.path") : "",
    digest: optionalString(value.digest || (value.sha256 ? `sha256:${normalizeHash(value.sha256, "artifact.sha256")}` : "")),
  };
}

function normalizeStringObjectArray(value, label) {
  if (!Array.isArray(value)) {
    return [];
  }
  return value
    .map((entry, index) => {
      if (typeof entry === "string") {
        return { id: entry, note: "" };
      }
      if (!entry || typeof entry !== "object" || Array.isArray(entry)) {
        throw new Error(`${label}[${index}] must be a string or object`);
      }
      return {
        ...entry,
        id: optionalString(entry.id || entry.name || entry.surface || entry.path || entry.kind || `entry-${index}`),
        kind: optionalString(entry.kind || entry.type),
        reason: optionalString(entry.reason || entry.rationale || entry.note || entry.description),
        owner: optionalString(entry.owner),
      };
    })
    .filter((entry) => entry.id || entry.reason);
}

const KFD2_TAXONOMY_FIELDS = ["riskType", "trustImpact", "machineProvability", "agentAction"];

function kfdExtensionGuidance({ taxonomy = undefined, extensionRequests = [] } = {}) {
  const requestPath = taxonomy?.["x-kfd"]?.extensionPolicy?.requestPath || {};
  const kfd3Request = Array.isArray(extensionRequests)
    ? extensionRequests.find((entry) => entry?.requestPath?.kind === "github-issue")
    : undefined;
  return {
    action: taxonomy?.["x-kfd"]?.extensionPolicy?.standardAction || "open-kfd-extension-issue",
    repository: requestPath.repository || kfd3Request?.requestPath?.target || "https://github.com/kungfu-systems/kfd",
    issueUrl: requestPath.issueUrl || kfd3Request?.requestPath?.template || "https://github.com/kungfu-systems/kfd/issues/new?title=KFD-2%20trust%20taxonomy%20extension%20request",
    appliesTo: requestPath.appliesTo || KFD2_TAXONOMY_FIELDS,
  };
}

function taxonomyAllowedValues(taxonomy = {}) {
  const xKfd = taxonomy?.["x-kfd"]?.allowedValues || {};
  const defs = taxonomy?.$defs || {};
  return {
    riskType: new Set(xKfd.riskType || defs.riskType?.enum || []),
    trustImpact: new Set(xKfd.trustImpact || defs.trustImpact?.enum || []),
    machineProvability: new Set(xKfd.machineProvability || defs.machineProvability?.enum || []),
    agentAction: new Set(xKfd.agentAction || defs.agentAction?.enum || []),
  };
}

function validateTaxonomyField(entry, field, { allowed, label, guidance }) {
  const value = optionalString(entry[field]).trim();
  if (!value) {
    throw new Error(`${label}.${field} is required by KFD-2 trust taxonomy; do not invent a local private value, ${guidance.action} at ${guidance.issueUrl}`);
  }
  if (!allowed[field]?.has(value)) {
    throw new Error(`${label}.${field}=${value} is not in KFD-2 trust taxonomy; unknown taxonomy values fail validation, ${guidance.action} at ${guidance.issueUrl}`);
  }
}

export function validateKfd2TrustTaxonomyEntry(entry, {
  kind = "residualRisk",
  label = kind,
  metadata = resolveKfd2Metadata({ requireTrustTaxonomy: true }),
  extensionRequests = [],
} = {}) {
  const taxonomy = metadata.trustTaxonomy;
  const taxonomyContract = taxonomy?.contract || taxonomy?.["x-kfd"]?.contract;
  if (!taxonomy || taxonomyContract !== "kfd-2-trust-taxonomy") {
    const guidance = kfdExtensionGuidance({ taxonomy, extensionRequests });
    throw new Error(`${label} requires KFD-2 trust taxonomy from @kungfu-tech/kfd standards.json; ${guidance.action} at ${guidance.issueUrl}`);
  }
  if (!entry || typeof entry !== "object" || Array.isArray(entry)) {
    throw new Error(`${label} must be an object validated by KFD-2 trust taxonomy`);
  }
  const guidance = kfdExtensionGuidance({ taxonomy, extensionRequests });
  const defs = taxonomy.$defs || {};
  const required = defs[kind]?.required || (kind === "residualRisk"
    ? ["id", "definedBy", "riskType", "trustImpact", "machineProvability", "agentAction", "reason", "owner"]
    : ["id", "riskType", "trustImpact", "reason"]);
  for (const field of required) {
    if (!optionalString(entry[field]).trim()) {
      throw new Error(`${label}.${field} is required by KFD-2 trust taxonomy; do not add a private local taxonomy value, ${guidance.action} at ${guidance.issueUrl}`);
    }
  }
  const allowed = taxonomyAllowedValues(taxonomy);
  for (const field of KFD2_TAXONOMY_FIELDS) {
    if (field in entry || required.includes(field)) {
      validateTaxonomyField(entry, field, { allowed, label, guidance });
    }
  }
  if (kind === "residualRisk") {
    const expectedDefinedBy = `${metadata.schemaIds.trustTaxonomy}#/$defs/residualRisk`;
    if (entry.definedBy !== expectedDefinedBy) {
      throw new Error(`${label}.definedBy must be ${expectedDefinedBy}; ${guidance.action} at ${guidance.issueUrl}`);
    }
  }
  return {
    ...entry,
    taxonomy: {
      standard: metadata.key,
      schemaId: metadata.schemaIds.trustTaxonomy,
      schemaPath: metadata.schemaPaths.trustTaxonomy,
      contract: taxonomyContract,
      package: metadata.package,
    },
    extensionRequest: entry.extensionRequest || kfdExtensionGuidance({ taxonomy, extensionRequests }),
  };
}

function normalizeKfd2TaxonomyEntries(value, {
  kind = "residualRisk",
  label = kind,
  extensionRequests = [],
} = {}) {
  const entries = normalizeStringObjectArray(value, label);
  if (entries.length === 0) {
    return [];
  }
  const metadata = resolveKfd2Metadata({ requireTrustTaxonomy: true });
  return entries.map((entry, index) => validateKfd2TrustTaxonomyEntry(entry, {
    kind,
    label: `${label}[${index}]`,
    metadata,
    extensionRequests,
  }));
}

function normalizeKfd3AuditBoundary(value = {}, { closure = {}, label = "auditBoundary" } = {}) {
  const boundary = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  const sourceClosure = closure && typeof closure === "object" && !Array.isArray(closure) ? closure : {};
  const nonExhaustiveSource =
    boundary.nonExhaustivelyEnumerableSurfaces ||
    boundary.non_exhaustively_enumerable_surfaces ||
    boundary.nonExhaustiveSurfaces ||
    boundary.non_exhaustive_surfaces ||
    sourceClosure.nonExhaustivelyEnumerableSurfaces ||
    sourceClosure.non_exhaustively_enumerable_surfaces ||
    sourceClosure.nonExhaustiveSurfaces ||
    sourceClosure.non_exhaustive_surfaces ||
    [];
  return {
    mode: optionalString(boundary.mode || boundary.classificationMode || sourceClosure.classificationMode || "closed-world"),
    scope: optionalString(boundary.scope || "participant-facing public collaboration/control surfaces"),
    reachableSurfaceMode: optionalString(
      boundary.reachableSurfaceMode ||
      boundary.reachable_surface_mode ||
      sourceClosure.reachableSurfaceMode ||
      sourceClosure.reachable_surface_mode ||
      sourceClosure.classificationMode ||
      "declared-boundary",
    ),
    unclassifiedPolicy: optionalString(
      boundary.unclassifiedPolicy ||
      boundary.unclassified_policy ||
      sourceClosure.unclassifiedEntrypointsPolicy ||
      sourceClosure.unclassified_entrypoints_policy ||
      "fail",
    ),
    nonExhaustivelyEnumerableSurfaces: normalizeStringObjectArray(nonExhaustiveSource, `${label}.nonExhaustivelyEnumerableSurfaces`),
    explicitlyExemptedSurfaces: normalizeStringObjectArray(
      boundary.explicitlyExemptedSurfaces ||
      boundary.explicitly_exempted_surfaces ||
      boundary.exemptions ||
      sourceClosure.explicitlyExemptedSurfaces ||
      sourceClosure.exemptions ||
      [],
      `${label}.explicitlyExemptedSurfaces`,
    ),
  };
}

function normalizeKfd3ResidualRisk(value = [], { auditBoundary = {}, extensionRequests = [] } = {}) {
  const explicitRisks = normalizeStringObjectArray(value, "residualRisk");
  const boundaryRisks = (auditBoundary.nonExhaustivelyEnumerableSurfaces || []).map((entry) => ({
    ...entry,
    id: entry.id,
    kind: entry.kind || "non-exhaustive-surface",
    reason: entry.reason || "Surface cannot be exhaustively enumerated by the release passport.",
    owner: entry.owner || "",
  }));
  const byId = new Map();
  for (const entry of [...explicitRisks, ...boundaryRisks]) {
    byId.set(entry.id || entry.reason, entry);
  }
  return normalizeKfd2TaxonomyEntries([...byId.values()], {
    kind: "residualRisk",
    label: "residualRisk",
    extensionRequests,
  });
}

function normalizeKfd3Responsibility(value = {}, { registry = {}, artifactVerifyCommand = "" } = {}) {
  const source = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  return {
    registryFactsOwner: optionalString(
      source.registryFactsOwner ||
      source.registry_facts_owner ||
      source.productRegistryOwner ||
      source.product_registry_owner ||
      source.product ||
      registry.id ||
      "product",
    ),
    artifactVerificationOwner: optionalString(
      source.artifactVerificationOwner ||
      source.artifact_verification_owner ||
      source.verifierOwner ||
      source.verifier_owner ||
      (artifactVerifyCommand ? "product-owned verify command" : "product"),
    ),
    releasePassportProofOwner: optionalString(
      source.releasePassportProofOwner ||
      source.release_passport_proof_owner ||
      source.passportOwner ||
      source.passport_owner ||
      "buildchain",
    ),
  };
}

export function normalizeKfd3CollaborationInterfacePrebuildWitness(witness, { metadata = resolveKfd3Metadata() } = {}) {
  if (!witness || typeof witness !== "object" || Array.isArray(witness)) {
    throw new Error("KFD-3 pre-build witness must be a JSON object");
  }
  const standard = optionalString(witness.standard || metadata.key);
  if (standard && standard !== metadata.key && standard !== metadata.id && standard !== metadata.label) {
    throw new Error(`KFD-3 witness standard must match ${metadata.key}`);
  }
  const declaredSurfaces = declaredSurfacesFromWitness(witness).map((surface, index) => normalizeKfd3Surface(surface, index, "declaredSurfaces"));
  if (declaredSurfaces.length === 0) {
    throw new Error("KFD-3 pre-build witness must declare at least one collaboration/control surface");
  }
  const registry = normalizeRegistry(witness.registry || witness.sourceRegistry || witness.source_registry || witness.collaborationInterface?.sourceRegistry || witness.collaboration_interface?.sourceRegistry);
  const closure = witness.collaborationInterface?.closure || witness.collaboration_interface?.closure || {};
  const extensionRequests = normalizeStringObjectArray(
    witness.extensionRequests ||
      witness.extension_requests ||
      witness.collaborationInterface?.extensionRequests ||
      witness.collaboration_interface?.extensionRequests ||
      [],
    "extensionRequests",
  );
  const auditBoundary = normalizeKfd3AuditBoundary(witness.auditBoundary || witness.audit_boundary || closure, { closure });
  const expectedArtifactVerification = witness.expectedArtifactVerification && typeof witness.expectedArtifactVerification === "object" && !Array.isArray(witness.expectedArtifactVerification)
    ? { ...witness.expectedArtifactVerification, command: optionalString(witness.expectedArtifactVerification.command) }
    : { command: optionalString(witness.artifactVerifyCommand || witness.artifact_verify_command) };
  return {
    schemaVersion: 1,
    contract: KFD3_PREBUILD_WITNESS_CONTRACT,
    id: nonEmptyString(witness.id, "KFD-3 pre-build witness id"),
    standard: metadata.key,
    standardLabel: metadata.label,
    supportLevel: optionalString(witness.supportLevel || witness.support_level || witness.support?.level || "release"),
    source: witness.source && typeof witness.source === "object" && !Array.isArray(witness.source)
      ? { ...witness.source }
      : {},
    registry,
    participantProfiles: normalizeStringArray(
      witness.participantProfiles ||
      witness.participant_profiles ||
      witness.profiles ||
      witness.collaborationInterface?.participants?.map((entry) => entry.id || entry.name) ||
      witness.collaboration_interface?.participants?.map((entry) => entry.id || entry.name),
    ),
    expectedArtifactVerification,
    collaborationInterfaceDigest: optionalString(
      witness.collaborationInterfaceDigest ||
      witness.collaboration_interface_digest ||
      witness.collaborationInterface?.digest ||
      witness.collaboration_interface?.digest,
    ),
    auditBoundary,
    residualRisk: normalizeKfd3ResidualRisk(
      witness.residualRisk || witness.residual_risk || witness.auditBoundary?.residualRisk || witness.audit_boundary?.residual_risk || [],
      { auditBoundary, extensionRequests },
    ),
    extensionRequests,
    responsibility: normalizeKfd3Responsibility(witness.responsibility || witness.owners, {
      registry,
      artifactVerifyCommand: expectedArtifactVerification.command,
    }),
    declaredSurfaces,
    metadata: {
      kfdPackage: metadata.package,
      schemaIds: metadata.schemaIds,
      schemaPaths: metadata.schemaPaths,
      hasCollaborationSchemas: Boolean(metadata.hasCollaborationSchemas),
    },
  };
}

export function normalizeKfd3CollaborationInterfaceArtifactWitness(witness, { metadata = resolveKfd3Metadata() } = {}) {
  if (!witness || typeof witness !== "object" || Array.isArray(witness)) {
    throw new Error("KFD-3 artifact witness must be a JSON object");
  }
  const standard = optionalString(witness.standard || metadata.key);
  if (standard && standard !== metadata.key && standard !== metadata.id && standard !== metadata.label) {
    throw new Error(`KFD-3 artifact witness standard must match ${metadata.key}`);
  }
  const exposedSurfaces = artifactSurfacesFromWitness(witness).map((surface, index) => normalizeKfd3Surface(surface, index, "exposedSurfaces"));
  const extensionRequests = normalizeStringObjectArray(
    witness.extensionRequests || witness.extension_requests || [],
    "extensionRequests",
  );
  return {
    schemaVersion: 1,
    contract: KFD3_ARTIFACT_WITNESS_CONTRACT,
    id: nonEmptyString(witness.id, "KFD-3 artifact witness id"),
    standard: metadata.key,
    standardLabel: metadata.label,
    artifact: normalizeArtifactIdentity(witness.artifact),
    registry: normalizeRegistry(witness.registry || witness.sourceRegistry || witness.source_registry),
    collaborationInterfaceDigest: optionalString(
      witness.collaborationInterfaceDigest ||
      witness.collaboration_interface_digest ||
      witness.collaborationInterface?.digest ||
      witness.collaboration_interface?.digest,
    ),
    exposedSurfaces,
    residualRisk: normalizeKfd2TaxonomyEntries(witness.residualRisk || witness.residual_risk || [], {
      kind: "residualRisk",
      label: "artifactWitness.residualRisk",
      extensionRequests,
    }),
    extensionRequests,
    verifier: witness.verifier && typeof witness.verifier === "object" && !Array.isArray(witness.verifier)
      ? { ...witness.verifier }
      : {},
    metadata: {
      kfdPackage: metadata.package,
      schemaIds: metadata.schemaIds,
      schemaPaths: metadata.schemaPaths,
      hasCollaborationSchemas: Boolean(metadata.hasCollaborationSchemas),
    },
  };
}

function isParticipantPublic(surface) {
  return Boolean(surface.public && surface.participantFacing);
}

function isDeclaredShipped(surface) {
  return ["shipped", "stable", "available", "ga", "production"].includes(surface.availability);
}

function isDeclaredPublic(surface) {
  return isParticipantPublic(surface) && !["internal", "unsupported", "not-shipped", "not_shipped"].includes(surface.availability);
}

function idSet(surfaces) {
  return new Set(surfaces.map((surface) => surface.id));
}

function sortedSetDiff(left, right) {
  return [...left].filter((entry) => !right.has(entry)).sort();
}

function kfd3ReleaseStatus({ comparisonStatus, supportLevel, residualRisk = [] } = {}) {
  if (comparisonStatus === "passed") {
    return residualRisk.length > 0 ? "audited" : "enforced";
  }
  if (["draft", "partial", "missing", "unsupported"].includes(supportLevel)) {
    return "draft";
  }
  return "declared";
}

function kfd3TrustResult(comparisonStatus) {
  if (comparisonStatus === "passed") return "pass";
  if (comparisonStatus === "downgraded") return "downgraded";
  return "fail";
}

function kfd3TrustStatement({
  comparisonStatus,
  missingDeclaredShipped = [],
  unclassifiedArtifactPublic = [],
  residualRisk = [],
} = {}) {
  if (comparisonStatus === "passed") {
    return unclassifiedArtifactPublic.length === 0
      ? "No unclassified reachable surface within the declared audit boundary."
      : "Unclassified reachable surfaces remain within the declared audit boundary.";
  }
  if (missingDeclaredShipped.length > 0) {
    return "One or more declared shipped public surfaces are missing from the artifact evidence.";
  }
  if (unclassifiedArtifactPublic.length > 0) {
    return "The artifact exposes participant-facing public surfaces not declared by the pre-build witness.";
  }
  if (residualRisk.length > 0) {
    return "KFD-3 proof is downgraded and residual risks remain explicit.";
  }
  return "KFD-3 collaboration-interface proof did not pass.";
}

function evidenceDescriptor({ path = "", sha256 = "", canonicalSha256 = "" } = {}) {
  return {
    path: optionalString(path),
    sha256: optionalString(sha256),
    canonicalSha256: optionalString(canonicalSha256),
  };
}

function kfd1SurfacesFromWitness(witness = {}) {
  return [
    ...(Array.isArray(witness.surfaces) ? witness.surfaces : []),
    ...groupedKfd1SurfacesFromSource(witness),
    ...groupedKfd1SurfacesFromSource(witness.standardContract),
    ...groupedKfd1SurfacesFromSource(witness.standard_contract),
    ...groupedKfd1SurfacesFromSource(witness.selfContract),
    ...groupedKfd1SurfacesFromSource(witness.self_contract),
    ...groupedKfd1SurfacesFromSource(witness.contractWorld),
  ];
}

function normalizeKfd1SelfHostingBoundary(value = {}, { contractWorld = {} } = {}) {
  const source = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  return {
    mode: optionalString(source.mode || (source.enabled || contractWorld.selfHosted ? "self-hosted-standard-contract" : "external-contract-world")),
    sourceScope: optionalString(source.sourceScope || source.source_scope || "KFD source standard metadata, schemas, package exports, and site-consumption entrypoints"),
    artifactScope: optionalString(source.artifactScope || source.artifact_scope || "packaged public artifact surfaces"),
    boundary: optionalString(source.boundary || "source-to-artifact byte equality for declared standard-contract surfaces"),
    residualRisk: normalizeStringObjectArray(
      source.residualRisk || source.residual_risk || source.nonEnumerableResidualRisk || source.non_enumerable_residual_risk || [],
      "selfHostingBoundary.residualRisk",
    ),
  };
}

function normalizeKfd1Responsibility(value = {}, { contractWorld = {} } = {}) {
  const source = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  return {
    sourceContractOwner: optionalString(source.sourceContractOwner || source.source_contract_owner || source.standardOwner || source.standard_owner || contractWorld.owner || "product"),
    artifactVerificationOwner: optionalString(source.artifactVerificationOwner || source.artifact_verification_owner || "buildchain-release-passport"),
    releasePassportProofOwner: optionalString(source.releasePassportProofOwner || source.release_passport_proof_owner || "buildchain"),
  };
}

function normalizeKfd1StandardContract(value = {}, { metadata = resolveKfd1Metadata() } = {}) {
  const source = value && typeof value === "object" && !Array.isArray(value) ? value : {};
  return {
    id: optionalString(source.id || source.name),
    schemaId: optionalString(source.schemaId || source.schema_id || metadata.schemaIds.contractWorld),
    path: source.path ? normalizePath(source.path, "standardContract.path") : "",
    sha256: source.sha256 ? normalizeHash(source.sha256, "standardContract.sha256") : "",
    digest: optionalString(source.digest || (source.sha256 ? `sha256:${normalizeHash(source.sha256, "standardContract.sha256")}` : "")),
  };
}

export function normalizeKfd1ContractWorldWitness(witness, { metadata = resolveKfd1Metadata() } = {}) {
  if (!witness || typeof witness !== "object" || Array.isArray(witness)) {
    throw new Error("KFD-1 witness must be a JSON object");
  }
  const surfaces = kfd1SurfacesFromWitness(witness).map((surface, index) => normalizeSurface(surface, index));
  if (surfaces.length === 0) {
    throw new Error("KFD-1 witness surfaces[] must include at least one artifact surface");
  }
  const standard = optionalString(witness.standard || metadata.key);
  if (standard && standard !== metadata.key && standard !== metadata.id && standard !== metadata.label) {
    throw new Error(`KFD-1 witness standard must match ${metadata.key}`);
  }
  return {
    schemaVersion: 1,
    contract: KFD1_WITNESS_SET_CONTRACT,
    id: nonEmptyString(witness.id, "KFD-1 witness id"),
    standard: metadata.key,
    standardLabel: metadata.label,
    source: witness.source && typeof witness.source === "object" && !Array.isArray(witness.source)
      ? { ...witness.source }
      : {},
    contractWorld: witness.contractWorld && typeof witness.contractWorld === "object" && !Array.isArray(witness.contractWorld)
      ? {
          ...witness.contractWorld,
          schemaId: witness.contractWorld.schemaId || metadata.schemaIds.contractWorld,
          digest: optionalString(witness.contractWorld.digest || witness.contractWorld.sha256),
        }
      : {
          schemaId: metadata.schemaIds.contractWorld,
          digest: "",
        },
    standardContract: normalizeKfd1StandardContract(witness.standardContract || witness.standard_contract || witness.selfContract || witness.self_contract || witness.contractWorld, { metadata }),
    selfHostingBoundary: normalizeKfd1SelfHostingBoundary(witness.selfHostingBoundary || witness.self_hosting_boundary, {
      contractWorld: witness.contractWorld,
    }),
    responsibility: normalizeKfd1Responsibility(witness.responsibility || witness.owners, {
      contractWorld: witness.contractWorld,
    }),
    sourceVerificationRequired: Boolean(witness.standardContract || witness.standard_contract || witness.selfContract || witness.self_contract || witness.selfHostingBoundary || witness.self_hosting_boundary),
    canonicalPolicy: normalizeEvidenceFile(witness.canonicalPolicy || witness.canonical_policy, "canonicalPolicy"),
    registry: normalizeEvidenceFile(witness.registry, "registry"),
    surfaces,
    metadata: {
      kfdPackage: metadata.package,
      schemaIds: metadata.schemaIds,
      schemaPaths: metadata.schemaPaths,
    },
  };
}

function resolveArtifactFile({ cwd, artifactRoot, artifacts = [], artifactPath }) {
  const candidates = [
    path.resolve(cwd, artifactPath),
    artifactRoot ? path.resolve(artifactRoot, artifactPath) : "",
  ].filter(Boolean);
  for (const artifact of artifacts) {
    const sourcePath = artifact.sourcePath || artifact.path || "";
    if (!sourcePath) {
      continue;
    }
    const normalizedSource = sourcePath.replace(/\\/g, "/");
    if (normalizedSource === artifactPath || normalizedSource.endsWith(`/${artifactPath}`)) {
      candidates.push(path.resolve(sourcePath));
    }
    const name = artifact.name || artifact.filename || "";
    if (name && name === artifactPath) {
      candidates.push(path.resolve(sourcePath));
    }
  }
  return candidates.find((candidate) => candidate && fs.existsSync(candidate) && fs.statSync(candidate).isFile()) || "";
}

function resolveSourceFile({ cwd, sourcePath }) {
  if (!sourcePath) {
    return "";
  }
  const candidate = path.resolve(cwd, sourcePath);
  return fs.existsSync(candidate) && fs.statSync(candidate).isFile() ? candidate : "";
}

export function createKfd1ReleaseGateEvidence({
  cwd = process.cwd(),
  artifactRoot = "",
  artifacts = [],
  witnesses = [],
  verifiedAt = new Date().toISOString(),
  metadata = resolveKfd1Metadata(),
} = {}) {
  const normalizedWitnesses = witnesses.map((witness) => normalizeKfd1ContractWorldWitness(witness, { metadata }));
  if (normalizedWitnesses.length === 0) {
    return undefined;
  }
  const worlds = normalizedWitnesses.map((witness) => {
    const preBuildWitnessSha256 = sha256Json(witness);
    const sourceResults = witness.surfaces.map((surface) => {
      if (!surface.sourcePath || !surface.sourceSha256) {
        return {
          name: surface.name,
          sourcePath: surface.sourcePath,
          expectedSha256: surface.sourceSha256,
          actualSha256: "",
          status: witness.sourceVerificationRequired ? "failed" : "not-declared",
          reason: witness.sourceVerificationRequired ? "source-digest-not-declared" : "",
        };
      }
      const filePath = resolveSourceFile({ cwd, sourcePath: surface.sourcePath });
      if (!filePath) {
        return {
          name: surface.name,
          sourcePath: surface.sourcePath,
          expectedSha256: surface.sourceSha256,
          actualSha256: "",
          status: witness.sourceVerificationRequired ? "failed" : "unavailable",
          reason: "source-missing",
        };
      }
      const actualSha256 = sha256File(filePath);
      const passed = actualSha256 === surface.sourceSha256;
      return {
        name: surface.name,
        sourcePath: surface.sourcePath,
        expectedSha256: surface.sourceSha256,
        actualSha256,
        status: passed ? "passed" : "failed",
        reason: passed ? "" : "source-digest-mismatch",
      };
    });
    const surfaceResults = witness.surfaces.map((surface) => {
      const filePath = resolveArtifactFile({
        cwd,
        artifactRoot,
        artifacts,
        artifactPath: surface.artifactPath,
      });
      if (!filePath) {
        return {
          name: surface.name,
          sourcePath: surface.sourcePath,
          sourceSha256: surface.sourceSha256,
          artifactPath: surface.artifactPath,
          expectedSha256: surface.expectedSha256,
          actualSha256: "",
          byteForByte: surface.byteForByte,
          status: "failed",
          reason: "artifact-missing",
        };
      }
      const actualSha256 = sha256File(filePath);
      const passed = actualSha256 === surface.expectedSha256;
      return {
        name: surface.name,
        sourcePath: surface.sourcePath,
        sourceSha256: surface.sourceSha256,
        artifactPath: surface.artifactPath,
        expectedSha256: surface.expectedSha256,
        actualSha256,
        byteForByte: surface.byteForByte,
        status: passed ? "passed" : "failed",
        reason: passed ? "" : "digest-mismatch",
      };
    });
    const status = surfaceResults.every((surface) => surface.status === "passed") ? "passed" : "failed";
    const sourceStatus = sourceResults.every((surface) => ["passed", "not-declared", "unavailable"].includes(surface.status)) &&
      (!witness.sourceVerificationRequired || sourceResults.every((surface) => surface.status === "passed"))
      ? "passed"
      : "failed";
    const worldStatus = status === "passed" && sourceStatus === "passed" ? "passed" : "failed";
    return {
      id: witness.id,
      standard: metadata.label,
      standardKey: metadata.key,
      result: worldStatus,
      preBuildWitnessSha256,
      sourceHashes: {
        sha256: sha256Json(sourceResults),
        surfaceCount: sourceResults.length,
      },
      artifactHashes: {
        sha256: sha256Json(surfaceResults),
        surfaceCount: surfaceResults.length,
      },
      witness,
      standardContract: witness.standardContract,
      selfHostingBoundary: witness.selfHostingBoundary,
      responsibility: witness.responsibility,
      sourceVerification: {
        status: sourceStatus,
        verifiedAt,
        required: Boolean(witness.sourceVerificationRequired),
        surfaces: sourceResults,
      },
      artifactVerification: {
        status,
        verifiedAt,
        surfaces: surfaceResults,
      },
    };
  });
  const status = worlds.every((world) => world.result === "passed") ? "passed" : "failed";
  return {
    key: metadata.key,
    passportSection: {
      schemaVersion: 1,
      contract: KFD1_RELEASE_GATE_CONTRACT,
      status,
      selfContractVerification: {
        result: status === "passed" ? "pass" : "fail",
        contractWorldCount: worlds.length,
        selfHosted: worlds.some((world) => world.sourceVerification.required),
        responsibility: {
          proofOwner: "buildchain-release-passport",
        },
      },
      metadata: {
        standard: {
          key: metadata.key,
          id: metadata.id,
          label: metadata.label,
          title: metadata.title,
          revision: metadata.revision,
          status: metadata.status,
        },
        schemas: {
          ids: metadata.schemaIds,
          paths: metadata.schemaPaths,
          metadata: metadata.metadataSchema,
        },
        package: metadata.package,
      },
      formatting: BUILDCHAIN_JSON_FORMATTING_POLICY,
      contractWorlds: worlds,
    },
  };
}

export function createKfd3CollaborationInterfaceReleaseGateEvidence({
  prebuildWitnesses = [],
  artifactWitnesses = [],
  prebuildWitnessMetas = [],
  artifactWitnessMetas = [],
  artifactCommandMeta = undefined,
  verifiedAt = new Date().toISOString(),
  metadata = resolveKfd3Metadata(),
} = {}) {
  const normalizedPrebuildWitnesses = (prebuildWitnesses || [])
    .filter(Boolean)
    .map((witness) => normalizeKfd3CollaborationInterfacePrebuildWitness(witness, { metadata }));
  if (normalizedPrebuildWitnesses.length === 0) {
    return undefined;
  }
  const normalizedArtifactWitnesses = (artifactWitnesses || [])
    .filter(Boolean)
    .map((witness) => normalizeKfd3CollaborationInterfaceArtifactWitness(witness, { metadata }));
  const artifactById = new Map(normalizedArtifactWitnesses.map((witness) => [witness.id, witness]));
  const singleArtifactWitness = normalizedArtifactWitnesses.length === 1 ? normalizedArtifactWitnesses[0] : undefined;
  const prebuildMetaById = new Map((prebuildWitnessMetas || [])
    .filter((meta) => meta?.value?.id)
    .map((meta) => [meta.value.id, meta]));
  const artifactMetaById = new Map((artifactWitnessMetas || [])
    .filter((meta) => meta?.value?.id)
    .map((meta) => [meta.value.id, meta]));
  const singleArtifactMeta = (artifactWitnessMetas || []).filter((meta) => meta?.value).length === 1
    ? (artifactWitnessMetas || []).find((meta) => meta?.value)
    : undefined;
  const worlds = normalizedPrebuildWitnesses.map((prebuildWitness) => {
    const artifactWitness = artifactById.get(prebuildWitness.id) || singleArtifactWitness;
    const prebuildMeta = prebuildMetaById.get(prebuildWitness.id) || {};
    const artifactMeta = artifactWitness ? (artifactMetaById.get(artifactWitness.id) || singleArtifactMeta || artifactCommandMeta || {}) : {};
    const preBuildWitnessSha256 = sha256Json(prebuildWitness);
    const artifactWitnessSha256 = artifactWitness ? sha256Json(artifactWitness) : "";
    const declaredPublic = prebuildWitness.declaredSurfaces.filter(isDeclaredPublic);
    const declaredShippedPublic = declaredPublic.filter(isDeclaredShipped);
    const artifactPublic = artifactWitness
      ? artifactWitness.exposedSurfaces.filter(isParticipantPublic)
      : [];
    const declaredPublicIds = idSet(declaredPublic);
    const declaredShippedIds = idSet(declaredShippedPublic);
    const artifactPublicIds = idSet(artifactPublic);
    const missingDeclaredShipped = sortedSetDiff(declaredShippedIds, artifactPublicIds);
    const unclassifiedArtifactPublic = sortedSetDiff(artifactPublicIds, declaredPublicIds);
    const reasons = [];
    if (!metadata.hasCollaborationSchemas) {
      reasons.push("kfd-metadata-schema-missing");
    }
    if (!artifactWitness) {
      reasons.push("artifact-witness-missing");
    }
    if (
      prebuildWitness.collaborationInterfaceDigest &&
      artifactWitness?.collaborationInterfaceDigest &&
      prebuildWitness.collaborationInterfaceDigest !== artifactWitness.collaborationInterfaceDigest
    ) {
      reasons.push("collaboration-interface-digest-mismatch");
    }
    if (missingDeclaredShipped.length > 0) {
      reasons.push("declared-shipped-surface-missing");
    }
    if (unclassifiedArtifactPublic.length > 0) {
      reasons.push("artifact-public-surface-not-declared");
    }
    const supportLevel = prebuildWitness.supportLevel || "release";
    if (["draft", "partial", "missing", "unsupported"].includes(supportLevel)) {
      reasons.push(`support-level-${supportLevel}`);
    }
    const status = reasons.length === 0 ? "passed" : supportLevel === "release" ? "failed" : "downgraded";
    const residualRiskMap = new Map();
    for (const risk of [...(prebuildWitness.residualRisk || []), ...(artifactWitness?.residualRisk || [])]) {
      residualRiskMap.set(risk.id || risk.reason, risk);
    }
    const residualRisk = [...residualRiskMap.values()];
    const releaseStatus = kfd3ReleaseStatus({ comparisonStatus: status, supportLevel, residualRisk });
    const trustResult = kfd3TrustResult(status);
    const declaredCapabilityVerification = {
      status,
      result: missingDeclaredShipped.length === 0 ? "passed" : "failed",
      declaredCapabilityCount: declaredPublic.length,
      declaredShippedPublicSurfaceCount: declaredShippedPublic.length,
      implementedPublicSurfaceCount: artifactPublic.length,
      missingDeclaredShipped,
    };
    const reverseAudit = {
      status: unclassifiedArtifactPublic.length === 0 ? "passed" : "failed",
      auditBoundary: prebuildWitness.auditBoundary,
      reachablePublicSurfaceCount: artifactPublic.length,
      unclassifiedReachableSurfaces: unclassifiedArtifactPublic,
      explicitlyExemptedSurfaces: prebuildWitness.auditBoundary.explicitlyExemptedSurfaces,
      nonExhaustivelyEnumerableSurfaces: prebuildWitness.auditBoundary.nonExhaustivelyEnumerableSurfaces,
      statement: unclassifiedArtifactPublic.length === 0
        ? "No unclassified reachable surface within the declared audit boundary."
        : "Unclassified reachable surfaces were found within the declared audit boundary.",
    };
    const witnessEvidence = {
      prebuild: evidenceDescriptor({
        path: prebuildMeta.path,
        sha256: prebuildMeta.sha256,
        canonicalSha256: preBuildWitnessSha256,
      }),
      artifact: evidenceDescriptor({
        path: artifactMeta.path,
        sha256: artifactMeta.sha256,
        canonicalSha256: artifactWitnessSha256,
      }),
      artifactVerifyCommandSha256: optionalString(artifactCommandMeta?.sha256),
    };
    return {
      id: prebuildWitness.id,
      standard: metadata.label,
      standardKey: metadata.key,
      preBuildWitnessSha256,
      artifactWitnessSha256,
      prebuildWitness,
      artifactWitness: artifactWitness || undefined,
      declaredSurfaces: prebuildWitness.declaredSurfaces,
      exposedSurfaces: artifactPublic,
      factSource: {
        role: "product-owned",
        registry: prebuildWitness.registry,
        collaborationInterfaceDigest: prebuildWitness.collaborationInterfaceDigest,
      },
      witnessEvidence,
      auditBoundary: prebuildWitness.auditBoundary,
      residualRisk,
      responsibility: prebuildWitness.responsibility,
      releaseStatus,
      trustProof: {
        contract: "kungfu-buildchain-kfd-3-passport-trust-proof",
        result: trustResult,
        releaseStatus,
        statement: kfd3TrustStatement({
          comparisonStatus: status,
          missingDeclaredShipped,
          unclassifiedArtifactPublic,
          residualRisk,
        }),
        factSourceRole: "product-owned-registry-and-witnesses",
        proofOwner: "buildchain-release-passport",
        declaredCapabilityVerification,
        reverseAudit,
        residualRisk,
        responsibility: prebuildWitness.responsibility,
      },
      declaredCapabilityVerification,
      reverseAudit,
      comparison: {
        status,
        verifiedAt,
        supportLevel,
        declaredPublicSurfaceCount: declaredPublic.length,
        declaredShippedPublicSurfaceCount: declaredShippedPublic.length,
        artifactPublicSurfaceCount: artifactPublic.length,
        missingDeclaredShipped,
        unclassifiedArtifactPublic,
        reasons,
      },
    };
  });
  const status = worlds.every((world) => world.comparison.status === "passed") ? "passed" : "failed";
  const releaseStatuses = [...new Set(worlds.map((world) => world.releaseStatus))];
  const trustResult = status === "passed" ? "pass" : worlds.some((world) => world.trustProof.result === "downgraded") ? "downgraded" : "fail";
  return {
    key: metadata.key,
    passportSection: {
      schemaVersion: 1,
      contract: KFD3_RELEASE_GATE_CONTRACT,
      status,
      releaseStatus: releaseStatuses.length === 1 ? releaseStatuses[0] : status === "passed" ? "audited" : "declared",
      trustProof: {
        contract: "kungfu-buildchain-kfd-3-passport-trust-proof",
        result: trustResult,
        statement: status === "passed"
          ? "No unclassified reachable surface within the declared audit boundary."
          : "One or more KFD-3 collaboration-interface witness pairs failed or downgraded.",
        factSourceRole: "product-owned-registry-and-witnesses",
        proofOwner: "buildchain-release-passport",
        collaborationInterfaceCount: worlds.length,
        audited: worlds.every((world) => world.trustProof.result === "pass"),
      },
      metadata: {
        standard: {
          key: metadata.key,
          id: metadata.id,
          label: metadata.label,
          title: metadata.title,
          revision: metadata.revision,
          status: metadata.status,
        },
        schemas: {
          ids: metadata.schemaIds,
          paths: metadata.schemaPaths,
          metadata: metadata.metadataSchema,
          hasCollaborationSchemas: Boolean(metadata.hasCollaborationSchemas),
        },
        package: metadata.package,
      },
      formatting: BUILDCHAIN_JSON_FORMATTING_POLICY,
      collaborationInterfaces: worlds,
    },
  };
}

export function validateKfd1ReleaseGateEvidence(section, { metadata = resolveKfd1Metadata() } = {}) {
  const issues = [];
  if (!section) {
    return issues;
  }
  if (typeof section !== "object" || Array.isArray(section)) {
    issues.push({
      level: "error",
      code: `${metadata.key}.object`,
      message: `${metadata.key} release gate evidence must be an object`,
      details: {},
    });
    return issues;
  }
  if (section.contract !== KFD1_RELEASE_GATE_CONTRACT) {
    issues.push({
      level: "error",
      code: `${metadata.key}.contract`,
      message: `${metadata.key}.contract must be ${KFD1_RELEASE_GATE_CONTRACT}`,
      details: {},
    });
  }
  if (section.metadata?.standard?.key !== metadata.key) {
    issues.push({
      level: "error",
      code: `${metadata.key}.metadata.standard.key`,
      message: `${metadata.key} metadata key must come from the KFD metadata package`,
      details: { expected: metadata.key, actual: section.metadata?.standard?.key || "" },
    });
  }
  const worlds = Array.isArray(section.contractWorlds) ? section.contractWorlds : [];
  if (worlds.length === 0) {
    issues.push({
      level: "error",
      code: `${metadata.key}.contractWorlds.empty`,
      message: `${metadata.key}.contractWorlds must include at least one witness`,
      details: {},
    });
  }
  for (const [worldIndex, world] of worlds.entries()) {
    if (!world.preBuildWitnessSha256) {
      issues.push({
        level: "error",
        code: `${metadata.key}.contractWorlds[${worldIndex}].preBuildWitnessSha256`,
        message: "KFD-1 contract world must record the frozen pre-build witness digest",
        details: {},
      });
    }
    if (world.standardKey !== metadata.key) {
      issues.push({
        level: "error",
        code: `${metadata.key}.contractWorlds[${worldIndex}].standardKey`,
        message: "KFD-1 contract world standardKey must match KFD metadata",
        details: { expected: metadata.key, actual: world.standardKey || "" },
      });
    }
    if (!world.sourceHashes?.sha256 || !world.artifactHashes?.sha256) {
      issues.push({
        level: "error",
        code: `${metadata.key}.contractWorlds[${worldIndex}].hashes`,
        message: "KFD-1 self contract evidence must record source and artifact hash summaries",
        details: { id: world.id || "" },
      });
    }
    if (!world.selfHostingBoundary || typeof world.selfHostingBoundary !== "object" || Array.isArray(world.selfHostingBoundary)) {
      issues.push({
        level: "error",
        code: `${metadata.key}.contractWorlds[${worldIndex}].selfHostingBoundary`,
        message: "KFD-1 contract world must record the self-hosting boundary",
        details: { id: world.id || "" },
      });
    }
    if (!world.responsibility?.sourceContractOwner || !world.responsibility?.artifactVerificationOwner || !world.responsibility?.releasePassportProofOwner) {
      issues.push({
        level: "error",
        code: `${metadata.key}.contractWorlds[${worldIndex}].responsibility`,
        message: "KFD-1 contract world must record source, artifact verification, and passport proof owners",
        details: { id: world.id || "" },
      });
    }
    if (world.sourceVerification?.required && world.sourceVerification?.status !== "passed") {
      issues.push({
        level: "error",
        code: `${metadata.key}.contractWorlds[${worldIndex}].sourceVerification`,
        message: "KFD-1 self contract source verification must pass before release passport finalization",
        details: { id: world.id || "", status: world.sourceVerification?.status || "" },
      });
    }
    if (world.artifactVerification?.status !== "passed") {
      issues.push({
        level: "error",
        code: `${metadata.key}.contractWorlds[${worldIndex}].artifactVerification`,
        message: "KFD-1 artifact verification must pass before release passport finalization",
        details: { id: world.id || "", status: world.artifactVerification?.status || "" },
      });
    }
    const surfaces = Array.isArray(world.artifactVerification?.surfaces) ? world.artifactVerification.surfaces : [];
    if (surfaces.length === 0) {
      issues.push({
        level: "error",
        code: `${metadata.key}.contractWorlds[${worldIndex}].surfaces.empty`,
        message: "KFD-1 artifact verification must list checked surfaces",
        details: { id: world.id || "" },
      });
    }
    for (const [surfaceIndex, surface] of surfaces.entries()) {
      if (surface.status !== "passed" || !surface.expectedSha256 || !surface.actualSha256 || surface.expectedSha256 !== surface.actualSha256) {
        issues.push({
          level: "error",
          code: `${metadata.key}.contractWorlds[${worldIndex}].surfaces[${surfaceIndex}]`,
          message: "KFD-1 verified surface digest mismatch",
          details: {
            id: world.id || "",
            name: surface.name || "",
            artifactPath: surface.artifactPath || "",
            status: surface.status || "",
            reason: surface.reason || "",
          },
        });
      }
    }
  }
  if (section.status !== "passed") {
    issues.push({
      level: "error",
      code: `${metadata.key}.status`,
      message: "KFD-1 release gate status must be passed",
      details: { status: section.status || "" },
    });
  }
  return issues;
}

export function validateKfd3CollaborationInterfaceReleaseGateEvidence(section, { metadata = resolveKfd3Metadata() } = {}) {
  const issues = [];
  if (!section) {
    return issues;
  }
  if (typeof section !== "object" || Array.isArray(section)) {
    issues.push({
      level: "error",
      code: `${metadata.key}.object`,
      message: `${metadata.key} collaboration-interface evidence must be an object`,
      details: {},
    });
    return issues;
  }
  if (section.contract !== KFD3_RELEASE_GATE_CONTRACT) {
    issues.push({
      level: "error",
      code: `${metadata.key}.contract`,
      message: `${metadata.key}.contract must be ${KFD3_RELEASE_GATE_CONTRACT}`,
      details: {},
    });
  }
  if (section.metadata?.standard?.key !== metadata.key) {
    issues.push({
      level: "error",
      code: `${metadata.key}.metadata.standard.key`,
      message: `${metadata.key} metadata key must come from the KFD metadata package`,
      details: { expected: metadata.key, actual: section.metadata?.standard?.key || "" },
    });
  }
  if (!section.metadata?.schemas?.hasCollaborationSchemas) {
    issues.push({
      level: "error",
      code: `${metadata.key}.metadata.schemas.collaborationInterface`,
      message: "KFD-3 release evidence requires KFD package metadata for collaboration-interface and witness schemas",
      details: { package: metadata.package, schemaIds: section.metadata?.schemas?.ids || {} },
    });
  }
  const interfaces = Array.isArray(section.collaborationInterfaces) ? section.collaborationInterfaces : [];
  if (interfaces.length === 0) {
    issues.push({
      level: "error",
      code: `${metadata.key}.collaborationInterfaces.empty`,
      message: `${metadata.key}.collaborationInterfaces must include at least one witness pair`,
      details: {},
    });
  }
  if (!section.trustProof || typeof section.trustProof !== "object" || Array.isArray(section.trustProof)) {
    issues.push({
      level: "error",
      code: `${metadata.key}.trustProof`,
      message: "KFD-3 release evidence must include a release-passport trust proof summary",
      details: {},
    });
  } else {
    const allowedStatuses = new Set(["not-applicable", "declared", "draft", "audited", "enforced"]);
    if (!allowedStatuses.has(section.releaseStatus)) {
      issues.push({
        level: "error",
        code: `${metadata.key}.releaseStatus`,
        message: "KFD-3 release status must be not-applicable, declared, draft, audited, or enforced",
        details: { status: section.releaseStatus || "" },
      });
    }
    if (!["pass", "fail", "downgraded"].includes(section.trustProof.result)) {
      issues.push({
        level: "error",
        code: `${metadata.key}.trustProof.result`,
        message: "KFD-3 trust proof result must be pass, fail, or downgraded",
        details: { result: section.trustProof.result || "" },
      });
    }
  }
  for (const [index, entry] of interfaces.entries()) {
    if (!entry.preBuildWitnessSha256) {
      issues.push({
        level: "error",
        code: `${metadata.key}.collaborationInterfaces[${index}].preBuildWitnessSha256`,
        message: "KFD-3 collaboration-interface evidence must record the frozen pre-build witness digest",
        details: {},
      });
    }
    if (!entry.artifactWitnessSha256) {
      issues.push({
        level: "error",
        code: `${metadata.key}.collaborationInterfaces[${index}].artifactWitnessSha256`,
        message: "KFD-3 collaboration-interface evidence must record the artifact-side witness digest",
        details: { id: entry.id || "" },
      });
    }
    if (entry.standardKey !== metadata.key) {
      issues.push({
        level: "error",
        code: `${metadata.key}.collaborationInterfaces[${index}].standardKey`,
        message: "KFD-3 collaboration-interface standardKey must match KFD metadata",
        details: { expected: metadata.key, actual: entry.standardKey || "" },
      });
    }
    const comparison = entry.comparison || {};
    if (comparison.status !== "passed") {
      issues.push({
        level: "error",
        code: `${metadata.key}.collaborationInterfaces[${index}].comparison`,
        message: "KFD-3 collaboration-interface artifact closure verification must pass before release passport finalization",
        details: {
          id: entry.id || "",
          status: comparison.status || "",
          reasons: comparison.reasons || [],
        },
      });
    }
    if (Array.isArray(comparison.missingDeclaredShipped) && comparison.missingDeclaredShipped.length > 0) {
      issues.push({
        level: "error",
        code: `${metadata.key}.collaborationInterfaces[${index}].missingDeclaredShipped`,
        message: "KFD-3 artifact is missing declared shipped public surfaces",
        details: { id: entry.id || "", surfaces: comparison.missingDeclaredShipped },
      });
    }
    if (Array.isArray(comparison.unclassifiedArtifactPublic) && comparison.unclassifiedArtifactPublic.length > 0) {
      issues.push({
        level: "error",
        code: `${metadata.key}.collaborationInterfaces[${index}].unclassifiedArtifactPublic`,
        message: "KFD-3 artifact exposes public participant-facing surfaces not declared by the pre-build witness",
        details: { id: entry.id || "", surfaces: comparison.unclassifiedArtifactPublic },
      });
    }
    if (!entry.trustProof || typeof entry.trustProof !== "object" || Array.isArray(entry.trustProof)) {
      issues.push({
        level: "error",
        code: `${metadata.key}.collaborationInterfaces[${index}].trustProof`,
        message: "KFD-3 collaboration-interface evidence must include a trust proof",
        details: { id: entry.id || "" },
      });
    } else {
      if (entry.trustProof.result === "pass" && comparison.status !== "passed") {
        issues.push({
          level: "error",
          code: `${metadata.key}.collaborationInterfaces[${index}].trustProof.result`,
          message: "KFD-3 trust proof cannot pass when closure comparison did not pass",
          details: { id: entry.id || "", result: entry.trustProof.result, comparisonStatus: comparison.status || "" },
        });
      }
      if (!entry.trustProof.declaredCapabilityVerification) {
        issues.push({
          level: "error",
          code: `${metadata.key}.collaborationInterfaces[${index}].trustProof.declaredCapabilityVerification`,
          message: "KFD-3 trust proof must record declared capability verification",
          details: { id: entry.id || "" },
        });
      }
      if (!entry.trustProof.reverseAudit) {
        issues.push({
          level: "error",
          code: `${metadata.key}.collaborationInterfaces[${index}].trustProof.reverseAudit`,
          message: "KFD-3 trust proof must record reverse audit results",
          details: { id: entry.id || "" },
        });
      }
    }
    if (!entry.witnessEvidence?.prebuild?.canonicalSha256 || !entry.witnessEvidence?.artifact?.canonicalSha256) {
      issues.push({
        level: "error",
        code: `${metadata.key}.collaborationInterfaces[${index}].witnessEvidence`,
        message: "KFD-3 trust proof must record pre-build and artifact witness hashes",
        details: { id: entry.id || "" },
      });
    }
    if (!entry.auditBoundary || typeof entry.auditBoundary !== "object" || Array.isArray(entry.auditBoundary)) {
      issues.push({
        level: "error",
        code: `${metadata.key}.collaborationInterfaces[${index}].auditBoundary`,
        message: "KFD-3 trust proof must record the reverse audit boundary",
        details: { id: entry.id || "" },
      });
    }
    if (!Array.isArray(entry.residualRisk)) {
      issues.push({
        level: "error",
        code: `${metadata.key}.collaborationInterfaces[${index}].residualRisk`,
        message: "KFD-3 trust proof must record residual risk as an array, even when empty",
        details: { id: entry.id || "" },
      });
    }
    if (!entry.responsibility?.registryFactsOwner || !entry.responsibility?.artifactVerificationOwner || !entry.responsibility?.releasePassportProofOwner) {
      issues.push({
        level: "error",
        code: `${metadata.key}.collaborationInterfaces[${index}].responsibility`,
        message: "KFD-3 trust proof must record registry, artifact verification, and passport proof owners",
        details: { id: entry.id || "" },
      });
    }
  }
  if (section.status !== "passed") {
    issues.push({
      level: "error",
      code: `${metadata.key}.status`,
      message: "KFD-3 collaboration-interface release gate status must be passed",
      details: { status: section.status || "" },
    });
  }
  return issues;
}

