export function collectKfdStatus({ cwd = process.cwd() } = {}) {
  const resolvedCwd = path.resolve(cwd);
  const schemas = listKfdSchemas();
  const layout = planBuildchainLayoutMigration({ cwd: resolvedCwd });
  const paths = {
    config: resolveBuildchainConfigPath(resolvedCwd),
    contractLock: resolveBuildchainContractLockPath(resolvedCwd),
    kfd2ProductClaimsRegistry: resolveKfd2ProductClaimsRegistryPath(resolvedCwd),
    kfd3SurfaceRegistry: resolveKfd3SurfaceRegistryPath(resolvedCwd),
    releasePassport: resolveReleasePassportPath(resolvedCwd),
  };
  const pathStatus = Object.fromEntries(Object.entries(paths).map(([key, relPath]) => [
    key,
    {
      path: relPath,
      exists: fs.existsSync(path.join(resolvedCwd, relPath)),
    },
  ]));
  return {
    schemaVersion: 1,
    contract: "kungfu-buildchain-kfd-status",
    cwd: resolvedCwd,
    layout: {
      status: layout.status,
      canonicalRoot: layout.canonicalRoot,
      migrationNeeded: layout.moves.length > 0,
      moves: layout.moves,
    },
    standards: schemas.schemas.reduce((acc, entry) => {
      acc[entry.standard] ||= [];
      acc[entry.standard].push({
        name: entry.name,
        schemaId: entry.schemaId,
        schemaPath: entry.schemaPath,
      });
      return acc;
    }, {}),
    support: {
      "kfd-1": ["schema", "witness", "gate", "verify"],
      "kfd-2": ["schema", "taxonomy", "claims", "product-claims", "trust-claims", "trust-assessment", "upstream"],
      "kfd-3": ["schema", "detect", "register", "audit", "witness", "query", "aggregate"],
      "kfd-4": ["schema"],
    },
    paths: pathStatus,
  };
}

export const layout = Object.freeze({
  plan: planBuildchainLayoutMigration,
  migrate: migrateBuildchainLayout,
  resolveConfigPath: resolveBuildchainConfigPath,
  resolveContractLockPath: resolveBuildchainContractLockPath,
  resolveKfd2ProductClaimsRegistryPath,
  resolveKfd3SurfaceRegistryPath,
  resolveReleasePassportPath,
});

import crypto from "node:crypto";
import { execFileSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";

import {
  BUILDCHAIN_KFD2_CLAIMS_DIR,
  BUILDCHAIN_KFD2_CLAIM_ARGS_PATH,
  BUILDCHAIN_KFD2_DIR,
  BUILDCHAIN_KFD2_REGISTRY_PATH,
  BUILDCHAIN_KFD2_RELEASE_CLAIMS_PATH,
  toPosixPath,
} from "./buildchain-layout.js";
import {
  discoverConfiguredVersionStateFiles,
  loadBuildchainConfig,
} from "./buildchain-config.js";

export const KFD2_PRODUCT_CLAIMS_REGISTRY_CONTRACT =
  "kungfu-buildchain-kfd-2-product-claims-registry/v1";
export const KFD2_PRODUCT_CLAIMS_VALIDATION_CONTRACT =
  "kungfu-buildchain-kfd-2-product-claims-registry-validation";
export const KFD2_PRODUCT_CLAIMS_OUTPUT_CONTRACT =
  "kungfu-buildchain-kfd-2-product-claims-output";

const CLAIM_ID_RE = /^[a-z0-9]+(-[a-z0-9]+)*$/;
const CLAIM_STATUSES = new Set([
  "declared",
  "audited",
  "enforced",
  "not-applicable",
]);
const ENUMERABILITY = new Set([
  "closed-world",
  "declared-open",
  "sampled",
  "manual",
]);

function issue(code, message, pathValue = "") {
  return {
    level: "error",
    code,
    message,
    ...(pathValue ? { path: pathValue } : {}),
  };
}

function renderJson(value) {
  return `${JSON.stringify(value, null, 2)}\n`;
}

function sha256Buffer(value) {
  return crypto.createHash("sha256").update(value).digest("hex");
}

function sha256File(filePath) {
  return sha256Buffer(fs.readFileSync(filePath));
}

function readJsonFile(filePath) {
  return JSON.parse(fs.readFileSync(filePath, "utf8"));
}

function resolveRepoPath(cwd, relativePath, label = "path") {
  if (!relativePath || typeof relativePath !== "string") {
    throw new Error(`${label} must be a repository-relative path`);
  }
  const root = path.resolve(cwd);
  const resolved = path.resolve(root, relativePath);
  if (resolved !== root && !resolved.startsWith(`${root}${path.sep}`)) {
    throw new Error(`${label} escapes repository root: ${relativePath}`);
  }
  return resolved;
}

function repoRelative(cwd, filePath) {
  return toPosixPath(path.relative(path.resolve(cwd), path.resolve(filePath)));
}

function gitHead(cwd) {
  try {
    return execFileSync("git", ["rev-parse", "HEAD"], {
      cwd,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    }).trim();
  } catch {
    return "";
  }
}

function dottedValue(value, key) {
  return String(key || "")
    .split(".")
    .filter(Boolean)
    .reduce((current, part) => current?.[part], value);
}

function configuredVersion(cwd) {
  const loaded = loadBuildchainConfig(cwd);
  const files = discoverConfiguredVersionStateFiles(cwd, loaded);
  const versions = files.map((file) => {
    if (file.type === "json" || file.type === "toml") {
      return dottedValue(file.content, file.key);
    }
    return file.source.match(file.pattern)?.groups?.version || "";
  }).filter(Boolean);
  if (new Set(versions).size > 1) {
    throw new Error(`configured version files disagree: ${versions.join(", ")}`);
  }
  if (versions.length > 0) return versions[0];
  for (const candidate of ["package.json", "lerna.json"]) {
    const candidatePath = path.join(cwd, candidate);
    if (!fs.existsSync(candidatePath)) continue;
    const value = readJsonFile(candidatePath).version;
    if (typeof value === "string" && value) return value;
  }
  return "";
}

function pointerFor(cwd, input, label) {
  const filePath = resolveRepoPath(cwd, input?.path, label);
  if (!fs.existsSync(filePath) || !fs.statSync(filePath).isFile()) {
    throw new Error(`${label} does not name a readable file: ${input?.path || ""}`);
  }
  return {
    kind: input.kind || "file",
    path: repoRelative(cwd, filePath),
    sha256: sha256File(filePath),
    ...(input.schemaId ? { schemaId: input.schemaId } : {}),
    ...(input.digest ? { digest: input.digest } : {}),
    ...(input.specifier ? { specifier: input.specifier } : {}),
  };
}

export function readKfd2ProductClaimsRegistry({
  cwd = process.cwd(),
  registryPath = BUILDCHAIN_KFD2_REGISTRY_PATH,
} = {}) {
  const resolvedPath = resolveRepoPath(cwd, registryPath, "registryPath");
  if (!fs.existsSync(resolvedPath)) {
    throw new Error(`KFD-2 product claims registry not found: ${registryPath}`);
  }
  return {
    path: repoRelative(cwd, resolvedPath),
    sha256: sha256File(resolvedPath),
    registry: readJsonFile(resolvedPath),
  };
}

export function validateKfd2ProductClaimsRegistry(registry = {}) {
  const issues = [];
  if (registry?.schema !== KFD2_PRODUCT_CLAIMS_REGISTRY_CONTRACT) {
    issues.push(issue(
      "kfd-2.product-registry.schema",
      `registry.schema must be ${KFD2_PRODUCT_CLAIMS_REGISTRY_CONTRACT}`,
      "schema",
    ));
  }
  if (registry?.kfd?.standard !== "kfd-2") {
    issues.push(issue("kfd-2.product-registry.standard", "registry.kfd.standard must be kfd-2", "kfd.standard"));
  }
  if (registry?.kfd?.contract !== "kfd-2-release-claims") {
    issues.push(issue(
      "kfd-2.product-registry.contract",
      "registry.kfd.contract must be kfd-2-release-claims",
      "kfd.contract",
    ));
  }
  if (!registry?.product?.name) {
    issues.push(issue("kfd-2.product-registry.product", "registry.product.name is required", "product.name"));
  }
  const claims = Array.isArray(registry?.claims) ? registry.claims : [];
  if (claims.length === 0) {
    issues.push(issue("kfd-2.product-registry.claims", "registry.claims must be a non-empty array", "claims"));
  }
  const ids = new Set();
  for (const [index, claim] of claims.entries()) {
    const label = `claims[${index}]`;
    if (!CLAIM_ID_RE.test(String(claim?.id || ""))) {
      issues.push(issue("kfd-2.product-registry.claim-id", `${label}.id must match ${CLAIM_ID_RE}`, `${label}.id`));
    } else if (ids.has(claim.id)) {
      issues.push(issue("kfd-2.product-registry.duplicate-claim", `${label}.id duplicates ${claim.id}`, `${label}.id`));
    }
    ids.add(claim?.id);
    if (!claim?.statement) issues.push(issue("kfd-2.product-registry.statement", `${label}.statement is required`, `${label}.statement`));
    if (!claim?.source?.path) issues.push(issue("kfd-2.product-registry.source", `${label}.source.path is required`, `${label}.source.path`));
    if (!Array.isArray(claim?.evidence) || claim.evidence.length === 0) {
      issues.push(issue("kfd-2.product-registry.evidence", `${label}.evidence must be non-empty`, `${label}.evidence`));
    }
    if (!Array.isArray(claim?.artifacts) || claim.artifacts.length === 0) {
      issues.push(issue("kfd-2.product-registry.artifacts", `${label}.artifacts must be non-empty`, `${label}.artifacts`));
    }
    if (!claim?.auditBoundary?.scope) {
      issues.push(issue("kfd-2.product-registry.audit-boundary", `${label}.auditBoundary.scope is required`, `${label}.auditBoundary.scope`));
    }
    if (!ENUMERABILITY.has(String(claim?.auditBoundary?.enumerability || ""))) {
      issues.push(issue("kfd-2.product-registry.enumerability", `${label}.auditBoundary.enumerability is invalid`, `${label}.auditBoundary.enumerability`));
    }
    if (!Array.isArray(claim?.residualRisk)) {
      issues.push(issue("kfd-2.product-registry.residual-risk", `${label}.residualRisk must be an array`, `${label}.residualRisk`));
    }
    for (const key of ["sourceOwner", "verificationOwner", "releaseDecisionOwner"]) {
      if (!claim?.responsibility?.[key]) {
        issues.push(issue("kfd-2.product-registry.responsibility", `${label}.responsibility.${key} is required`, `${label}.responsibility.${key}`));
      }
    }
    if (!CLAIM_STATUSES.has(String(claim?.status || ""))) {
      issues.push(issue("kfd-2.product-registry.status", `${label}.status is invalid`, `${label}.status`));
    }
  }
  return {
    schemaVersion: 1,
    contract: KFD2_PRODUCT_CLAIMS_VALIDATION_CONTRACT,
    ok: issues.length === 0,
    claimCount: claims.length,
    issues,
  };
}

function assertValidRegistry(registry) {
  const validation = validateKfd2ProductClaimsRegistry(registry);
  if (!validation.ok) {
    throw new Error(`KFD-2 product claims registry is invalid:\n${validation.issues.map((entry) => `- ${entry.path || entry.code}: ${entry.message}`).join("\n")}`);
  }
  return validation;
}

function canonicalClaim(cwd, claim, defaultCheckCommand) {
  const source = pointerFor(cwd, claim.source, `${claim.id}.source`);
  return {
    id: claim.id,
    statement: claim.statement,
    category: claim.category || "kfd-2",
    source,
    evidence: claim.evidence.map((entry, index) => ({
      type: entry.type || "file",
      pointer: pointerFor(cwd, { ...entry, kind: entry.kind || "file" }, `${claim.id}.evidence[${index}]`),
      description: entry.description || "",
    })),
    verification: {
      command: claim.verification?.command || defaultCheckCommand,
      expectedResult: claim.verification?.expectedResult || "pass",
    },
    auditBoundary: {
      scope: claim.auditBoundary.scope,
      enumerability: claim.auditBoundary.enumerability,
      exclusions: claim.auditBoundary.exclusions || [],
    },
    residualRisk: claim.residualRisk,
    responsibility: claim.responsibility,
    status: claim.status,
  };
}

function passportClaim(cwd, claim, registrySha256, defaultCheckCommand) {
  const source = pointerFor(cwd, claim.source, `${claim.id}.source`);
  const machineEvidence = claim.evidence.map((entry, index) => ({
    type: entry.type || "file",
    pointer: pointerFor(cwd, { ...entry, kind: entry.kind || "file" }, `${claim.id}.evidence[${index}]`),
    description: entry.description || "",
  }));
  const artifacts = claim.artifacts.map((artifact, index) => {
    const pointer = pointerFor(cwd, { kind: "file", path: artifact.path }, `${claim.id}.artifacts[${index}]`);
    return {
      name: artifact.name || path.basename(artifact.path),
      path: pointer.path,
      sha256: pointer.sha256,
      expectedPackagePath: artifact.expectedPackagePath || "",
    };
  });
  return {
    id: claim.id,
    public: true,
    claim: claim.statement,
    sourceBindings: [{
      role: "claim-source",
      kind: source.kind,
      path: source.path,
      sha256: source.sha256,
    }],
    machineEvidence,
    hashes: {
      registrySha256,
      sourceSha256: source.sha256,
      evidenceSha256: machineEvidence.map((entry) => ({
        path: entry.pointer.path,
        sha256: entry.pointer.sha256,
      })),
      artifactSha256: artifacts.map((entry) => ({ path: entry.path, sha256: entry.sha256 })),
    },
    artifacts,
    verification: {
      result: claim.residualRisk.length === 0 ? "passed" : "passed-with-residual-risk",
      command: claim.verification?.command || defaultCheckCommand,
      expectedResult: claim.verification?.expectedResult || "pass",
    },
    auditBoundary: {
      scope: claim.auditBoundary.scope,
      enumerability: claim.auditBoundary.enumerability,
      exclusions: claim.auditBoundary.exclusions || [],
    },
    responsibility: claim.responsibility,
    residualRisk: claim.residualRisk,
    canonicalStatus: claim.status,
  };
}

function outputPaths(cwd, outputDir, claimIds) {
  const resolvedOutputDir = resolveRepoPath(cwd, outputDir, "outputDir");
  return {
    outputDir: resolvedOutputDir,
    releaseClaims: path.join(resolvedOutputDir, path.basename(BUILDCHAIN_KFD2_RELEASE_CLAIMS_PATH)),
    claimArgs: path.join(resolvedOutputDir, path.basename(BUILDCHAIN_KFD2_CLAIM_ARGS_PATH)),
    claimsDir: path.join(resolvedOutputDir, path.basename(BUILDCHAIN_KFD2_CLAIMS_DIR)),
    claims: claimIds.map((id) => path.join(resolvedOutputDir, path.basename(BUILDCHAIN_KFD2_CLAIMS_DIR), `${id}.json`)),
  };
}

export function renderKfd2ProductClaimOutputs({
  cwd = process.cwd(),
  registryPath = BUILDCHAIN_KFD2_REGISTRY_PATH,
  outputDir = BUILDCHAIN_KFD2_DIR,
  version = "",
  channel = "",
  tag = "",
  sourceSha = "",
} = {}) {
  const source = readKfd2ProductClaimsRegistry({ cwd, registryPath });
  const validation = assertValidRegistry(source.registry);
  const releaseVersion = version || source.registry.releaseDefaults?.version || configuredVersion(cwd);
  if (!releaseVersion) throw new Error("KFD-2 product claims require a release version");
  const defaultCheckCommand = source.registry.buildchain?.checkCommand || "buildchain kfd 2 product-claims check";
  const releaseClaims = {
    schemaVersion: 1,
    contract: source.registry.kfd.contract,
    standard: source.registry.kfd.standard,
    product: source.registry.product,
    release: {
      version: releaseVersion,
      channel: channel || source.registry.releaseDefaults?.channel || "local",
      tag: tag || `${source.registry.releaseDefaults?.tagPrefix || "v"}${releaseVersion}`,
      sourceSha: sourceSha || source.registry.releaseDefaults?.sourceSha || gitHead(cwd) || "unknown",
    },
    claims: source.registry.claims.map((claim) => canonicalClaim(cwd, claim, defaultCheckCommand)),
    schemaEvolution: {
      interfaceVersion: source.registry.kfd.interfaceVersion || 1,
      compatibilityRule: "Compatible additions may keep schemaVersion 1; required-field or semantic changes require a new KFD-owned interface version.",
    },
  };
  const claims = source.registry.claims.map((claim) => passportClaim(
    cwd,
    claim,
    source.sha256,
    defaultCheckCommand,
  ));
  const paths = outputPaths(cwd, outputDir, claims.map((claim) => claim.id));
  const claimArgs = `${paths.claims.map((claimPath) => `--kfd-2-claim-json ${repoRelative(cwd, claimPath)}`).join("\n")}\n`;
  const files = [
    { path: repoRelative(cwd, paths.releaseClaims), content: renderJson(releaseClaims) },
    ...claims.map((claim, index) => ({ path: repoRelative(cwd, paths.claims[index]), content: renderJson(claim) })),
    { path: repoRelative(cwd, paths.claimArgs), content: claimArgs },
  ];
  return {
    schemaVersion: 1,
    contract: KFD2_PRODUCT_CLAIMS_OUTPUT_CONTRACT,
    ok: true,
    registry: {
      path: source.path,
      sha256: source.sha256,
      contract: source.registry.schema,
    },
    validation,
    releaseClaims,
    claims,
    outputDir: repoRelative(cwd, paths.outputDir),
    files,
    summary: {
      claimCount: claims.length,
      releaseClaimsSha256: sha256Buffer(Buffer.from(renderJson(releaseClaims))),
      passportClaimStatuses: claims.map((claim) => ({
        id: claim.id,
        status: claim.residualRisk.length === 0 ? "passed" : "downgraded",
        residualRisk: claim.residualRisk.length,
      })),
    },
  };
}

function compareOutputs(cwd, rendered) {
  const issues = [];
  const expectedPaths = new Set(rendered.files.map((entry) => entry.path));
  for (const entry of rendered.files) {
    const filePath = resolveRepoPath(cwd, entry.path, "output path");
    if (!fs.existsSync(filePath)) {
      issues.push(issue("kfd-2.product-output.missing", `missing generated output: ${entry.path}`, entry.path));
    } else if (fs.readFileSync(filePath, "utf8") !== entry.content) {
      issues.push(issue("kfd-2.product-output.drift", `generated output is stale: ${entry.path}`, entry.path));
    }
  }
  const claimsDir = resolveRepoPath(cwd, path.join(rendered.outputDir, "claims"), "claims directory");
  if (fs.existsSync(claimsDir)) {
    for (const entry of fs.readdirSync(claimsDir, { withFileTypes: true })) {
      if (!entry.isFile() || !entry.name.endsWith(".json")) continue;
      const relativePath = repoRelative(cwd, path.join(claimsDir, entry.name));
      if (!expectedPaths.has(relativePath)) {
        issues.push(issue("kfd-2.product-output.unexpected", `unexpected generated claim: ${relativePath}`, relativePath));
      }
    }
  }
  return issues;
}

export function checkKfd2ProductClaimOutputs(options = {}) {
  const rendered = renderKfd2ProductClaimOutputs(options);
  const issues = compareOutputs(path.resolve(options.cwd || process.cwd()), rendered);
  return {
    ...rendered,
    ok: issues.length === 0,
    status: issues.length === 0 ? "current" : "mismatched",
    issues,
  };
}

export function writeKfd2ProductClaimOutputs(options = {}) {
  const cwd = path.resolve(options.cwd || process.cwd());
  const rendered = renderKfd2ProductClaimOutputs({ ...options, cwd });
  for (const entry of rendered.files) {
    const filePath = resolveRepoPath(cwd, entry.path, "output path");
    fs.mkdirSync(path.dirname(filePath), { recursive: true });
    fs.writeFileSync(filePath, entry.content);
  }
  const expectedPaths = new Set(rendered.files.map((entry) => entry.path));
  const claimsDir = resolveRepoPath(cwd, path.join(rendered.outputDir, "claims"), "claims directory");
  const removed = [];
  if (fs.existsSync(claimsDir)) {
    for (const entry of fs.readdirSync(claimsDir, { withFileTypes: true })) {
      if (!entry.isFile() || !entry.name.endsWith(".json")) continue;
      const filePath = path.join(claimsDir, entry.name);
      const relativePath = repoRelative(cwd, filePath);
      if (!expectedPaths.has(relativePath)) {
        fs.unlinkSync(filePath);
        removed.push(relativePath);
      }
    }
  }
  return {
    ...rendered,
    status: "written",
    written: rendered.files.map((entry) => entry.path),
    removed,
  };
}

import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { resolveKfd3SurfaceRegistryPath } from "./buildchain-layout.js";

export const KFD3_SURFACE_REGISTRY_CONTRACT = "kungfu-buildchain-kfd-3-surface-registry";
export const KFD3_SURFACE_DETECTION_CONTRACT = "kungfu-buildchain-kfd-3-surface-detection";
export const KFD3_SURFACE_AUDIT_CONTRACT = "kungfu-buildchain-kfd-3-surface-audit";
export const KFD3_CAPABILITY_QUERY_CONTRACT = "kungfu-buildchain-kfd-3-capability-query";
export const KFD3_DEFAULT_REGISTRY_PATH = ".buildchain/kfd/kfd-3/surfaces.json";

const KIND_ALIASES = Object.freeze({
  "node-api": "node-api",
  node: "node-api",
  npm: "node-api",
  "python-api": "python-api",
  python: "python-api",
  wheel: "python-api",
  cli: "cli",
  command: "cli",
  binary: "binary",
  "standalone-binary": "binary",
  docs: "documentation",
  documentation: "documentation",
  site: "site-bundle",
  "site-bundle": "site-bundle",
});

function readText(filePath, fallback = "") {
  return fs.existsSync(filePath) ? fs.readFileSync(filePath, "utf8") : fallback;
}

function readJsonFile(filePath, fallback = {}) {
  if (!fs.existsSync(filePath)) return fallback;
  return JSON.parse(fs.readFileSync(filePath, "utf8"));
}

function writeJsonFile(filePath, value) {
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  fs.writeFileSync(filePath, `${JSON.stringify(value, null, 2)}\n`);
}

function sha256Text(value) {
  return crypto.createHash("sha256").update(String(value || "")).digest("hex");
}

function sha256Json(value) {
  return sha256Text(JSON.stringify(value));
}

function sha256File(filePath) {
  return fs.existsSync(filePath) && fs.statSync(filePath).isFile()
    ? crypto.createHash("sha256").update(fs.readFileSync(filePath)).digest("hex")
    : "";
}

function normalizeKind(kind) {
  const normalized = KIND_ALIASES[String(kind || "").trim().toLowerCase()];
  if (!normalized) {
    throw new Error(`unsupported KFD-3 surface kind: ${kind}`);
  }
  return normalized;
}

function normalizeKinds(kinds = []) {
  const selected = kinds.length ? kinds : ["node-api", "python-api", "cli", "binary", "documentation", "site-bundle"];
  return [...new Set(selected.map(normalizeKind))].sort();
}

export function normalizeKfd3DistributionDeclaration(distribution, { surfaceId = "surface" } = {}) {
  if (!distribution || typeof distribution !== "object" || Array.isArray(distribution)) {
    throw new Error(`KFD-3 surface ${surfaceId} distribution must be an object`);
  }
  const registrar = String(distribution.registrar || "").trim();
  if (!registrar) {
    throw new Error(`KFD-3 surface ${surfaceId} distribution.registrar is required`);
  }
  const tasks = Array.isArray(distribution.tasks)
    ? [...new Set(distribution.tasks.map((entry) => String(entry || "").trim()).filter(Boolean))]
    : [];
  if (tasks.length === 0) {
    throw new Error(`KFD-3 surface ${surfaceId} distribution.tasks must contain at least one task`);
  }
  const sourceArtifacts = Array.isArray(distribution.artifacts) ? distribution.artifacts : [];
  if (sourceArtifacts.length === 0) {
    throw new Error(`KFD-3 surface ${surfaceId} distribution.artifacts must contain at least one artifact`);
  }
  const artifacts = sourceArtifacts.map((artifact, index) => {
    if (!artifact || typeof artifact !== "object" || Array.isArray(artifact)) {
      throw new Error(`KFD-3 surface ${surfaceId} distribution.artifacts[${index}] must be an object`);
    }
    const normalized = {
      ...artifact,
      kind: String(artifact.kind || "").trim(),
      platform: String(artifact.platform || "").trim(),
      pathGlob: String(artifact.pathGlob || "").trim(),
    };
    for (const field of ["kind", "platform", "pathGlob"]) {
      if (!normalized[field]) {
        throw new Error(`KFD-3 surface ${surfaceId} distribution.artifacts[${index}].${field} is required`);
      }
    }
    if (artifact.sha256 !== undefined) {
      normalized.sha256 = String(artifact.sha256 || "").trim().toLowerCase();
      if (!/^[a-f0-9]{64}$/.test(normalized.sha256)) {
        throw new Error(`KFD-3 surface ${surfaceId} distribution.artifacts[${index}].sha256 must be 64 lowercase hex characters`);
      }
    }
    return normalized;
  });
  return {
    ...distribution,
    registrar,
    tasks,
    artifacts,
  };
}

function normalizeRegistrySurface(entry) {
  if (!entry?.distribution) return entry;
  return {
    ...entry,
    distribution: normalizeKfd3DistributionDeclaration(entry.distribution, { surfaceId: entry.id || "surface" }),
  };
}

function stableId(value) {
  return String(value || "")
    .toLowerCase()
    .replace(/^@/, "")
    .replace(/[^a-z0-9._/-]+/g, "-")
    .replace(/\/+/g, "/")
    .replace(/^-+|-+$/g, "") || "surface";
}

function surface({ id, kind, name, sourcePath = "", artifactPath = "", evidencePath = "", detectionMethod, policy = {}, facts = {} }) {
  return {
    id,
    kind,
    name: name || id,
    visibility: "public",
    participantFacing: true,
    state: "detected",
    sourcePath,
    artifactPath: artifactPath || sourcePath,
    evidencePath: evidencePath || sourcePath,
    detectionMethod,
    policy,
    facts,
  };
}

function listFilesRecursive(root, relDir, predicate = () => true) {
  const absoluteDir = path.join(root, relDir);
  if (!fs.existsSync(absoluteDir)) return [];
  const out = [];
  const visit = (dir) => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const absolutePath = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        visit(absolutePath);
      } else if (entry.isFile()) {
        const relPath = path.relative(root, absolutePath).replace(/\\/g, "/");
        if (predicate(relPath, entry.name)) out.push(relPath);
      }
    }
  };
  visit(absoluteDir);
  return out.sort();
}

function detectNodeApiSurfaces({ cwd, packageJson = undefined } = {}) {
  const pkgPath = path.join(cwd, "package.json");
  const pkg = packageJson || readJsonFile(pkgPath, {});
  if (!pkg.name && !pkg.exports && !pkg.main && !pkg.types) return [];
  const entries = [];
  for (const [specifier, target] of Object.entries(pkg.exports || {})) {
    if (specifier.startsWith("./site/") || specifier === "./package.json") continue;
    const targetPath = typeof target === "string" ? target.replace(/^\.\//, "") : "";
    entries.push(surface({
      id: `node-api:${stableId(specifier === "." ? pkg.name : `${pkg.name}/${specifier.replace(/^\.\//, "")}`)}`,
      kind: "node-api",
      name: specifier === "." ? pkg.name : `${pkg.name}/${specifier.replace(/^\.\//, "")}`,
      sourcePath: targetPath || "package.json",
      detectionMethod: "package.json#exports",
      facts: { packageName: pkg.name || "", export: specifier, target },
    }));
  }
  for (const [field, kind] of [["main", "main"], ["types", "types"]]) {
    if (!pkg[field]) continue;
    entries.push(surface({
      id: `node-api:${kind}:${stableId(pkg[field])}`,
      kind: "node-api",
      name: `${pkg.name || "package"} ${kind}`,
      sourcePath: String(pkg[field]).replace(/^\.\//, ""),
      detectionMethod: `package.json#${field}`,
      facts: { packageName: pkg.name || "", field, target: pkg[field] },
    }));
  }
  return entries;
}

function detectCliSurfaces({ cwd, packageJson = undefined } = {}) {
  const pkg = packageJson || readJsonFile(path.join(cwd, "package.json"), {});
  const entries = [];
  const bins = typeof pkg.bin === "string"
    ? [[pkg.name || "cli", pkg.bin]]
    : Object.entries(pkg.bin || {});
  for (const [name, target] of bins) {
    entries.push(surface({
      id: `cli:${stableId(name)}`,
      kind: "cli",
      name,
      sourcePath: String(target).replace(/^\.\//, ""),
      detectionMethod: "package.json#bin",
      facts: { packageName: pkg.name || "", binName: name, target },
    }));
  }
  for (const relPath of listFilesRecursive(cwd, "bin", (relPath) => /\.m?js$|\.c?js$|\.sh$|\.exe$/.test(relPath))) {
    const name = path.basename(relPath).replace(/\.(mjs|cjs|js|sh|exe)$/i, "");
    if (entries.some((entry) => entry.sourcePath === relPath)) continue;
    entries.push(surface({
      id: `cli:${stableId(name)}`,
      kind: "cli",
      name,
      sourcePath: relPath,
      detectionMethod: "bin-directory",
      facts: { path: relPath },
    }));
  }
  return entries;
}

function parseMetadata(text) {
  const metadata = {};
  for (const line of String(text || "").split(/\r?\n/)) {
    const match = line.match(/^([A-Za-z0-9_.-]+):\s*(.*)$/);
    if (match) metadata[match[1].toLowerCase()] = match[2].trim();
  }
  return metadata;
}

function parseEntryPoints(text) {
  const points = [];
  let group = "";
  for (const rawLine of String(text || "").split(/\r?\n/)) {
    const line = rawLine.trim();
    if (!line || line.startsWith("#")) continue;
    const groupMatch = line.match(/^\[([^\]]+)\]$/);
    if (groupMatch) {
      group = groupMatch[1];
      continue;
    }
    const entryMatch = line.match(/^([^=]+)=\s*(.+)$/);
    if (entryMatch) {
      points.push({ group, name: entryMatch[1].trim(), target: entryMatch[2].trim() });
    }
  }
  return points;
}

function distInfoDirs(root) {
  if (!fs.existsSync(root)) return [];
  return fs.readdirSync(root, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && entry.name.endsWith(".dist-info"))
    .map((entry) => path.join(root, entry.name))
    .sort();
}

function detectPythonWheelSurfaces({ cwd, artifactPath = "" } = {}) {
  const root = path.resolve(cwd, artifactPath || ".");
  const entries = [];
  for (const infoDir of distInfoDirs(root)) {
    const relInfoDir = path.relative(cwd, infoDir).replace(/\\/g, "/") || path.basename(infoDir);
    const metadata = parseMetadata(readText(path.join(infoDir, "METADATA")));
    const recordText = readText(path.join(infoDir, "RECORD"));
    const entryPoints = parseEntryPoints(readText(path.join(infoDir, "entry_points.txt")));
    const topLevelText = readText(path.join(infoDir, "top_level.txt"));
    const packageName = metadata.name || path.basename(infoDir).replace(/\.dist-info$/, "");
    const topLevelPackages = [
      ...topLevelText.split(/\r?\n/).map((line) => line.trim()).filter(Boolean),
      ...recordText.split(/\r?\n/).map((line) => line.split(",")[0]).filter(Boolean)
        .map((recordPath) => recordPath.split(/[\\/]/)[0])
        .filter((segment) => segment && !segment.endsWith(".dist-info") && /^[A-Za-z_][A-Za-z0-9_]*$/.test(segment)),
    ];
    for (const moduleName of [...new Set(topLevelPackages)].sort()) {
      entries.push(surface({
        id: `python-api:${stableId(packageName)}:${stableId(moduleName)}`,
        kind: "python-api",
        name: `${packageName}:${moduleName}`,
        sourcePath: relInfoDir,
        artifactPath: relInfoDir,
        detectionMethod: "wheel-dist-info",
        policy: { publicApiPolicy: "top-level-package-metadata" },
        facts: { packageName, version: metadata.version || "", moduleName },
      }));
    }
    for (const point of entryPoints) {
      entries.push(surface({
        id: `cli:${stableId(packageName)}:${stableId(point.name)}`,
        kind: "cli",
        name: point.name,
        sourcePath: `${relInfoDir}/entry_points.txt`,
        artifactPath: `${relInfoDir}/entry_points.txt`,
        detectionMethod: "wheel-entry-points",
        facts: { packageName, version: metadata.version || "", entryPointGroup: point.group, target: point.target },
      }));
    }
  }
  return entries;
}

function detectBinarySurfaces({ cwd, artifactPath = "" } = {}) {
  const roots = [artifactPath, "dist", "build", "target/release"].filter(Boolean);
  const seen = new Set();
  const entries = [];
  for (const relRoot of roots) {
    for (const relPath of listFilesRecursive(cwd, relRoot, (candidate, name) => {
      return /\.(exe|dll|dylib|so|a|lib|zip|tar\.gz|tgz)$/i.test(candidate) || (!name.includes(".") && candidate.includes("/"));
    })) {
      if (seen.has(relPath)) continue;
      seen.add(relPath);
      entries.push(surface({
        id: `binary:${stableId(relPath)}`,
        kind: "binary",
        name: path.basename(relPath),
        sourcePath: relPath,
        artifactPath: relPath,
        detectionMethod: "artifact-path-scan",
        facts: { path: relPath, sha256: sha256File(path.join(cwd, relPath)) },
      }));
    }
  }
  return entries;
}

function detectDocumentationSurfaces({ cwd } = {}) {
  return [
    ...listFilesRecursive(cwd, "docs", (relPath) => relPath.endsWith(".md")),
    "README.md",
    "AGENTS.md",
  ]
    .filter((relPath) => fs.existsSync(path.join(cwd, relPath)))
    .map((relPath) => surface({
      id: `doc:${stableId(relPath)}`,
      kind: "documentation",
      name: relPath,
      sourcePath: relPath,
      detectionMethod: "documentation-scan",
      facts: { path: relPath, sha256: sha256File(path.join(cwd, relPath)) },
    }));
}

function detectSiteBundleSurfaces({ cwd } = {}) {
  return listFilesRecursive(cwd, "dist/site", (relPath) => relPath.endsWith(".json"))
    .map((relPath) => surface({
      id: `site-bundle:${stableId(relPath)}`,
      kind: "site-bundle",
      name: relPath,
      sourcePath: relPath,
      artifactPath: relPath,
      detectionMethod: "buildchain-site-bundle",
      facts: { path: relPath, sha256: sha256File(path.join(cwd, relPath)) },
    }));
}

function uniqueSurfaces(entries) {
  const byId = new Map();
  for (const entry of entries) {
    if (!entry?.id || byId.has(entry.id)) continue;
    byId.set(entry.id, entry);
  }
  return [...byId.values()].sort((a, b) => a.id.localeCompare(b.id));
}

export function detectKfd3Surfaces({ cwd = process.cwd(), kinds = [], artifactPath = "" } = {}) {
  const resolvedCwd = path.resolve(cwd);
  const selectedKinds = normalizeKinds(kinds);
  const packageJson = readJsonFile(path.join(resolvedCwd, "package.json"), {});
  const detectedAt = process.env.BUILDCHAIN_KFD3_DETECTED_AT || process.env.BUILDCHAIN_SURFACE_GENERATED_AT || new Date().toISOString();
  const surfaces = [];
  if (selectedKinds.includes("node-api")) surfaces.push(...detectNodeApiSurfaces({ cwd: resolvedCwd, packageJson }));
  if (selectedKinds.includes("python-api")) surfaces.push(...detectPythonWheelSurfaces({ cwd: resolvedCwd, artifactPath }));
  if (selectedKinds.includes("cli")) surfaces.push(...detectCliSurfaces({ cwd: resolvedCwd, packageJson }));
  if (selectedKinds.includes("binary")) surfaces.push(...detectBinarySurfaces({ cwd: resolvedCwd, artifactPath }));
  if (selectedKinds.includes("documentation")) surfaces.push(...detectDocumentationSurfaces({ cwd: resolvedCwd }));
  if (selectedKinds.includes("site-bundle")) surfaces.push(...detectSiteBundleSurfaces({ cwd: resolvedCwd }));
  const detected = uniqueSurfaces(surfaces);
  return {
    schemaVersion: 1,
    contract: KFD3_SURFACE_DETECTION_CONTRACT,
    cwd: resolvedCwd,
    artifactPath,
    detectedAt,
    kinds: selectedKinds,
    summary: {
      surfaceCount: detected.length,
      byKind: Object.fromEntries(selectedKinds.map((kind) => [kind, detected.filter((entry) => entry.kind === kind).length])),
    },
    surfaces: detected,
  };
}

function resolveRegistryPath(cwd, registryPath) {
  return registryPath || resolveKfd3SurfaceRegistryPath(cwd);
}

export function readKfd3SurfaceRegistry({ cwd = process.cwd(), registryPath = "" } = {}) {
  const effectiveRegistryPath = resolveRegistryPath(cwd, registryPath);
  const filePath = path.resolve(cwd, effectiveRegistryPath);
  const registry = readJsonFile(filePath, null);
  if (!registry) {
    return {
      schemaVersion: 1,
      contract: KFD3_SURFACE_REGISTRY_CONTRACT,
      product: {},
      registryPath: effectiveRegistryPath,
      surfaces: [],
    };
  }
  return {
    schemaVersion: registry.schemaVersion || 1,
    contract: registry.contract || KFD3_SURFACE_REGISTRY_CONTRACT,
    product: registry.product || {},
    registryPath: registry.registryPath || effectiveRegistryPath,
    surfaces: Array.isArray(registry.surfaces) ? registry.surfaces.map(normalizeRegistrySurface) : [],
    policy: registry.policy || {},
  };
}

export function writeKfd3SurfaceRegistry({ cwd = process.cwd(), registryPath = "", registry }) {
  const effectiveRegistryPath = resolveRegistryPath(cwd, registryPath);
  const next = {
    schemaVersion: 1,
    contract: KFD3_SURFACE_REGISTRY_CONTRACT,
    product: registry.product || {},
    registryPath: effectiveRegistryPath,
    surfaces: uniqueSurfaces(registry.surfaces || []).map((entry) => ({
      ...normalizeRegistrySurface(entry),
      state: entry.state || "declared",
      declaration: entry.declaration || {
        owner: "product",
        source: "buildchain kfd 3 register",
      },
    })),
    policy: registry.policy || {
      detectedButUnregistered: "warn",
      declaredButMissing: "fail",
    },
  };
  writeJsonFile(path.resolve(cwd, effectiveRegistryPath), next);
  return next;
}

export function registerKfd3Surfaces({
  cwd = process.cwd(),
  registryPath = "",
  kinds = [],
  artifactPath = "",
  product = {},
} = {}) {
  const detection = detectKfd3Surfaces({ cwd, kinds, artifactPath });
  const registry = readKfd3SurfaceRegistry({ cwd, registryPath });
  const existing = new Map((registry.surfaces || []).map((entry) => [entry.id, entry]));
  for (const detected of detection.surfaces) {
    existing.set(detected.id, {
      ...detected,
      ...(existing.get(detected.id) || {}),
      id: detected.id,
      kind: detected.kind,
      name: detected.name,
      state: existing.get(detected.id)?.state || "declared",
      sourcePath: detected.sourcePath,
      artifactPath: detected.artifactPath,
      evidencePath: detected.evidencePath,
      detectionMethod: detected.detectionMethod,
      facts: detected.facts,
    });
  }
  const next = writeKfd3SurfaceRegistry({
    cwd,
    registryPath,
    registry: {
      ...registry,
      product: { ...registry.product, ...product },
      surfaces: [...existing.values()],
    },
  });
  return {
    schemaVersion: 1,
    contract: "kungfu-buildchain-kfd-3-surface-register",
    registryPath,
    registeredCount: detection.surfaces.length,
    registrySurfaceCount: next.surfaces.length,
    detection,
    registry: next,
  };
}

export function auditKfd3Surfaces({
  cwd = process.cwd(),
  registryPath = "",
  kinds = [],
  artifactPath = "",
} = {}) {
  const detection = detectKfd3Surfaces({ cwd, kinds, artifactPath });
  const registry = readKfd3SurfaceRegistry({ cwd, registryPath });
  const detectedIds = new Set(detection.surfaces.map((entry) => entry.id));
  const declaredIds = new Set(registry.surfaces.map((entry) => entry.id));
  const detectedButUnregistered = detection.surfaces.filter((entry) => !declaredIds.has(entry.id));
  const declaredButMissing = registry.surfaces.filter((entry) => !detectedIds.has(entry.id));
  const enforced = registry.surfaces.filter((entry) => entry.state === "enforced" || entry.enforcement === "enforced");
  const issues = [
    ...detectedButUnregistered.map((entry) => ({
      level: "warning",
      code: "detected-unregistered",
      surfaceId: entry.id,
      message: `Detected public surface is not declared: ${entry.id}`,
    })),
    ...declaredButMissing.map((entry) => ({
      level: "error",
      code: "declared-missing",
      surfaceId: entry.id,
      message: `Declared public surface was not detected: ${entry.id}`,
    })),
  ];
  return {
    schemaVersion: 1,
    contract: KFD3_SURFACE_AUDIT_CONTRACT,
    ok: issues.every((issue) => issue.level !== "error"),
    status: issues.some((issue) => issue.level === "error") ? "failed" : detectedButUnregistered.length ? "partial" : "passed",
    registryPath,
    detection,
    registry,
    summary: {
      detected: detection.surfaces.length,
      declared: registry.surfaces.length,
      enforced: enforced.length,
      detectedButUnregistered: detectedButUnregistered.length,
      declaredButMissing: declaredButMissing.length,
    },
    states: {
      detected: detection.surfaces,
      declared: registry.surfaces,
      enforced,
    },
    comparison: {
      detectedButUnregistered,
      declaredButMissing,
    },
    issues,
  };
}

export function createKfd3SurfaceWitness({
  cwd = process.cwd(),
  registryPath = "",
  kind = "prebuild",
  sourceSha = "",
  artifactPath = "",
} = {}) {
  const audit = auditKfd3Surfaces({ cwd, registryPath, artifactPath });
  const registryDigest = `sha256:${sha256Json(audit.registry)}`;
  const collaborationInterface = {
    schemaVersion: 1,
    contract: KFD3_SURFACE_REGISTRY_CONTRACT,
    product: audit.registry.product,
    surfaces: audit.registry.surfaces,
    detectedSurfaces: audit.detection.surfaces,
    audit,
  };
  return {
    schemaVersion: 1,
    id: audit.registry.product?.id || audit.registry.product?.name || "kfd-3-surface-registry",
    standard: "kfd-3",
    witnessKind: kind,
    supportLevel: audit.status === "passed" ? "release" : "declared",
    source: {
      cwd: path.resolve(cwd),
      sourceSha,
      registryPath,
      registryDigest,
    },
    sourceRegistry: {
      id: audit.registry.product?.id || audit.registry.product?.name || "product-kfd-3-surface-registry",
      path: registryPath,
      sha256: sha256File(path.resolve(cwd, registryPath)),
    },
    collaborationInterfaceDigest: `sha256:${sha256Json(collaborationInterface)}`,
    collaborationInterface,
    auditBoundary: {
      mode: audit.status === "passed" ? "closed-world" : "declared-boundary",
      scope: "KFD-3 registered product public surfaces detected by Buildchain",
      detectedButUnregisteredPolicy: "warn",
      declaredButMissingPolicy: "fail",
    },
    residualRisk: audit.comparison.detectedButUnregistered.map((entry) => ({
      surfaceId: entry.id,
      riskType: "unregistered-detected-surface",
      trustImpact: "manual-review-required",
      machineProvability: "machine-detected",
      agentAction: "register-or-exempt-surface",
      message: `Detected public surface is not yet declared: ${entry.id}`,
    })),
    responsibility: {
      registryFactsOwner: "product",
      artifactVerificationOwner: "Buildchain KFD-3 surface audit",
      releasePassportProofOwner: "Buildchain",
    },
  };
}

async function readJsonLocation(location) {
  if (!location) return null;
  if (/^https?:\/\//.test(location)) {
    const response = await fetch(location);
    if (!response.ok) {
      throw new Error(`failed to fetch ${location}: HTTP ${response.status}`);
    }
    return response.json();
  }
  return readJsonFile(path.resolve(location), null);
}

function kfd2TrustForCapability(passport, surfaceId) {
  const claims = passport?.["kfd-2"]?.claims || passport?.kfd2?.claims || [];
  const related = claims.find((claim) => {
    const haystack = JSON.stringify(claim);
    return haystack.includes(surfaceId) || haystack.includes("kfd-3");
  });
  if (!related) {
    return {
      status: "unknown",
      trustImpact: "passport-claim-not-found",
      residualRisk: [],
    };
  }
  return {
    status: related.verification?.result || related.releaseStatus || "declared",
    trustImpact: related.trustProof?.releaseStatus || related.verification?.result || "review",
    residualRisk: related.residualRisk || related.trustProof?.residualRisk || [],
    claimId: related.id || "",
  };
}

function capabilitiesFromRegistry({ registry, audit, passport = null }) {
  const detectedById = new Map((audit?.detection?.surfaces || []).map((entry) => [entry.id, entry]));
  return (registry.surfaces || []).map((entry) => {
    const detected = detectedById.get(entry.id);
    return {
      id: entry.id,
      kind: entry.kind,
      name: entry.name,
      state: entry.state || "declared",
      detected: Boolean(detected),
      enforced: entry.state === "enforced" || entry.enforcement === "enforced",
      sourcePath: entry.sourcePath,
      artifactPath: entry.artifactPath,
      evidencePath: entry.evidencePath,
      kfd1Basis: {
        registryPath: registry.registryPath || KFD3_DEFAULT_REGISTRY_PATH,
        sourcePath: entry.sourcePath,
        artifactPath: entry.artifactPath,
        digest: `sha256:${sha256Json(entry)}`,
      },
      kfd2Trust: kfd2TrustForCapability(passport, entry.id),
      residualRisk: detected ? [] : [{
        riskType: "declared-surface-not-detected",
        trustImpact: "verification-required",
        machineProvability: "machine-detected",
        agentAction: "run-buildchain-kfd-3-audit",
      }],
    };
  });
}

export async function queryKfd3Capabilities({
  cwd = process.cwd(),
  product = "",
  registryPath = "",
  passportLocation = "",
  artifactPath = "",
} = {}) {
  const passport = await readJsonLocation(passportLocation);
  if (passport) {
    const kfd3 = passport["kfd-3"] || passport.kfd3 || {};
    const interfaces = Array.isArray(kfd3.collaborationInterfaces)
      ? kfd3.collaborationInterfaces
      : [kfd3.collaborationInterface].filter(Boolean);
    const surfaces = interfaces.flatMap((entry) => entry?.surfaces || entry?.declaredSurfaces || []);
    return {
      schemaVersion: 1,
      contract: KFD3_CAPABILITY_QUERY_CONTRACT,
      product: product || passport.product?.name || passport.package?.name || "release-passport",
      source: { type: "release-passport", location: passportLocation },
      release: passport.release || {},
      capabilities: surfaces.map((entry) => ({
        id: entry.id || entry.name,
        kind: entry.kind || "surface",
        name: entry.name || entry.id,
        state: entry.state || "declared",
        detected: true,
        enforced: kfd3.releaseStatus === "enforced",
        kfd1Basis: { sourcePath: entry.sourcePath || "", artifactPath: entry.artifactPath || "", digest: entry.digest || "" },
        kfd2Trust: kfd2TrustForCapability(passport, entry.id || entry.name || ""),
        residualRisk: entry.residualRisk || [],
      })),
      kfd: {
        kfd1: passport["kfd-1"]?.result || passport.kfd1?.result || "unknown",
        kfd2: passport["kfd-2"]?.result || passport.kfd2?.result || "unknown",
        kfd3: kfd3.result || kfd3.releaseStatus || "unknown",
      },
    };
  }

  const effectiveRegistryPath = resolveRegistryPath(cwd, registryPath);
  const registry = readKfd3SurfaceRegistry({ cwd, registryPath: effectiveRegistryPath });
  const hasRegistry = fs.existsSync(path.resolve(cwd, effectiveRegistryPath));
  const audit = hasRegistry ? auditKfd3Surfaces({ cwd, registryPath: effectiveRegistryPath, artifactPath }) : null;
  if (hasRegistry) {
    return {
      schemaVersion: 1,
      contract: KFD3_CAPABILITY_QUERY_CONTRACT,
      product: product || registry.product?.name || registry.product?.id || "local-product",
      source: { type: "surface-registry", path: effectiveRegistryPath },
      status: audit.status,
      summary: audit.summary,
      capabilities: capabilitiesFromRegistry({ registry, audit }),
      kfd: {
        kfd1: "registry-facts",
        kfd2: passport ? "passport-trust" : "not-attached",
        kfd3: audit.status,
      },
    };
  }

  if (!product || product === "buildchain" || product === "@kungfu-tech/buildchain") {
    const claimsPath = path.join(cwd, "dist/site/kfd-claims.json");
    const claims = readJsonFile(claimsPath, null);
    if (claims?.collaborationSurfaces) {
      const registryFromClaims = {
        product: claims.product || { name: "Buildchain" },
        registryPath: "dist/site/kfd-claims.json",
        surfaces: [
          ...Object.values(claims.collaborationSurfaces.groups || {}).flat(),
          ...(claims.collaborationSurfaces.additionalSurfaces || []),
        ],
      };
      return {
        schemaVersion: 1,
        contract: KFD3_CAPABILITY_QUERY_CONTRACT,
        product: "Buildchain",
        source: { type: "buildchain-site-kfd-claims", path: "dist/site/kfd-claims.json" },
        status: claims.publicSurfaceReverseAudit?.status || "declared",
        summary: {
          declared: registryFromClaims.surfaces.length,
          publicSurfaceCount: claims.collaborationSurfaces.publicSurfaceCount,
        },
        capabilities: capabilitiesFromRegistry({ registry: registryFromClaims, audit: { detection: { surfaces: registryFromClaims.surfaces } } }),
        kfd: {
          kfd1: "self-contract-registry",
          kfd2: "public-claim-registry",
          kfd3: claims.publicSurfaceReverseAudit?.status || "declared",
        },
      };
    }
  }

  throw new Error(`no KFD-3 registry, passport, or known product facts found for ${product || "local product"}`);
}

